function escapeHtml(str) {
  if (!str) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// ==========================================================================
// ENHANCED ARABIC NORMALIZATION
// Handles: harakat, hamzat forms, alef variants, Egyptian dialect substitutions,
// common prefix/suffix stripping (al-, wa-, bi-, etc.), ta-marbouta
// ==========================================================================
function normalizeArabic(text) {
  if (!text) return '';
  return String(text)
    // Alef variants
    .replace(/[أإآٱاٲٳ]/g, 'ا')
    // Ya variants
    .replace(/[ىئ]/g, 'ي')
    // Ta-marbouta → ha
    .replace(/ة/g, 'ه')
    // Waw variants
    .replace(/[ؤۇۈ]/g, 'و')
    // Remove all diacritics (harakat, shadda, sukun, maddah, etc.)
    .replace(/[\u064B-\u065F\u0670\u0610-\u061A]/g, '')
    // Tatweel (kashida)
    .replace(/\u0640/g, '')
    // Egyptian dialect: ق often pronounced/written as أ → normalize both to q base
    // Don't collapse ق/ء since they're distinct — but strip leading ال
    .replace(/^ال/g, '')
    // Normalize space sequences
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .trim();
}

// Strip common Arabic prefixes AND suffixes for root matching
function arabicStem(word) {
  let w = normalizeArabic(word);
  // Strip prefixes: و ف ب ل ك ال
  w = w.replace(/^(وال|فال|بال|لل|ال|و|ف|ب|ل|ك)/, '');
  // Strip suffixes: ها هم هن كم ون ين ات ه
  w = w.replace(/(ها|هم|هن|كم|ون|ين|ات|ه|ي|ك|ا|وا)$/, '');
  return w.length > 1 ? w : normalizeArabic(word);
}

// ==========================================================================
// ARABIC ATTACHED / SEPARATED PREPOSITIONS & DIALECT EQUIVALENCE GENERATOR
// e.g. "جايلك" <-> "جاي لك", "راجعلك" <-> "راجع لك", "مفيش" <-> "ما فيش"
// ==========================================================================
const ARABIC_ATTACHED_SUFFIXES = [
  'لك', 'لي', 'لنا', 'لكم', 'له', 'لها', 'لهم',
  'بيك', 'بي', 'بينا', 'بيكم', 'بيه', 'بيها', 'بيهم',
  'بك', 'بنا', 'به', 'بها', 'بهم'
];

const ARABIC_DIALECT_PAIRS = [
  ['مفيش', 'ما فيش'],
  ['معنديش', 'ما عنديش'],
  ['متخافش', 'ما تخافش'],
  ['متسبنيش', 'ما تسيبنيش'],
  ['متنساش', 'ما تنساش'],
  ['منبقاش', 'ما نبقاش'],
  ['معرفش', 'ما اعرفش'],
  ['مبقتش', 'ما بقتش'],
  ['علشان', 'عشان'],
  ['علشانك', 'عشانك'],
  ['علشان لك', 'عشانك'],
  ['عشان لك', 'عشانك'],
  ['كتير', 'كثير'],
  ['دلوقتي', 'دلوقت'],
  ['ازاي', 'إزاي'],
  ['كده', 'كدة']
];

function generateArabicSpellingVariants(text) {
  if (!text) return [];
  const raw = String(text).trim();
  if (!raw) return [];
  
  const variants = new Set();
  const words = raw.split(/\s+/).filter(Boolean);
  
  // 1. Separate attached enclitic suffixes (e.g. "جايلك" -> "جاي لك", "راجعلك" -> "راجع لك")
  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    for (let sIdx = 0; sIdx < ARABIC_ATTACHED_SUFFIXES.length; sIdx++) {
      const suf = ARABIC_ATTACHED_SUFFIXES[sIdx];
      if (w.length > suf.length + 1 && w.endsWith(suf)) {
        const base = w.slice(0, -suf.length);
        if (base.length >= 2) {
          const newWords = [...words];
          newWords[i] = base + ' ' + suf;
          const variant = newWords.join(' ');
          if (variant !== raw) variants.add(variant);
        }
      }
    }
  }

  // 2. Combine separated enclitic suffixes (e.g. "جاي لك" -> "جايلك", "راجع لك" -> "راجعلك")
  for (let i = 0; i < words.length - 1; i++) {
    const w1 = words[i];
    const w2 = words[i + 1];
    if (ARABIC_ATTACHED_SUFFIXES.includes(w2) && w1.length >= 2) {
      const newWords = [...words];
      newWords[i] = w1 + w2;
      newWords.splice(i + 1, 1);
      const variant = newWords.join(' ');
      if (variant !== raw) variants.add(variant);
    }
  }

  // 3. Dialect replacements (e.g. "مفيش" <-> "ما فيش", "علشان" <-> "عشان")
  for (let i = 0; i < ARABIC_DIALECT_PAIRS.length; i++) {
    const [p1, p2] = ARABIC_DIALECT_PAIRS[i];
    if (raw.includes(p1)) {
      variants.add(raw.split(p1).join(p2));
    }
    if (raw.includes(p2)) {
      variants.add(raw.split(p2).join(p1));
    }
  }

  return Array.from(variants);
}

function francoToArabic(text) {
  if (!text) return '';
  let s = String(text).trim();
  if (!s || !/[a-z0-9]/i.test(s)) return '';

  let words = s.split(/\s+/);
  let translated = words.map(w => {
    if (!/[a-z0-9]/i.test(w)) return w;
    let tw = w.toLowerCase();
    FRANCO_MAPPINGS.forEach(([f, a]) => {
      tw = tw.split(f).join(a);
    });
    return tw;
  });
  return translated.join(' ');
}

// Extract Arabic consonant skeleton for a single word
function getWordConsonantSkeleton(word) {
  if (!word) return '';
  return normalizeArabic(word)
    .replace(/[أإآءاوىهة]/g, '')
    .replace(/^(وال|فال|بال|لل|ال|و|ف|ب|ل|ك|عا)/g, '')
    .trim();
}

// Extract Arabic consonant skeleton (removes weak vowels & silent letters)
function extractArabicConsonantSkeleton(text) {
  if (!text) return '';
  const words = normalizeArabic(text).split(/\s+/).filter(Boolean);
  return words.map(getWordConsonantSkeleton).filter(Boolean).join('');
}

function convertFrancoWordPhonetic(w) {
  let tw = String(w).toLowerCase();
  
  tw = tw.replace(/sh/g, 'ش')
         .replace(/kh/g, 'خ')
         .replace(/th/g, 'ث')
         .replace(/gh/g, 'غ')
         .replace(/aa/g, 'ا')
         .replace(/ee/g, 'ي')
         .replace(/oo/g, 'و')
         .replace(/ou/g, 'و')
         .replace(/ei/g, 'ي')
         .replace(/3/g, 'ع')
         .replace(/7/g, 'ح')
         .replace(/5/g, 'خ')
         .replace(/2/g, 'أ')
         .replace(/6/g, 'ط')
         .replace(/8/g, 'ه')
         .replace(/9/g, 'ق');

  let res = '';
  for (let i = 0; i < tw.length; i++) {
    let char = tw[i];
    if (char === 'a') {
      if (i === 0 || i === tw.length - 1) res += 'ا';
      // skip interior single 'a' (short vowel fatha)
    } else if (char === 'e' || char === 'i') {
      if (i === tw.length - 1) res += 'ي';
      // skip interior single 'e'/'i' (short vowel kasra)
    } else if (char === 'o' || char === 'u') {
      res += 'و';
    } else {
      switch (char) {
        case 'b': case 'p': res += 'ب'; break;
        case 't': res += 'ت'; break;
        case 'g': res += 'ج'; break;
        case 'd': res += 'د'; break;
        case 'r': res += 'ر'; break;
        case 'z': res += 'ز'; break;
        case 's': res += 'س'; break;
        case 'f': case 'v': res += 'ف'; break;
        case 'k': case 'c': res += 'ك'; break;
        case 'q': res += 'ق'; break;
        case 'l': res += 'ل'; break;
        case 'm': res += 'م'; break;
        case 'n': res += 'ن'; break;
        case 'h': res += 'ه'; break;
        case 'w': res += 'و'; break;
        case 'y': res += 'ي'; break;
        default:
          if (/[\u0600-\u06FF]/.test(char)) res += char;
          break;
      }
    }
  }
  return res || w;
}

function francoToArabicVariants(text) {
  if (!text) return [];
  let s = String(text).trim();
  if (!s || !/[a-z0-9]/i.test(s)) return [];

  const rawWords = s.toLowerCase().split(/\s+/).filter(Boolean);

  // Variant 1: Smart Dictionary + Vowel-Sensitive Phonetic
  const smartWords = rawWords.map(w => {
    if (typeof FRANCO_DICTIONARY !== 'undefined' && FRANCO_DICTIONARY[w]) return FRANCO_DICTIONARY[w];
    const cleanW = w.replace(/^(el|al|l)/, '');
    if (typeof FRANCO_DICTIONARY !== 'undefined' && FRANCO_DICTIONARY[cleanW]) return (w.startsWith('el') || w.startsWith('al') ? 'ال' : '') + FRANCO_DICTIONARY[cleanW];
    return convertFrancoWordPhonetic(w);
  });
  const vSmart = normalizeArabic(smartWords.join(' '));

  // Variant 2: Literal legacy transliteration
  const vLiteral = normalizeArabic(francoToArabic(s));

  const variants = [vSmart, vLiteral].filter(Boolean);
  return Array.from(new Set(variants));
}

