  function closeAllPopovers(exceptPopover = null) {
    if (els.popoverStyle && els.popoverStyle !== exceptPopover) {
      els.popoverStyle.classList.add('hidden');
    }
    if (els.popoverCast && els.popoverCast !== exceptPopover) {
      els.popoverCast.classList.add('hidden');
    }
    if (els.popoverObsWs && els.popoverObsWs !== exceptPopover) {
      els.popoverObsWs.classList.add('hidden');
    }
    if (els.popoverInstall && els.popoverInstall !== exceptPopover) {
      els.popoverInstall.classList.add('hidden');
    }
    if (els.popoverBible && els.popoverBible !== exceptPopover) {
      els.popoverBible.classList.add('hidden');
      if (els.btnMenuBible) els.btnMenuBible.classList.remove('active');
    }
    if (els.popoverSlideJump && els.popoverSlideJump !== exceptPopover) {
      els.popoverSlideJump.classList.add('hidden');
    }
    const playlistPopover = document.getElementById('popover-playlist');
    if (playlistPopover && playlistPopover !== exceptPopover) {
      playlistPopover.classList.add('hidden');
    }
    const highlightPopover = document.getElementById('popover-highlight-color');
    if (highlightPopover && highlightPopover !== exceptPopover) {
      highlightPopover.classList.add('hidden');
    }
  }


  function setupNetworkSync() {
    window.addEventListener('online', () => {
      showToast('تم استعادة الاتصال بالإنترنت 🌐', 'info');
      if (typeof syncLiveState === 'function') {
        syncLiveState();
      }
    });

    window.addEventListener('offline', () => {
      showToast('أنت الآن في وضع عدم الاتصال (Offline) — كافة الترانيم والإعدادات متاحة محلياً!', 'warning');
    });
  }


  // =========================================================================
  // OBS STUDIO WEBSOCKET & SCENE CONTROLLER ENGINE
  // =========================================================================

  const OBS_PROFILES_STORAGE_KEY = 'sunday_school_obs_saved_connections';
  let activeQrMediaStream = null;
  let qrScanInterval = null;

  function getSavedObsProfiles() {
    try {
      const raw = localStorage.getItem(OBS_PROFILES_STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch(e) {}
    return [];
  }

  function saveObsProfiles(list) {
    try {
      localStorage.setItem(OBS_PROFILES_STORAGE_KEY, JSON.stringify(list));
    } catch(e) {}
  }

  function getLastConnectedObsInfo() {
    try {
      const raw = localStorage.getItem('sunday_school_obs_last_connected');
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && parsed.ip) return parsed;
      }
    } catch(e) {}

    const savedProfiles = getSavedObsProfiles();
    if (savedProfiles && savedProfiles.length > 0) {
      return savedProfiles[0];
    }
    return null;
  }

  function updateObsLastConnUI() {
    const banner = document.getElementById('obs-last-conn-bar');
    const infoEl = document.getElementById('obs-last-conn-info');
    const btnAction = document.getElementById('btn-obs-connect-last-action');
    const last = getLastConnectedObsInfo();

    if (!last || globalObsClient.isConnected) {
      if (banner) {
        banner.classList.add('hidden');
        banner.style.display = 'none';
      }
      if (btnAction) {
        btnAction.classList.add('hidden');
        btnAction.style.display = 'none';
      }
      return;
    }

    const displayText = (last.name ? `${last.name} (${last.ip}:${last.port})` : `${last.ip}:${last.port}`);
    if (infoEl) infoEl.textContent = displayText;

    if (banner) {
      banner.classList.remove('hidden');
      banner.style.display = 'flex';
    }
    if (btnAction) {
      btnAction.classList.remove('hidden');
      btnAction.style.display = 'inline-flex';
    }
  }

  function connectToLastObsServer() {
    const last = getLastConnectedObsInfo();
    if (!last || !last.ip) {
      showToast('لا يوجد خادم OBS محفوظ سابقاً');
      return;
    }

    const ipInput = document.getElementById('obs-ip-input');
    const portInput = document.getElementById('obs-port-input');
    const pwInput = document.getElementById('obs-pw-input');
    const nameInput = document.getElementById('obs-profile-name-input');

    if (ipInput) ipInput.value = last.ip || 'localhost';
    if (portInput) portInput.value = last.port || 4455;
    if (pwInput) pwInput.value = last.password || '';
    if (nameInput && last.name) nameInput.value = last.name;

    showToast(`جاري الاتصال بـ OBS (${last.ip}:${last.port})...`);
    globalObsClient.connect(last.ip, last.port || 4455, last.password || '');
  }

  // Initialize Global OBS WebSocket Client Instance
  const globalObsClient = new OBSWSClient({
    onStatusChange: (connected, message) => {
      if (connected) {
        try {
          const nameInput = document.getElementById('obs-profile-name-input');
          const profName = nameInput && nameInput.value.trim() ? nameInput.value.trim() : '';
          localStorage.setItem('sunday_school_obs_last_connected', JSON.stringify({
            name: profName,
            ip: globalObsClient.ip,
            port: globalObsClient.port,
            password: globalObsClient.password
          }));
        } catch(e) {}
      }
      updateObsUIStatus(connected, message);
    },
    onScenesUpdated: (scenes, currentProgramScene) => {
      renderObsScenesGrid(scenes, currentProgramScene);
    },
    onCurrentSceneChanged: (sceneName) => {
      updateObsActiveSceneDisplay(sceneName);
    },
    onTransitionsUpdated: (transitions, currentTransition) => {
      renderObsTransitionsList(transitions, currentTransition);
    }
  });

  window.globalObsClient = globalObsClient;

  function updateObsUIStatus(connected, message) {
    const headerDot = document.getElementById('obs-header-status-badge');
    const modalPill = document.getElementById('obs-modal-status-pill');
    const btnConnect = document.getElementById('btn-obs-connect');
    const btnDisconnect = document.getElementById('btn-obs-disconnect');
    const controlPanelBar = document.getElementById('obs-control-panel-scenes-bar');

    if (headerDot) {
      headerDot.className = 'obs-badge-dot ' + (connected ? 'connected' : (message && message.includes('جاري') ? 'connecting' : 'disconnected'));
    }

    if (modalPill) {
      modalPill.className = 'status-pill ' + (connected ? 'online' : 'offline');
      modalPill.innerHTML = `<i class="fa-solid fa-circle-${connected ? 'check' : 'dot'}"></i> ${escapeHtml(message || (connected ? 'متصل بـ OBS' : 'غير متصل'))}`;
    }

    const advPill = document.getElementById('obs-adv-status-pill');
    if (advPill) {
      advPill.className = 'status-pill ' + (connected ? 'online' : 'offline');
      advPill.innerHTML = `<i class="fa-solid fa-circle-${connected ? 'check' : 'dot'}"></i> ${escapeHtml(message || (connected ? 'متصل بـ OBS' : 'غير متصل'))}`;
    }

    if (btnConnect && btnDisconnect) {
      if (connected) {
        btnConnect.classList.add('hidden');
        btnDisconnect.classList.remove('hidden');
      } else {
        btnConnect.classList.remove('hidden');
        btnDisconnect.classList.add('hidden');
      }
    }

    const btnAdvConnect = document.getElementById('btn-obs-adv-connect');
    const btnAdvDisconnect = document.getElementById('btn-obs-adv-disconnect');
    if (btnAdvConnect && btnAdvDisconnect) {
      if (connected) {
        btnAdvConnect.classList.add('hidden');
        btnAdvDisconnect.classList.remove('hidden');
      } else {
        btnAdvConnect.classList.remove('hidden');
        btnAdvDisconnect.classList.add('hidden');
      }
    }

    // SHOW / HIDE CONTROL PANEL SCENES SWITCHER BAR UNDER SEARCH
    if (controlPanelBar) {
      if (connected) {
        controlPanelBar.classList.remove('hidden');
      } else {
        controlPanelBar.classList.add('hidden');
      }
    }

    if (!connected) {
      const activeSceneNameEl = document.getElementById('obs-active-scene-name');
      if (activeSceneNameEl) activeSceneNameEl.textContent = 'غير متصل بـ OBS';
      const barActiveTxt = document.getElementById('obs-bar-active-scene-txt');
      if (barActiveTxt) barActiveTxt.textContent = 'غير متصل';
    }

    updateObsLastConnUI();
  }

  function updateObsActiveSceneDisplay(sceneName) {
    const activeSceneNameEl = document.getElementById('obs-active-scene-name');
    if (activeSceneNameEl) {
      activeSceneNameEl.textContent = sceneName || 'بدون تحديد';
    }

    const barActiveTxt = document.getElementById('obs-bar-active-scene-txt');
    if (barActiveTxt) {
      barActiveTxt.textContent = sceneName || 'بدون تحديد';
    }

    // Toggle Previous Scene Button Management
    const btnTogglePrev = document.getElementById('btn-obs-toggle-prev-scene');
    const prevTxt = document.getElementById('obs-bar-prev-scene-txt');
    if (btnTogglePrev && prevTxt) {
      if (globalObsClient.previousProgramScene && globalObsClient.previousProgramScene !== sceneName) {
        btnTogglePrev.classList.remove('hidden');
        prevTxt.textContent = globalObsClient.previousProgramScene;
      } else {
        btnTogglePrev.classList.add('hidden');
      }
    }

    // 1. Highlight active scene card in Modal Grid
    const grid = document.getElementById('obs-scenes-grid');
    if (grid) {
      grid.querySelectorAll('.obs-scene-card').forEach(card => {
        const isCurrent = card.dataset.sceneName === sceneName;
        card.classList.toggle('active', isCurrent);
        const existingBadge = card.querySelector('.obs-scene-badge');
        if (isCurrent && !existingBadge) {
          const badge = document.createElement('span');
          badge.className = 'obs-scene-badge';
          badge.textContent = 'مباشر LIVE';
          card.appendChild(badge);
        } else if (!isCurrent && existingBadge) {
          existingBadge.remove();
        }
      });
    }

    // 2. Highlight active scene pill in Control Panel Bar
    const track = document.getElementById('obs-bar-scenes-track');
    if (track) {
      track.querySelectorAll('.obs-bar-scene-pill').forEach(pill => {
        const isCurrent = pill.dataset.sceneName === sceneName;
        pill.classList.toggle('active', isCurrent);
        const existingBadge = pill.querySelector('.scene-pill-badge');
        if (isCurrent && !existingBadge) {
          const badge = document.createElement('span');
          badge.className = 'scene-pill-badge';
          badge.textContent = 'LIVE';
          pill.appendChild(badge);
        } else if (!isCurrent && existingBadge) {
          existingBadge.remove();
        }
      });
    }
  }

  function renderObsScenesGrid(scenes, currentProgramScene) {
    const grid = document.getElementById('obs-scenes-grid');
    const countBadge = document.getElementById('obs-scenes-count-badge');
    const track = document.getElementById('obs-bar-scenes-track');

    if (countBadge) countBadge.textContent = (scenes && scenes.length) || 0;

    // 1. Render in Modal Grid
    if (grid) {
      if (!scenes || scenes.length === 0) {
        grid.innerHTML = `
          <div class="obs-scenes-empty">
            <i class="fa-solid fa-film"></i>
            <span>لم يتم العثور على مشاهد في OBS Studio</span>
          </div>
        `;
      } else {
        grid.innerHTML = scenes.map(sceneName => {
          const isCurrent = sceneName === currentProgramScene;
          return `
            <div class="obs-scene-card ${isCurrent ? 'active' : ''}" data-scene-name="${escapeHtml(sceneName)}" title="انقر للتبديل إلى ${escapeHtml(sceneName)}">
              <i class="fa-solid fa-video obs-scene-icon"></i>
              <span class="obs-scene-name">${escapeHtml(sceneName)}</span>
              ${isCurrent ? '<span class="obs-scene-badge">مباشر LIVE</span>' : ''}
            </div>
          `;
        }).join('');

        grid.querySelectorAll('.obs-scene-card').forEach(card => {
          card.addEventListener('click', () => {
            const sceneName = card.dataset.sceneName;
            if (sceneName && globalObsClient.isConnected) {
              globalObsClient.setCurrentScene(sceneName);
              showToast(`🎬 تم التبديل إلى مشهد "${sceneName}" في OBS!`);
            } else if (!globalObsClient.isConnected) {
              showToast('⚠️ يجب الاتصال بخادم OBS أولاً لتغيير المشاهد.');
            }
          });
        });
      }
    }

    // 2. Render in Control Panel Scenes Bar (Under Search Hero)
    if (track) {
      if (!scenes || scenes.length === 0) {
        track.innerHTML = '<span style="color:#94a3b8; font-size:0.8rem;">لا توجد مشاهد</span>';
      } else {
        track.innerHTML = scenes.map(sceneName => {
          const isCurrent = sceneName === currentProgramScene;
          return `
            <button type="button" class="obs-bar-scene-pill ${isCurrent ? 'active' : ''}" data-scene-name="${escapeHtml(sceneName)}" title="تبديل إلى ${escapeHtml(sceneName)}">
              <i class="fa-solid fa-clapperboard scene-pill-icon"></i>
              <span>${escapeHtml(sceneName)}</span>
              ${isCurrent ? '<span class="scene-pill-badge">LIVE</span>' : ''}
            </button>
          `;
        }).join('');

        track.querySelectorAll('.obs-bar-scene-pill').forEach(pill => {
          pill.addEventListener('click', () => {
            const sceneName = pill.dataset.sceneName;
            if (sceneName && globalObsClient.isConnected) {
              globalObsClient.setCurrentScene(sceneName);
              showToast(`🎬 تم التبديل إلى مشهد "${sceneName}" في OBS!`);
            }
          });
        });
      }
    }

    updateObsActiveSceneDisplay(currentProgramScene);
  }

  function renderObsTransitionsList(transitions, currentTransition) {
    const track = document.getElementById('obs-bar-transitions-track');
    const row = document.getElementById('obs-bar-transitions-row');
    const oldContainer = document.getElementById('obs-transitions-list');

    if (row) {
      row.style.display = (transitions && transitions.length > 0) ? 'flex' : 'none';
    }

    const htmlContent = (!transitions || transitions.length === 0)
      ? '<span style="color:#94a3b8; font-size:0.75rem;">لا توجد انتقالات</span>'
      : transitions.map(tName => {
          const isCurrent = tName === currentTransition;
          return `
            <button type="button" class="obs-bar-transition-pill ${isCurrent ? 'active' : ''}" data-trans-name="${escapeHtml(tName)}" title="تفعيل انتقال ${escapeHtml(tName)}">
              ${escapeHtml(tName)}
            </button>
          `;
        }).join('');

    if (track) {
      track.innerHTML = htmlContent;
      track.querySelectorAll('.obs-bar-transition-pill').forEach(btn => {
        btn.addEventListener('click', () => {
          const tName = btn.dataset.transName;
          if (tName && globalObsClient.isConnected) {
            globalObsClient.setTransition(tName);
            track.querySelectorAll('.obs-bar-transition-pill').forEach(b => b.classList.toggle('active', b.dataset.transName === tName));
            showToast(`⚡ تم تفعيل انتقال "${tName}" في OBS!`);
          }
        });
      });
    }

    if (oldContainer) {
      oldContainer.innerHTML = htmlContent;
    }
  }

  function renderSavedObsProfilesList() {
    const listEl = document.getElementById('obs-saved-profiles-list');
    if (!listEl) return;

    const profiles = getSavedObsProfiles();
    if (profiles.length === 0) {
      listEl.innerHTML = `
        <div style="text-align:center; padding:16px; color:#64748b; font-size:0.82rem;">
          <i class="fa-solid fa-bookmark" style="font-size:1.4rem; opacity:0.4; display:block; margin-bottom:4px;"></i>
          لا توجد خوادم محفوظة حتى الآن
        </div>
      `;
      return;
    }

    listEl.innerHTML = profiles.map(p => {
      const isActive = globalObsClient.isConnected && globalObsClient.ip === p.ip && String(globalObsClient.port) === String(p.port);
      return `
        <div class="obs-profile-item ${isActive ? 'active' : ''}" data-profile-id="${escapeHtml(p.id)}">
          <div class="profile-main-info">
            <span class="profile-name"><i class="fa-solid fa-server" style="color:#2563eb; margin-left:4px;"></i> ${escapeHtml(p.name)}</span>
            <span class="profile-address">${escapeHtml(p.ip)}:${escapeHtml(p.port)}</span>
          </div>
          <div class="profile-actions">
            <button type="button" class="btn btn-sm btn-primary btn-connect-profile" data-profile-id="${escapeHtml(p.id)}" style="font-size:0.75rem; padding:4px 8px;" title="اتصال بهذا الخادم">
              <i class="fa-solid fa-link"></i> اتصال
            </button>
            <button type="button" class="btn btn-sm btn-danger btn-delete-profile" data-profile-id="${escapeHtml(p.id)}" style="font-size:0.75rem; padding:4px 7px; border:none; cursor:pointer;" title="حذف الخادم">
              <i class="fa-solid fa-trash"></i>
            </button>
          </div>
        </div>
      `;
    }).join('');

    listEl.querySelectorAll('.btn-connect-profile').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.profileId;
        const profile = getSavedObsProfiles().find(p => p.id === id);
        if (profile) {
          const nameInput = document.getElementById('obs-profile-name-input');
          const ipInput = document.getElementById('obs-ip-input');
          const portInput = document.getElementById('obs-port-input');
          const pwInput = document.getElementById('obs-pw-input');

          if (nameInput) nameInput.value = profile.name || '';
          if (ipInput) ipInput.value = profile.ip || '';
          if (portInput) portInput.value = profile.port || 4455;
          if (pwInput) pwInput.value = profile.password || '';

          globalObsClient.connect(profile.ip, profile.port, profile.password);
        }
      });
    });

    listEl.querySelectorAll('.btn-delete-profile').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = btn.dataset.profileId;
        const updated = getSavedObsProfiles().filter(p => p.id !== id);
        saveObsProfiles(updated);
        renderSavedObsProfilesList();
        showToast('تم حذف الخادم من القائمة.');
      });
    });
  }

  // UNIVERSAL OBS QR CODE PAYLOAD PARSER (SUPPORTS ALL OBS STUDIO & REMOTE FORMATS)
  function parseObsQrPayload(raw) {
    if (!raw || typeof raw !== 'string') return null;
    let str = raw.trim();

    // 1. Check if Base64 encoded JSON
    if (/^[A-Za-z0-9+/=]{16,}$/.test(str)) {
      try {
        const decoded = atob(str);
        if (decoded && decoded.trim().startsWith('{')) {
          str = decoded.trim();
        }
      } catch(e) {}
    }

    // 2. Parse JSON format (e.g. {"ip":"...","port":4455,"pw":"..."})
    if (str.startsWith('{') && str.endsWith('}')) {
      try {
        const obj = JSON.parse(str);
        const ip = String(obj.ip || obj.host || obj.address || obj.server || obj.hostname || 'localhost').trim();
        const port = parseInt(obj.port || obj.wsPort || obj.serverPort || 4455, 10) || 4455;
        const password = String(obj.pw || obj.password || obj.serverPassword || obj.secret || obj.auth || '');
        const name = obj.name || obj.profileName || `OBS (${ip})`;
        return { ip, port, password, name };
      } catch(e) {}
    }

    // 3. Parse OBS URL schemes: obs-websocket://, obsws://, ws://, wss://
    // e.g. obs-websocket://192.168.1.50:4455/mySecretPassword or obsws://192.168.1.50:4455?password=...
    const schemeMatch = str.match(/^(?:obs-websocket|obsws|wss?):\/\/([^/?#]+)(?:\/([^?#]*))?(?:\?(.*))?$/i);
    if (schemeMatch) {
      const hostPart = schemeMatch[1];
      const pathPart = schemeMatch[2] ? decodeURIComponent(schemeMatch[2]) : '';
      const queryPart = schemeMatch[3] || '';

      let ip = hostPart;
      let port = 4455;

      if (hostPart.includes(':')) {
        const parts = hostPart.split(':');
        ip = parts[0];
        port = parseInt(parts[1], 10) || 4455;
      }

      let password = pathPart;

      // Check query parameters (e.g. ?password=xyz or ?pw=xyz or ?secret=xyz)
      if (queryPart) {
        try {
          const params = new URLSearchParams(queryPart);
          if (params.has('password')) password = params.get('password');
          else if (params.has('pw')) password = params.get('pw');
          else if (params.has('auth')) password = params.get('auth');
          else if (params.has('secret')) password = params.get('secret');
        } catch(e) {}
      }

      return {
        ip: ip.trim(),
        port: port,
        password: password,
        name: `OBS (${ip.trim()})`
      };
    }

    // 4. Parse plain host:port/password (e.g. 192.168.1.50:4455/password)
    const hostPortMatch = str.match(/^([a-zA-Z0-9.\-_]+):(\d+)(?:\/(.*))?$/);
    if (hostPortMatch) {
      return {
        ip: hostPortMatch[1].trim(),
        port: parseInt(hostPortMatch[2], 10) || 4455,
        password: hostPortMatch[3] ? decodeURIComponent(hostPortMatch[3]) : '',
        name: `OBS (${hostPortMatch[1].trim()})`
      };
    }

    // 5. Parse plain IP (e.g. 192.168.1.50)
    if (/^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(str) || /^localhost$/i.test(str)) {
      return {
        ip: str.trim(),
        port: 4455,
        password: '',
        name: `OBS (${str.trim()})`
      };
    }

    return null;
  }

  // Handle scanned QR result
  function handleScannedQrData(decodedText) {
    const parsed = parseObsQrPayload(decodedText);
    if (parsed) {
      stopQrCameraScanner();
      
      const nameInput = document.getElementById('obs-profile-name-input');
      const ipInput = document.getElementById('obs-ip-input');
      const portInput = document.getElementById('obs-port-input');
      const pwInput = document.getElementById('obs-pw-input');

      if (nameInput) nameInput.value = parsed.name || 'خادم OBS من QR';
      if (ipInput) ipInput.value = parsed.ip;
      if (portInput) portInput.value = parsed.port;
      if (pwInput) pwInput.value = parsed.password || '';

      // Auto-save to profiles
      const currentProfiles = getSavedObsProfiles();
      const existingIdx = currentProfiles.findIndex(p => p.ip === parsed.ip && String(p.port) === String(parsed.port));
      const newProfile = {
        id: 'obs_prof_' + Date.now(),
        name: parsed.name || `OBS (${parsed.ip})`,
        ip: parsed.ip,
        port: parsed.port,
        password: parsed.password || '',
        updatedAt: Date.now()
      };

      if (existingIdx !== -1) {
        currentProfiles[existingIdx] = { ...currentProfiles[existingIdx], ...newProfile };
      } else {
        currentProfiles.push(newProfile);
      }
      saveObsProfiles(currentProfiles);
      renderSavedObsProfilesList();

      // Switch to Scenes / Connection Tab and connect
      const connectTabBtn = document.querySelector('.obs-tab-btn[data-tab="obs-tab-scenes"]');
      if (connectTabBtn) connectTabBtn.click();

      globalObsClient.connect(parsed.ip, parsed.port, parsed.password);
      showToast(`✅ تم التعرف على بيانات OBS والاتصال بـ ${parsed.ip}:${parsed.port}!`);
    } else {
      showToast('⚠️ رمز QR غير صالح لخادم OBS.');
    }
  }

  // QR Camera Scanner lifecycle
  async function startQrCameraScanner() {
    const video = document.getElementById('obs-qr-video');
    const placeholder = document.getElementById('obs-qr-placeholder');
    const laser = document.getElementById('obs-qr-laser');
    const btnStop = document.getElementById('btn-stop-qr-scanner');
    const canvas = document.getElementById('obs-qr-canvas');

    if (!video || !canvas) return;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment', width: { ideal: 640 }, height: { ideal: 480 } }
      });
      activeQrMediaStream = stream;
      video.srcObject = stream;
      video.classList.remove('hidden');
      if (placeholder) placeholder.classList.add('hidden');
      if (laser) laser.classList.remove('hidden');
      if (btnStop) btnStop.classList.remove('hidden');

      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      let barcodeDetector = null;
      if ('BarcodeDetector' in window) {
        try {
          barcodeDetector = new window.BarcodeDetector({ formats: ['qr_code'] });
        } catch(e) {}
      }

      if (qrScanInterval) clearInterval(qrScanInterval);
      qrScanInterval = setInterval(async () => {
        if (!activeQrMediaStream || video.readyState !== video.HAVE_ENOUGH_DATA) return;

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        // Try native BarcodeDetector API first
        if (barcodeDetector) {
          try {
            const barcodes = await barcodeDetector.detect(canvas);
            if (barcodes && barcodes.length > 0 && barcodes[0].rawValue) {
              handleScannedQrData(barcodes[0].rawValue);
              return;
            }
          } catch(e) {}
        }

        // Fallback to jsQR if available
        if (typeof window.jsQR === 'function') {
          try {
            const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const code = window.jsQR(imgData.data, imgData.width, imgData.height, {
              inversionAttempts: 'dontInvert'
            });
            if (code && code.data) {
              handleScannedQrData(code.data);
              return;
            }
          } catch(e) {}
        }
      }, 200);

    } catch (err) {
      showToast('⚠️ تعذر تشغيل الكاميرا. يمكنك مسح صورة رمز QR بدلاً من ذلك.');
      if (placeholder) placeholder.classList.remove('hidden');
      if (video) video.classList.add('hidden');
    }
  }

  function stopQrCameraScanner() {
    if (qrScanInterval) {
      clearInterval(qrScanInterval);
      qrScanInterval = null;
    }
    if (activeQrMediaStream) {
      activeQrMediaStream.getTracks().forEach(t => t.stop());
      activeQrMediaStream = null;
    }
    const video = document.getElementById('obs-qr-video');
    const placeholder = document.getElementById('obs-qr-placeholder');
    const laser = document.getElementById('obs-qr-laser');
    const btnStop = document.getElementById('btn-stop-qr-scanner');

    if (video) {
      video.srcObject = null;
      video.classList.add('hidden');
    }
    if (placeholder) placeholder.classList.remove('hidden');
    if (laser) laser.classList.add('hidden');
    if (btnStop) btnStop.classList.add('hidden');
  }

