  // =========================================================================
  // MOBILE REMOTE CONTROL HOST ENGINE (WEBRTC 0MS DIRECT SOCKET + INSTANT SERVER STREAMING)
  let remoteHostSession = null;
  let isHostPolling = false;
  let hostPeer = null;
  let activeRemotePeerConnections = new Map();

  // BROADCAST CHANNEL FOR 0.01MS LOCAL TAB / SAME-DEVICE SYNC
  const remoteBroadcastChannel = (typeof window.BroadcastChannel !== 'undefined') ? new window.BroadcastChannel('taranim_remote_sync') : null;
  if (remoteBroadcastChannel) {
    remoteBroadcastChannel.onmessage = (e) => {
      if (e.data) {
        if (e.data.type === 'COMMAND' && e.data.command) {
          executeRemoteCommand(e.data.command);
        } else if (e.data.type === 'REQUEST_STATE') {
          pushRemoteHostState();
        }
      }
    };
  }

  // CLEAN ROOT API GATEWAY HOST FETCHER
  async function requestRemoteHostApi(action, payload = {}) {
    try {
      const res = await fetch(`/api.php?action=remote_${action}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: action, ...payload })
      });
      if (res.ok) {
        const data = await res.json();
        if (data) return data;
      }
    } catch(e) {}
    return null;
  }

  async function initRemoteHost(forceNew = false) {
    let existingSession = null;
    if (!forceNew) {
      try {
        const saved = localStorage.getItem('sunday_school_remote_host_session');
        if (saved) existingSession = JSON.parse(saved);
      } catch(e) {}
    }

    const payload = { action: 'create_room' };
    if (existingSession && existingSession.roomId && existingSession.roomPin && existingSession.hostKey && !forceNew) {
      payload.roomId = existingSession.roomId;
      payload.roomPin = existingSession.roomPin;
      payload.hostKey = existingSession.hostKey;
    }

    const data = await requestRemoteHostApi('create_room', payload);
    if (data && data.success) {
      remoteHostSession = {
        roomId: data.roomId,
        roomPin: data.roomPin,
        hostKey: data.hostKey
      };
      try {
        localStorage.setItem('sunday_school_remote_host_session', JSON.stringify(remoteHostSession));
      } catch(e) {}
    } else if (existingSession) {
      remoteHostSession = existingSession;
    }

    if (remoteHostSession) {
      renderRemotePairingUI();
      initWebRtcHost(remoteHostSession.roomPin);
      pushRemoteHostState();
      startHostInstantLongPoll();
    }
  }

  // 1. WEBRTC DIRECT PEER HOST LISTENER (TRUE 0MS SOCKET)
  function initWebRtcHost(roomPin) {
    if (!window.Peer || !roomPin) return;
    try {
      if (hostPeer) hostPeer.destroy();
      const hostPeerId = 'sstaranim_' + roomPin;
      hostPeer = new window.Peer(hostPeerId, {
        debug: 0,
        config: {
          iceServers: [
            { urls: 'stun:stun.l.google.com:19302' },
            { urls: 'stun:stun1.l.google.com:19302' },
            { urls: 'stun:stun2.l.google.com:19302' },
            { urls: 'stun:stun.cloudflare.com:3478' }
          ],
          iceCandidatePoolSize: 10
        }
      });

      hostPeer.on('open', () => {
        // Peer host ready
      });

      hostPeer.on('connection', (conn) => {
        activeRemotePeerConnections.set(conn.peer, conn);
        updateRemoteClientsUI(activeRemotePeerConnections.size);

        conn.on('data', (cmd) => {
          if (!cmd) return;
          if (cmd.type === 'REQUEST_CONTROL') {
            handleHostControlRequest(cmd, conn);
          } else if (cmd.type === 'REGISTER_DEVICE') {
            registerHotspotDevice(cmd, conn);
          } else if (cmd.type === 'DISCONNECT_CONTROLLER') {
            handleControllerDisconnected(conn);
          } else {
            // Check if device is blocked or control permission disabled
            let devRecord = null;
            state.hotspotConnectedDevices.forEach((d) => {
              if (d.conn === conn || (conn.peer && d.peerId === conn.peer)) {
                devRecord = d;
              }
            });

            if (devRecord && devRecord.canControl === false) {
              try {
                conn.send({
                  type: 'CONTROL_DENIED',
                  message: 'صلاحية التحكم معطلة لهذا الجهاز من قبل المشرف على شاشة العرض.'
                });
              } catch(e) {}
              return;
            }

            executeRemoteCommand(cmd, conn);
          }
        });

        conn.on('close', () => {
          activeRemotePeerConnections.delete(conn.peer);
          updateRemoteClientsUI(activeRemotePeerConnections.size);
          state.hotspotConnectedDevices.forEach((dev, key) => {
            if (dev.conn === conn) {
              state.hotspotConnectedDevices.delete(key);
            }
          });
          renderHotspotConnectedDevices();
          if (state.hotspotConnectedDevices.size === 0) {
            updateHotspotConnectionBadge(false);
          }
        });

        conn.on('error', () => {
          activeRemotePeerConnections.delete(conn.peer);
        });

        // If client is reconnecting and was already approved, send full current state immediately
        if (conn.peer && approvedControllerTokens.has(conn.peer)) {
          conn.send({
            type: 'STATE_UPDATE',
            state: getFullHostStateSnapshot()
          });
        }
      });

      hostPeer.on('error', () => {});
    } catch(e) {}
  }

  function getRemoteAppUrl(roomId, roomPin) {
    const pin = encodeURIComponent(roomPin || roomId || '');
    const loc = window.location;
    let path = loc.pathname;
    if (path.endsWith('.html') || path.endsWith('.php')) {
      path = path.substring(0, path.lastIndexOf('/') + 1);
    } else if (!path.endsWith('/')) {
      path += '/';
    }
    return `${loc.origin}${path}remote.html?pin=${pin}`;
  }

  function renderRemotePairingUI() {
    if (!remoteHostSession) return;
    const pinEl = document.getElementById('remote-host-pin-txt');
    const advPinEl = document.getElementById('remote-adv-pin-txt');
    const container = document.getElementById('remote-qr-canvas-container');
    const advContainer = document.getElementById('remote-adv-qr-canvas-container');

    const pinVal = remoteHostSession.roomPin || '------';
    if (pinEl) pinEl.textContent = pinVal;
    if (advPinEl) advPinEl.textContent = pinVal;

    const fullUrl = getRemoteAppUrl(remoteHostSession.roomId, remoteHostSession.roomPin);

    const renderQr = (cnt, size) => {
      if (!cnt) return;
      cnt.innerHTML = '';
      if (typeof window.QRCode === 'function') {
        try {
          new window.QRCode(cnt, {
            text: fullUrl,
            width: size,
            height: size,
            colorDark: '#0f172a',
            colorLight: '#ffffff',
            correctLevel: window.QRCode.CorrectLevel.M
          });
        } catch(e) {
          cnt.innerHTML = `<img src="https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(fullUrl)}" alt="QR Code" style="width:${size}px; height:${size}px; display:block;">`;
        }
      } else {
        cnt.innerHTML = `<img src="https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(fullUrl)}" alt="QR Code" style="width:${size}px; height:${size}px; display:block;">`;
      }
    };

    renderQr(container, 200);
    renderQr(advContainer, 160);
  }

  // 2. BROADCAST STATE IN 0MS TO ALL CONNECTED PEERS & PUSH TO SERVER
  async function pushRemoteHostState() {
    const currentLines = (state.livePresentationLines && state.livePresentationLines.length > 0) ? state.livePresentationLines : (state.presentationLines || []);
    const targetSong = state.liveSong || state.activeSong;
    const targetIdx = (state.liveLineIndex >= 0) ? state.liveLineIndex : (state.currentLineIndex >= 0 ? state.currentLineIndex : 0);

    const stateObj = {
      activeSong: targetSong,
      liveSong: targetSong,
      currentLineIndex: targetIdx,
      liveLineIndex: targetIdx,
      totalLines: currentLines.length,
      presentationLines: currentLines,
      isBlank: Boolean(state.isBlank),
      isStandbyMode: Boolean(state.isStandbyMode),
      sessionRecents: (state.sessionRecents || []).slice(0, 30),
      theme: state.userSettings?.selectedTemplateId || 'default'
    };

    const payload = { type: 'STATE_UPDATE', state: stateObj };
    const sentConns = new Set();

    // Instant WebRTC Broadcast to ALL connected peers
    if (activeRemotePeerConnections) {
      activeRemotePeerConnections.forEach(conn => {
        if (conn && conn.open) {
          try {
            conn.send(payload);
            sentConns.add(conn);
          } catch(e) {}
        }
      });
    }

    if (state.hotspotConnectedDevices) {
      state.hotspotConnectedDevices.forEach(dev => {
        if (dev && dev.conn && dev.conn.open && !sentConns.has(dev.conn)) {
          try {
            dev.conn.send(payload);
            sentConns.add(dev.conn);
          } catch(e) {}
        }
      });
    }

    // Server State Push if session active
    if (remoteHostSession && remoteHostSession.roomId) {
      requestRemoteHostApi('push_state', {
        roomId: remoteHostSession.roomId,
        hostKey: remoteHostSession.hostKey,
        state: stateObj
      }).catch(() => {});
    }
  }

  window.pushRemoteHostState = pushRemoteHostState;

  function updateRemoteClientsUI(count) {
    const headerBadge = document.getElementById('remote-header-status-badge');
    const clientsDot = document.getElementById('remote-clients-dot');
    const clientsTxt = document.getElementById('remote-clients-count-txt');
    const advClientsTxt = document.getElementById('remote-adv-clients-txt');

    if (headerBadge) {
      headerBadge.className = 'remote-badge-dot ' + (count > 0 ? 'connected' : 'disconnected');
    }
    if (clientsDot) {
      clientsDot.className = 'status-dot ' + (count > 0 ? '' : 'offline');
    }
    if (clientsTxt) {
      clientsTxt.textContent = count > 0 ? `🟢 متصل: ${count} هاتف / جهاز (مباشر)` : 'في انتظار مسح رمز QR...';
    }
    if (advClientsTxt) {
      advClientsTxt.textContent = count > 0 ? `متصل (${count} أجهزة)` : 'جاهز للاتصال';
    }
  }

  // 3. INSTANT SERVER LONG-POLL STREAM (ZERO DELAY FALLBACK)
  async function startHostInstantLongPoll() {
    if (isHostPolling || !remoteHostSession) return;
    isHostPolling = true;

    while (isHostPolling && remoteHostSession) {
      try {
        const data = await requestRemoteHostApi('poll_commands', {
          roomId: remoteHostSession.roomId,
          hostKey: remoteHostSession.hostKey
        });
        if (data && data.success) {
          const count = Math.max(data.clientCount || 0, activeRemotePeerConnections.size);
          updateRemoteClientsUI(count);

          if (Array.isArray(data.commands) && data.commands.length > 0) {
            data.commands.forEach(cmd => executeRemoteCommand(cmd));
          }
        }
        await new Promise(r => setTimeout(r, 300));
      } catch(e) {
        await new Promise(r => setTimeout(r, 1000));
      }
    }
  }

  const processedRemoteCommandIds = new Set();
  let lastRemoteCommandType = '';
  let lastRemoteCommandTime = 0;

  function executeRemoteCommand(cmd) {
    if (!cmd || !cmd.type) return;

    // 1. Deduplicate by unique Command ID across WebRTC, BroadcastChannel, and HTTP Long-poll
    if (cmd.id) {
      if (processedRemoteCommandIds.has(cmd.id)) {
        return;
      }
      processedRemoteCommandIds.add(cmd.id);
      if (processedRemoteCommandIds.size > 250) {
        const first = processedRemoteCommandIds.values().next().value;
        processedRemoteCommandIds.delete(first);
      }
    }

    // 2. Debounce rapid identical command duplicate triggers (e.g. within 200ms)
    const now = Date.now();
    if (cmd.type === lastRemoteCommandType && (now - lastRemoteCommandTime < 200)) {
      return;
    }
    lastRemoteCommandType = cmd.type;
    lastRemoteCommandTime = now;

    if (cmd.type === 'NEXT_LINE') {
      nextLine();
    } else if (cmd.type === 'PREV_LINE') {
      prevLine();
    } else if (cmd.type === 'JUMP_LINE' || cmd.type === 'PRESENT_LINE') {
      if (cmd.activeSong) {
        const currKey = state.activeSong ? getItemKey(state.activeSong) : '';
        const incomingKey = getItemKey(cmd.activeSong);
        if (incomingKey && incomingKey !== currKey) {
          const songToLoad = Object.assign({}, cmd.activeSong, { _fromHotspotSync: true });
          if (typeof openAndPresentItem === 'function') {
            openAndPresentItem(songToLoad, Boolean(songToLoad.is_bible));
          } else if (typeof loadSongIntoPresentation === 'function') {
            loadSongIntoPresentation(songToLoad, true, true);
          }
        }
      }
      const targetIdx = (cmd.lineIndex !== undefined) ? cmd.lineIndex : cmd.currentLineIndex;
      if (targetIdx !== undefined && state.presentationLines && targetIdx >= 0 && targetIdx < state.presentationLines.length) {
        state.liveSong = state.activeSong;
        state.livePresentationLines = state.presentationLines;
        state.currentLineIndex = targetIdx;
        state.liveLineIndex = targetIdx;
        state.isBlank = false;
        renderPresentationLinesList();
        syncLiveState();
        if (typeof scrollActiveSlideToTop === 'function') {
          scrollActiveSlideToTop(false);
        }
      }
    } else if (cmd.type === 'SYNC_STATE') {
      if (cmd.activeSong) {
        const currKey = state.activeSong ? getItemKey(state.activeSong) : '';
        const incomingKey = getItemKey(cmd.activeSong);
        if (incomingKey && incomingKey !== currKey) {
          const songToLoad = Object.assign({}, cmd.activeSong, { _fromHotspotSync: true });
          if (typeof openAndPresentItem === 'function') {
            openAndPresentItem(songToLoad, Boolean(songToLoad.is_bible));
          } else if (typeof loadSongIntoPresentation === 'function') {
            loadSongIntoPresentation(songToLoad, true, true);
          }
        }
      }
      if (cmd.currentLineIndex !== undefined && state.presentationLines && cmd.currentLineIndex >= 0 && cmd.currentLineIndex < state.presentationLines.length) {
        state.liveSong = state.activeSong;
        state.livePresentationLines = state.presentationLines;
        state.currentLineIndex = cmd.currentLineIndex;
        state.liveLineIndex = cmd.currentLineIndex;
      }
      if (cmd.isBlank !== undefined) {
        state.isBlank = Boolean(cmd.isBlank);
        if (els.btnToggleBlank) els.btnToggleBlank.classList.toggle('active', state.isBlank);
      }
      if (cmd.isStandbyMode !== undefined) {
        state.isStandbyMode = Boolean(cmd.isStandbyMode);
        if (els.btnToggleStandby) els.btnToggleStandby.classList.toggle('active', state.isStandbyMode);
      }
      renderPresentationLinesList();
      syncLiveState();
      if (typeof scrollActiveSlideToTop === 'function') {
        scrollActiveSlideToTop(false);
      }
    } else if (cmd.type === 'TOGGLE_BLANK') {
      toggleBlank();
    } else if (cmd.type === 'SET_BLANK') {
      if (cmd.isBlank !== undefined) {
        state.isBlank = Boolean(cmd.isBlank);
        if (els.btnToggleBlank) els.btnToggleBlank.classList.toggle('active', state.isBlank);
        syncLiveState();
      }
    } else if (cmd.type === 'TOGGLE_STANDBY') {
      toggleStandbyMode(true);
    } else if (cmd.type === 'SET_STANDBY') {
      if (cmd.isStandby !== undefined) {
        state.isStandbyMode = Boolean(cmd.isStandby);
        if (els.btnToggleStandby) els.btnToggleStandby.classList.toggle('active', state.isStandbyMode);
        syncLiveState();
      }
    } else if ((cmd.type === 'PLAY_SONG' || cmd.type === 'LOAD_SONG') && cmd.song) {
      const songToLoad = Object.assign({}, cmd.song, { _fromHotspotSync: true });
      if (typeof openAndPresentItem === 'function') {
        openAndPresentItem(songToLoad, Boolean(songToLoad.is_bible));
      } else if (typeof loadSongIntoPresentation === 'function') {
        loadSongIntoPresentation(songToLoad, true);
      }
      showToast(`📱 تم تشغيل "${cmd.song.title || 'العنصر'}" من الهاتف!`);
    } else if (cmd.type === 'LAUNCH_SCREEN') {
      const targetVal = cmd.screenVal || 'screen_0';
      if (cmd.targetLineIdx !== undefined && cmd.targetLineIdx !== null && !isNaN(cmd.targetLineIdx)) {
        state.liveLineIndex = cmd.targetLineIdx;
        state.currentLineIndex = cmd.targetLineIdx;
      }
      launchPresenterOnSelectedScreen(targetVal);
      showToast(`📺 تم إطلاق العرض من الريموت على (${targetVal})`);
    } else if (cmd.type === 'REQUEST_CATALOG') {
      if (state.allSongs && state.allSongs.length > 0) {
        const compactCatalog = state.allSongs.slice(0, 3500).map(s => ({
          id: s.id,
          title: s.title,
          notes: (s.text || s.notes || '').substring(0, 150),
          is_custom: Boolean(s.is_custom)
        }));
        activeRemotePeerConnections.forEach(conn => {
          if (conn && conn.open) {
            conn.send({ type: 'CATALOG_DATA', songs: compactCatalog });
          }
        });
      }
    }

    pushRemoteHostState();
  }

