    if (els.standbyFileInput) {
      els.standbyFileInput.addEventListener('change', (e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (evt) => {
          state.standbyConfig.url = evt.target.result;
          if (file.type.startsWith('video/')) {
            state.standbyConfig.type = 'custom_video';
          } else {
            state.standbyConfig.type = 'custom_image';
          }
          if (els.standbyFileName) els.standbyFileName.textContent = file.name;
          updateStandbyUI();
          saveMediaConfig();
          syncLiveState();
          showToast(`تم تعيين شاشة الانتظار: ${file.name}`);
        };
        reader.readAsDataURL(file);
      });
    }

    if (els.standbyLoopCb) {
      els.standbyLoopCb.addEventListener('change', (e) => {
        state.standbyConfig.loop = Boolean(e.target.checked);
        saveMediaConfig();
        syncLiveState();
      });
    }

    // --- 4. TRANSITIONS CONFIG HANDLERS ---
    const updateTransitionUI = () => {
      const type = state.transitionConfig?.type || 'fade';
      if (els.transitionTypeSelect) els.transitionTypeSelect.value = type;

      document.querySelectorAll('.transition-source-segmented .segmented-btn').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-trans-type') === type);
      });

      if (els.stingerConfigWrap) els.stingerConfigWrap.classList.toggle('hidden', type !== 'stinger');
      if (els.stingerCutpointRange) els.stingerCutpointRange.value = state.transitionConfig?.cutPointMs || 1200;
      if (els.stingerCutpointBadge) els.stingerCutpointBadge.textContent = `${state.transitionConfig?.cutPointMs || 1200}ms`;

      if (els.stingerTemplateSelect && state.transitionConfig?.stingerUrl) {
        els.stingerTemplateSelect.value = state.transitionConfig.stingerUrl;
      }
    };

    document.querySelectorAll('.transition-source-segmented .segmented-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const type = btn.getAttribute('data-trans-type') || 'fade';
        if (!state.transitionConfig) state.transitionConfig = {};
        state.transitionConfig.type = type;
        state.transitionConfig.userSelected = true;
        updateTransitionUI();
        saveMediaConfig();
        syncLiveState();
        const transNames = {
          stinger: 'ستنجر فيديو',
          luma_sinus9: 'مسح متمركز ناعم',
          fade: 'تلاشي ناعم',
          zoom: 'تكبير وانبثاق',
          cut: 'قطع فوري'
        };
        showToast(`تم تفعيل نمط انتقال: ${transNames[type] || type}`);
      });
    });

    if (els.transitionTypeSelect) {
      els.transitionTypeSelect.addEventListener('change', (e) => {
        if (!state.transitionConfig) state.transitionConfig = {};
        state.transitionConfig.type = e.target.value;
        state.transitionConfig.userSelected = true;
        updateTransitionUI();
        saveMediaConfig();
        syncLiveState();
      });
    }

    if (els.stingerTemplateSelect) {
      els.stingerTemplateSelect.addEventListener('change', (e) => {
        const val = e.target.value;
        if (val === 'custom') {
          if (els.stingerCustomUploadWrap) els.stingerCustomUploadWrap.classList.remove('hidden');
        } else {
          if (els.stingerCustomUploadWrap) els.stingerCustomUploadWrap.classList.add('hidden');
          state.transitionConfig.stingerUrl = val;
          saveMediaConfig();
          syncLiveState();
        }
      });
    }

    if (els.stingerFileInput) {
      els.stingerFileInput.addEventListener('change', (e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (evt) => {
          state.transitionConfig.stingerUrl = evt.target.result;
          if (els.stingerFileName) els.stingerFileName.textContent = file.name;
          saveMediaConfig();
          syncLiveState();
          showToast(`تم تعيين فيديو الستنجر: ${file.name}`);
        };
        reader.readAsDataURL(file);
      });
    }

    if (els.stingerCutpointRange) {
      els.stingerCutpointRange.addEventListener('input', (e) => {
        const val = parseInt(e.target.value) || 1200;
        state.transitionConfig.cutPointMs = val;
        if (els.stingerCutpointBadge) els.stingerCutpointBadge.textContent = `${val}ms`;
        saveMediaConfig();
      });
    }

    // --- 5. CATEGORIZED TEMPLATES CATALOG WITH LIVE THUMBNAILS ---
    const getSavedTemplates = () => {
      try {
        return JSON.parse(localStorage.getItem('sunday_school_saved_templates')) || [];
      } catch(e) {
        return [];
      }
    };



      // ----------------------------------------------------
  // TEMPLATE PRE-RENDER & CACHE DOWNLOAD ENGINE
  // ----------------------------------------------------
  const TEMPLATE_KNOWN_SIZES = {
    'tmpl-default-black': 0,
    'tmpl-shabahak-akon-2026': 64.84, // 29.63 MB (Loop) + 29.60 MB (Empty) + 5.61 MB (Stringer)
    'tmpl-paint-sweeps': 37.40, // 25 backgrounds total
    'tmpl-paint-sweeps-animated': 328.5,
    'tmpl-broadcast-chroma-green': 0.1 // 10 animated HD 1080 video loops
  };

  function getTemplateAssets(tmpl) {
    if (!tmpl) return [];
    const urls = [];
    if (tmpl.standby && !tmpl.standby.startsWith('data:')) urls.push(tmpl.standby);
    if (tmpl.slidesBg && !tmpl.slidesBg.startsWith('data:')) urls.push(tmpl.slidesBg);
    if (tmpl.stringer && !tmpl.stringer.startsWith('data:')) urls.push(tmpl.stringer);
    if (tmpl.thumbnailUrl && !tmpl.thumbnailUrl.startsWith('data:')) urls.push(tmpl.thumbnailUrl);
    if (tmpl.varieties && Array.isArray(tmpl.varieties)) {
      tmpl.varieties.forEach(v => {
        if (v && v.url && !v.url.startsWith('data:')) urls.push(v.url);
      });
    }
    return Array.from(new Set(urls.filter(Boolean)));
  }

  function getTemplateEstimatedSizeMB(tmpl) {
    if (!tmpl) return 0;
    if (TEMPLATE_KNOWN_SIZES[tmpl.id]) {
      return TEMPLATE_KNOWN_SIZES[tmpl.id];
    }
    const assets = getTemplateAssets(tmpl);
    if (assets.length === 0) return 0;
    let est = 0;
    assets.forEach(u => {
      if (/\.(mp4|webm|mov)$/i.test(u)) est += 15.0;
      else if (/\.(jpg|jpeg|png|webp)$/i.test(u)) est += 0.8;
      else est += 0.5;
    });
    return Math.round(est * 10) / 10;
  }

  const PRERENDER_STORAGE_KEY_PREFIX = 'sunday_school_tmpl_prerendered_';
  const PRERENDER_VER_KEY_PREFIX = 'sunday_school_tmpl_version_';
  const DISMISSED_UPDATE_KEY_PREFIX = 'sunday_school_tmpl_dismissed_update_';

  function getTemplateVersion(tmpl) {
    if (!tmpl) return '1';
    if (tmpl.version !== undefined && tmpl.version !== null) return String(tmpl.version);
    if (tmpl.updated_at !== undefined && tmpl.updated_at !== null) return String(tmpl.updated_at);
    // Fallback: stable hash from asset URLs
    const assets = getTemplateAssets(tmpl).join('|');
    let hash = 0;
    for (let i = 0; i < assets.length; i++) {
      hash = ((hash << 5) - hash) + assets.charCodeAt(i);
      hash |= 0;
    }
    return String(hash);
  }

  function isTemplatePrerendered(tmplId) {
    if (tmplId === 'tmpl-default-black') return true;
    try {
      return localStorage.getItem(PRERENDER_STORAGE_KEY_PREFIX + tmplId) === 'true';
    } catch(e) {
      return false;
    }
  }

  function getDownloadedTemplateVersion(tmplId) {
    try {
      return localStorage.getItem(PRERENDER_VER_KEY_PREFIX + tmplId);
    } catch(e) {
      return null;
    }
  }

  function isTemplateUpdateAvailable(tmpl) {
    if (!tmpl || tmpl.isCustom || tmpl.id === 'tmpl-default-black') return false;
    if (!isTemplatePrerendered(tmpl.id)) return false;
    const currentVer = getTemplateVersion(tmpl);
    const downloadedVer = getDownloadedTemplateVersion(tmpl.id);
    if (downloadedVer && downloadedVer !== currentVer) {
      return true;
    }
    // If downloaded without version record but server version is > 1
    if (!downloadedVer && currentVer !== '1') {
      return true;
    }
    return false;
  }

  function setTemplatePrerendered(tmplId, isPrerendered = true, version = null) {
    try {
      if (isPrerendered) {
        localStorage.setItem(PRERENDER_STORAGE_KEY_PREFIX + tmplId, 'true');
        if (version !== null && version !== undefined) {
          localStorage.setItem(PRERENDER_VER_KEY_PREFIX + tmplId, String(version));
        }
        try {
          sessionStorage.removeItem(DISMISSED_UPDATE_KEY_PREFIX + tmplId);
        } catch(e) {}
      } else {
        localStorage.removeItem(PRERENDER_STORAGE_KEY_PREFIX + tmplId);
        localStorage.removeItem(PRERENDER_VER_KEY_PREFIX + tmplId);
      }
    } catch(e) {}
  }

  function isVarietyUrlCached(url, tmplId) {
    if (!url) return false;
    if (tmplId && isTemplatePrerendered(tmplId)) return true;
    try {
      return localStorage.getItem('sunday_school_var_cached_' + url) === 'true';
    } catch(e) {
      return false;
    }
  }

  async function downloadSingleVariety(tmpl, variety, btnEl, cardEl) {
    if (!tmpl || !variety || !variety.url) return;
    const url = variety.url;
    const varName = variety.name || 'النمط المختار';

    if (btnEl) {
      btnEl.disabled = true;
      btnEl.classList.add('downloading');
      btnEl.classList.remove('cached');
      btnEl.innerHTML = `<i class="fa-solid fa-circle-notch fa-spin"></i> <span>جاري التحميل...</span>`;
    }

    try {
      let cache = null;
      if ('caches' in window) {
        cache = await caches.open('taranim-pwa-v40');
      }

      const isVid = /\.(mp4|webm|mov)$/i.test(url);
      const isImg = /\.(jpg|jpeg|png|webp|gif|svg)$/i.test(url);

      if (cache) {
        try {
          await cache.delete(url);
          const fetchUrl = url + (url.includes('?') ? '&' : '?') + 't=' + Date.now();
          const res = await fetch(fetchUrl, { cache: 'reload' });
          if (res && res.ok) {
            await cache.put(url, res.clone());
          }
        } catch(err) {
          try {
            const res2 = await fetch(url, { cache: 'force-cache' });
            if (res2 && res2.ok) await cache.put(url, res2.clone());
          } catch(e2) {}
        }

        if (variety.thumbUrl && variety.thumbUrl !== url) {
          try {
            const tRes = await fetch(variety.thumbUrl, { cache: 'force-cache' });
            if (tRes && tRes.ok) await cache.put(variety.thumbUrl, tRes.clone());
          } catch(e) {}
        }
      }

      if (isImg) {
        await new Promise((resolve) => {
          const img = new Image();
          img.onload = () => resolve();
          img.onerror = () => resolve();
          img.src = url + (url.includes('?') ? '&' : '?') + 't=' + Date.now();
        });
      } else if (isVid) {
        await new Promise((resolve) => {
          const vid = document.createElement('video');
          vid.preload = 'auto';
          vid.muted = true;
          vid.oncanplaythrough = () => resolve();
          vid.onerror = () => resolve();
          setTimeout(resolve, 3000);
          vid.src = url;
          vid.load();
        });
      }

      try {
        localStorage.setItem('sunday_school_var_cached_' + url, 'true');
      } catch(e) {}

      if (cardEl) {
        const activeCircle = cardEl.querySelector(`.template-variety-circle[data-url="${CSS.escape(url)}"]`);
        if (activeCircle) {
          activeCircle.dataset.cached = '1';
          activeCircle.classList.add('is-cached');
          activeCircle.title = `${varName} (جاهز أوفلاين)`;
          if (!activeCircle.querySelector('.var-check-badge')) {
            const badge = document.createElement('span');
            badge.className = 'var-check-badge';
            badge.innerHTML = '<i class="fa-solid fa-check"></i>';
            activeCircle.appendChild(badge);
          }
        }

        const allVars = tmpl.varieties || [];
        const allDone = allVars.every(v => isVarietyUrlCached(v.url, tmpl.id));
        if (allDone) {
          setTemplatePrerendered(tmpl.id, true, getTemplateVersion(tmpl));
          const allBtn = cardEl.querySelector('.btn-prerender-template-card');
          if (allBtn) {
            allBtn.remove();
          }
        }

        const applyBtn = cardEl.querySelector('.btn-apply-template-card');
        if (applyBtn) {
          applyBtn.style.display = 'inline-flex';
          applyBtn.classList.remove('hidden');
        }

        const statusPill = cardEl.querySelector(`#tmpl-var-status-${tmpl.id}`);
        if (statusPill) {
          statusPill.className = 'variety-status-pill cached';
          statusPill.innerHTML = '<i class="fa-solid fa-circle-check"></i> جاهز';
        }
      }

      if (btnEl) {
        btnEl.disabled = false;
        btnEl.classList.remove('downloading');
        btnEl.classList.add('cached');
        btnEl.innerHTML = `<i class="fa-solid fa-circle-check" style="color:#10b981;"></i> <span style="color:#059669; font-weight:700;">النمط جاهز</span>`;
        btnEl.title = `النمط "${varName}" محمل وجاهز للعرض`;
      }

      showToast(`✅ تم تحميل النمط "${varName}" بنجاح وجاهز للعرض!`);

    } catch(err) {
      console.error('Failed to download variety:', err);
      if (btnEl) {
        btnEl.disabled = false;
        btnEl.classList.remove('downloading');
        btnEl.innerHTML = `<i class="fa-solid fa-download"></i> <span>إعادة المحاولة</span>`;
      }
      showToast(`تعذر تحميل النمط "${varName}". تحقق من الاتصال بالإنترنت.`);
    }
  }

  async function prerenderTemplateAssets(tmpl, btnEl, onProgress) {
    const assets = getTemplateAssets(tmpl);
    const tmplVer = getTemplateVersion(tmpl);

    if (assets.length === 0) {
      setTemplatePrerendered(tmpl.id, true, tmplVer);
      if (btnEl) {
        btnEl.classList.add('cached');
        btnEl.classList.remove('btn-warning', 'downloading');
        btnEl.innerHTML = `<i class="fa-solid fa-circle-check" style="color:#10b981;"></i> <span style="color:#059669; font-weight:700;">جاهز للعرض</span>`;
      }
      showToast(`القالب "${tmpl.name}" جاهز فوراً للعرض! ✨`);
      return;
    }

    if (btnEl) {
      btnEl.disabled = true;
      btnEl.classList.remove('cached', 'btn-warning');
      btnEl.classList.add('downloading');
      btnEl.innerHTML = `<i class="fa-solid fa-circle-notch fa-spin"></i> <span>جاري التجهيز 0%...</span>`;
    }

    const total = assets.length;
    let completed = 0;

    let cache = null;
    try {
      if ('caches' in window) {
        cache = await caches.open('taranim-pwa-v40');
      }
    } catch(e) {}

    const promises = assets.map(async (url) => {
      try {
        const isVid = /\.(mp4|webm|mov)$/i.test(url);
        const isImg = /\.(jpg|jpeg|png|webp|gif|svg)$/i.test(url);

        // 1. Fetch & Store into Cache Storage (Bypass old cache on update)
        if (cache) {
          try {
            await cache.delete(url);
            const fetchUrl = url + (url.includes('?') ? '&' : '?') + 't=' + Date.now();
            const res = await fetch(fetchUrl, { cache: 'reload' });
            if (res && res.ok) {
              await cache.put(url, res.clone());
            }
          } catch(err) {
            try {
              const res2 = await fetch(url, { cache: 'force-cache' });
              if (res2 && res2.ok) await cache.put(url, res2.clone());
            } catch(e2) {}
          }
        }

        // 2. Pre-decode into browser memory / GPU texture
        if (isImg) {
          await new Promise((resolve) => {
            const img = new Image();
            img.onload = () => resolve();
            img.onerror = () => resolve();
            img.src = url + (url.includes('?') ? '&' : '?') + 't=' + Date.now();
          });
        } else if (isVid) {
          await new Promise((resolve) => {
            const vid = document.createElement('video');
            vid.preload = 'auto';
            vid.muted = true;
            vid.oncanplaythrough = () => resolve();
            vid.onerror = () => resolve();
            setTimeout(resolve, 3000);
            vid.src = url;
            vid.load();
          });
        }
      } catch(e) {
        console.warn('Pre-render asset skipped:', url, e);
      } finally {
        completed++;
        const pct = Math.round((completed / total) * 100);
        if (typeof onProgress === 'function') {
          onProgress(pct, completed, total);
        }
        if (btnEl) {
          btnEl.innerHTML = `<i class="fa-solid fa-circle-notch fa-spin"></i> <span>جاري التجهيز ${pct}% (${completed}/${total})</span>`;
        }
      }
    });

    await Promise.all(promises);

    if (tmpl.varieties && Array.isArray(tmpl.varieties)) {
      tmpl.varieties.forEach(v => {
        if (v && v.url) {
          try {
            localStorage.setItem('sunday_school_var_cached_' + v.url, 'true');
          } catch(e) {}
        }
      });
    }

    setTemplatePrerendered(tmpl.id, true, tmplVer);
    if (btnEl) {
      const card = btnEl.closest('.template-preview-card');
      if (card) {
        const updateBadge = card.querySelector('.template-update-badge');
        if (updateBadge) updateBadge.remove();

        // Update all variety circles with checked badge
        card.querySelectorAll('.template-variety-circle').forEach(c => {
          c.classList.add('is-cached');
          c.dataset.cached = '1';
          if (!c.querySelector('.var-check-badge')) {
            const badge = document.createElement('span');
            badge.className = 'var-check-badge';
            badge.innerHTML = '<i class="fa-solid fa-check"></i>';
            c.appendChild(badge);
          }
        });

        const singleBtn = card.querySelector('.btn-download-single-var');
        if (singleBtn) {
          singleBtn.disabled = false;
          singleBtn.classList.add('cached');
          singleBtn.classList.remove('downloading');
          singleBtn.innerHTML = `<i class="fa-solid fa-circle-check" style="color:#10b981;"></i> <span>النمط جاهز</span>`;
        }

        const statusPill = card.querySelector(`#tmpl-var-status-${tmpl.id}`);
        if (statusPill) {
          statusPill.className = 'variety-status-pill cached';
          statusPill.innerHTML = '<i class="fa-solid fa-circle-check"></i> جاهز';
        }

        const applyBtn = card.querySelector('.btn-apply-template-card');
        if (applyBtn) {
          applyBtn.style.display = 'inline-flex';
          applyBtn.classList.remove('hidden');
        }

        // Remove the prerender button now that template is fully downloaded
        btnEl.remove();
      }
    }

    updateTemplatesTabBadge();
    showToast(`✅ تم تحديث وتجهيز قالب "${tmpl.name}" بنجاح! جاهز للعرض الفوري.`);
  }

  function updateTemplatesTabBadge() {
    const allTmpls = sanitizeAndGroupTemplates(state.availableTemplates || []);
    const hasUpdates = allTmpls.some(t => isTemplateUpdateAvailable(t));
    const tmplTabBtn = document.querySelector('.style-tab-btn[data-tab="tab-templates"]');
    if (!tmplTabBtn) return;
    let dot = tmplTabBtn.querySelector('.template-tab-update-dot');
    if (hasUpdates) {
      if (!dot) {
        dot = document.createElement('span');
        dot.className = 'template-tab-update-dot';
        tmplTabBtn.prepend(dot);
      }
    } else {
      if (dot) dot.remove();
    }
  }

  function checkAndPromptTemplateUpdates() {
    const allTmpls = sanitizeAndGroupTemplates(state.availableTemplates || []);
    const updatedTmpls = allTmpls.filter(t => isTemplateUpdateAvailable(t) && sessionStorage.getItem(DISMISSED_UPDATE_KEY_PREFIX + t.id) !== 'true');
    
    updateTemplatesTabBadge();

    if (updatedTmpls.length === 0) return;

    const modal = document.getElementById('modal-template-update-prompt');
    const listEl = document.getElementById('template-update-prompt-list');
    const descEl = document.getElementById('template-update-prompt-desc');
    const btnConfirm = document.getElementById('btn-confirm-update-templates');
    const btnDismiss = document.getElementById('btn-dismiss-update-templates');
    const progressWrap = document.getElementById('template-update-progress-wrap');
    const progressBar = document.getElementById('template-update-progress-bar');
    const progressTxt = document.getElementById('template-update-progress-txt');

    if (!modal || !listEl) return;

    if (descEl) {
      descEl.textContent = (updatedTmpls.length === 1)
        ? `تم تحديث قالب "${updatedTmpls[0].name}" المحمل لديك بمحتوى وخلفيات جديدة ومحسنة.`
        : `تم تحديث عدد ${updatedTmpls.length} من القوالب المحملة لديك بمحتوى وخلفيات جديدة.`;
    }

    listEl.innerHTML = updatedTmpls.map(t => {
      const sizeMB = getTemplateEstimatedSizeMB(t);
      const sizeStr = sizeMB > 0 ? ` (${sizeMB} MB)` : '';
      return `
        <div class="template-update-prompt-item">
          <div>
            <div class="template-update-prompt-item-name">
              <i class="fa-solid fa-layer-group" style="color:#f59e0b;"></i>
              <span>${escapeHtml(t.name)}</span>
              <span style="background:#fef3c7; color:#d97706; font-size:0.7rem; padding:2px 7px; border-radius:10px; font-weight:800; display:inline-flex; align-items:center; gap:3px;">
                <i class="fa-solid fa-circle-arrow-up"></i> إصدار جديد
              </span>
            </div>
            <div class="template-update-prompt-item-desc">${escapeHtml(t.category || 'عام')} • الحجم التقديري:${sizeStr}</div>
          </div>
          <button type="button" class="btn-single-tmpl-quick-update btn btn-sm btn-warning" data-tmpl-id="${escapeHtml(t.id)}" style="background:linear-gradient(135deg, #f59e0b, #d97706); color:#fff; border:none; padding:6px 14px; border-radius:8px; font-size:0.8rem; font-weight:800; cursor:pointer;">
            <i class="fa-solid fa-arrows-rotate"></i> تحديث
          </button>
        </div>
      `;
    }).join('');

    modal.classList.remove('hidden');

    // Single item update button clicks
    listEl.querySelectorAll('.btn-single-tmpl-quick-update').forEach(btn => {
      btn.addEventListener('click', async (e) => {
        e.stopPropagation();
        const tmplId = btn.dataset.tmplId;
        const targetTmpl = updatedTmpls.find(t => t.id === tmplId);
        if (targetTmpl) {
          btn.disabled = true;
          btn.innerHTML = `<i class="fa-solid fa-circle-notch fa-spin"></i> جاري...`;
          await prerenderTemplateAssets(targetTmpl, null, (pct) => {
            btn.innerHTML = `<i class="fa-solid fa-circle-notch fa-spin"></i> ${pct}%`;
          });
          btn.innerHTML = `<i class="fa-solid fa-check"></i> تم!`;
          btn.style.background = '#10b981';
          renderTemplatesCatalog();
          setTimeout(() => {
            const remaining = allTmpls.filter(t => isTemplateUpdateAvailable(t) && sessionStorage.getItem(DISMISSED_UPDATE_KEY_PREFIX + t.id) !== 'true');
            if (remaining.length === 0) {
              modal.classList.add('hidden');
            } else {
              checkAndPromptTemplateUpdates();
            }
          }, 800);
        }
      });
    });

    // Top X Close button
    if (btnDismiss) {
      btnDismiss.onclick = () => {
        updatedTmpls.forEach(t => {
          try { sessionStorage.setItem(DISMISSED_UPDATE_KEY_PREFIX + t.id, 'true'); } catch(e) {}
        });
        modal.classList.add('hidden');
      };
    }

    // Confirm all update button
    if (btnConfirm) {
      btnConfirm.onclick = async () => {
        btnConfirm.disabled = true;
        if (btnDismiss) btnDismiss.disabled = true;
        if (progressWrap) progressWrap.classList.remove('hidden');

        for (let i = 0; i < updatedTmpls.length; i++) {
          const tmpl = updatedTmpls[i];
          if (progressTxt) progressTxt.textContent = `جاري تحديث قالب "${tmpl.name}" (${i+1}/${updatedTmpls.length})...`;
          await prerenderTemplateAssets(tmpl, null, (pct, comp, tot) => {
            if (progressBar) {
              const overallPct = Math.round(((i + (comp / tot)) / updatedTmpls.length) * 100);
              progressBar.style.width = overallPct + '%';
            }
          });
        }

        if (progressBar) progressBar.style.width = '100%';
        if (progressTxt) progressTxt.textContent = '✅ تم تحديث كافة القوالب بنجاح!';
        showToast('✅ تم تحديث كافة القوالب بنجاح!');
        renderTemplatesCatalog();
        updateTemplatesTabBadge();

        setTimeout(() => {
          modal.classList.add('hidden');
          if (progressWrap) progressWrap.classList.add('hidden');
          btnConfirm.disabled = false;
          if (btnDismiss) btnDismiss.disabled = false;
        }, 1200);
      };
    }
  }

    function renderTemplatesCatalog() {
      const container = document.getElementById('templates-catalog-grid');
      const totalBadge = document.getElementById('templates-total-count-badge');
      if (!container) return;

      const groupedBuiltin = sanitizeAndGroupTemplates(state.availableTemplates || []);
      state.availableTemplates = groupedBuiltin;

      const builtinList = groupedBuiltin.map(t => ({
        ...t,
        isCustom: false,
        categoryKey: t.categoryKey || (t.category === 'المؤتمرات' ? 'conferences' : (t.category === 'خلفيات وسلايدات' ? 'backgrounds' : 'conferences'))
      }));

      const customList = getSavedTemplates().map(t => ({
        ...t,
        isCustom: true,
        category: 'قوالبي المخصصة',
        categoryKey: 'custom',
        thumbnailType: 'sim',
        thumbnailBg: 'linear-gradient(135deg, #334155, #1e293b)',
        thumbnailText: t.name || 'قالب مخصص'
      }));

      const allTemplates = [...builtinList, ...customList];

      // Update category badges counts
      const counts = {
        all: allTemplates.length,
        conferences: allTemplates.filter(t => t.categoryKey === 'conferences').length,
        backgrounds: allTemplates.filter(t => t.categoryKey === 'backgrounds').length,
        video: allTemplates.filter(t => t.categoryKey === 'video').length,
        custom: customList.length
      };

      if (totalBadge) totalBadge.textContent = `${allTemplates.length}`;
      const countAllEl = document.getElementById('tmpl-cat-count-all');
      if (countAllEl) countAllEl.textContent = counts.all;
      const countConfEl = document.getElementById('tmpl-cat-count-conferences');
      if (countConfEl) countConfEl.textContent = counts.conferences;
      const countBgEl = document.getElementById('tmpl-cat-count-backgrounds');
      if (countBgEl) countBgEl.textContent = counts.backgrounds;
      const countVideoEl = document.getElementById('tmpl-cat-count-video');
      if (countVideoEl) countVideoEl.textContent = counts.video;
      const countCustEl = document.getElementById('tmpl-cat-count-custom');
      if (countCustEl) countCustEl.textContent = counts.custom;

      // Filter by active category
      const currentCat = state.activeTemplateCategory || 'all';
      const filtered = (currentCat === 'all')
        ? allTemplates
        : allTemplates.filter(t => t.categoryKey === currentCat);

      if (filtered.length === 0) {
        container.innerHTML = `
          <div style="text-align:center; padding:28px 16px; color:var(--text-muted); font-size:0.88rem; grid-column:1/-1;">
            <i class="fa-solid fa-folder-open" style="font-size:1.8rem; margin-bottom:8px; opacity:0.5; display:block;"></i>
            لا توجد قوالب في هذا القسم حالياً
          </div>
        `;
        return;
      }

      container.innerHTML = filtered.map(t => {
        let thumbHtml = '';
        const videoSrc = t.thumbnailUrl || t.standby || t.slidesBg;
        const hasVarieties = Boolean(t.varieties && Array.isArray(t.varieties) && t.varieties.length > 0);
        const hasUpdate = !t.isCustom && isTemplateUpdateAvailable(t);
        const updateBadgeHtml = hasUpdate ? `<span class="template-update-badge"><i class="fa-solid fa-arrows-rotate"></i> تحديث متوفر</span>` : '';
        
        if (hasVarieties) {
          const defaultVar = t.varieties[0];
          const thumbSrc = defaultVar.thumbUrl || t.thumbnailUrl || (defaultVar.url && !/\.(mp4|webm)$/i.test(defaultVar.url) ? defaultVar.url : 'Templates/SlidesBg/Paint Sweeps/Paint Sweeps Blank.jpg');
          thumbHtml = `
            <div class="template-thumb-container">
              <img class="template-thumb-img" id="tmpl-thumb-img-${escapeHtml(t.id)}" src="${escapeHtml(thumbSrc)}" alt="${escapeHtml(t.name)}">
              ${updateBadgeHtml}
              <span class="template-badge-pill"><i class="fa-solid fa-layer-group" style="margin-left:3px;"></i> ${escapeHtml(t.category || 'خلفيات وسلايدات')} (${t.varieties.length} عنصر)</span>
              <div class="template-components-chips">
                <span class="template-comp-chip" id="tmpl-selected-var-badge-${escapeHtml(t.id)}"><i class="fa-solid fa-palette"></i> ${escapeHtml(defaultVar.name)}</span>
                <span class="template-comp-chip"><i class="fa-solid fa-image"></i> خلفية شرائح & انتظار</span>
              </div>
            </div>
          `;
        } else if (t.thumbnailUrl && !/\.(mp4|webm|mov)$/i.test(t.thumbnailUrl) && !t.isCustom) {
          thumbHtml = `
            <div class="template-thumb-container">
              <img class="template-thumb-img" id="tmpl-thumb-img-${escapeHtml(t.id)}" src="${escapeHtml(t.thumbnailUrl)}" alt="${escapeHtml(t.name)}" loading="lazy">
              ${updateBadgeHtml}
              <span class="template-badge-pill">${t.is_default || t.id === 'tmpl-default-black' ? '<i class="fa-solid fa-star" style="color:#fbbf24; margin-left:3px;"></i> رئيسي' : `<i class="fa-solid fa-users" style="margin-left:3px;"></i> ${escapeHtml(t.category || 'مؤتمرات')}`}</span>
              <div class="template-components-chips">
                ${t.is_default || t.id === 'tmpl-default-black' ? '<span class="template-comp-chip" style="background:rgba(16, 185, 129, 0.15); color:#10b981; border:1px solid rgba(16, 185, 129, 0.3);"><i class="fa-solid fa-circle-check"></i> محمل تلقائياً (الأساسي)</span>' : ''}
                ${t.standby ? '<span class="template-comp-chip"><i class="fa-solid fa-photo-film"></i> شاشة انتظار</span>' : ''}
                ${t.slidesBg ? '<span class="template-comp-chip"><i class="fa-solid fa-image"></i> خلفية شرائح</span>' : ''}
                ${t.stringer ? '<span class="template-comp-chip"><i class="fa-solid fa-bolt"></i> انتقال ستنجر</span>' : ''}
              </div>
            </div>
          `;
        } else if ((t.thumbnailType === 'video' || (videoSrc && /\.(mp4|webm)$/i.test(videoSrc))) && !t.isCustom) {
          thumbHtml = `
            <div class="template-thumb-container">
              <div class="template-thumb-sim" style="background: linear-gradient(135deg, #1e293b, #0f172a);">
                <div style="font-size:1.8rem; color:#60a5fa; margin-bottom:6px;"><i class="fa-solid fa-video"></i></div>
                <div style="font-size:0.95rem; font-weight:800; color:#fff;">${escapeHtml(t.name)}</div>
              </div>
              ${updateBadgeHtml}
              <span class="template-badge-pill"><i class="fa-solid fa-users" style="margin-left:3px;"></i> ${escapeHtml(t.category || 'مؤتمرات')}</span>
              <div class="template-components-chips">
                ${t.standby ? '<span class="template-comp-chip"><i class="fa-solid fa-photo-film"></i> شاشة انتظار</span>' : ''}
                ${t.slidesBg ? '<span class="template-comp-chip"><i class="fa-solid fa-image"></i> خلفية شرائح</span>' : ''}
                ${t.stringer ? '<span class="template-comp-chip"><i class="fa-solid fa-bolt"></i> انتقال ستنجر</span>' : ''}
              </div>
            </div>
          `;
        } else {
          const fontName = t.selectedFont ? t.selectedFont.replace(/['",]/g, '') : 'Alexandria';
          thumbHtml = `
            <div class="template-thumb-container">
              <div class="template-thumb-sim" style="background:${t.thumbnailBg || 'linear-gradient(135deg, #1e293b, #0f172a)'};">
                <div style="font-family:${escapeHtml(t.selectedFont || 'inherit')}; font-size:1.15rem; font-weight:800; color:${t.styleOptions?.textColor || '#fff'}; line-height:1.3; text-shadow:0 2px 10px rgba(0,0,0,0.6);">${escapeHtml(t.thumbnailText || t.name)}</div>
                <div style="font-size:0.75rem; opacity:0.85; margin-top:6px;"><i class="fa-solid fa-font"></i> ${escapeHtml(fontName)} • ${t.fontSize || 105}px</div>
              </div>
              ${updateBadgeHtml}
              <span class="template-badge-pill">${escapeHtml(t.category || (t.isCustom ? 'قالب مخصص' : 'عام'))}</span>
              ${t.styleOptions?.textColor ? `<div class="template-components-chips"><span class="template-comp-chip"><i class="fa-solid fa-palette"></i> نمط نص مخصص</span></div>` : ''}
            </div>
          `;
        }

        const initialVarUrl = hasVarieties ? t.varieties[0].url : '';
        const initialVarName = hasVarieties ? t.varieties[0].name : '';

        return `
          <div class="template-preview-card" data-id="${escapeHtml(t.id || t.name)}" data-iscustom="${t.isCustom ? '1' : '0'}">
            ${thumbHtml}
            <div class="template-card-body">
              <div class="template-card-header">
                <div class="template-card-title">
                  <i class="fa-solid fa-layer-group" style="color:#2563eb;"></i>
                  <span>${escapeHtml(t.name)}</span>
                </div>
              </div>
              ${t.desc ? `<div class="template-card-desc">${escapeHtml(t.desc)}</div>` : ''}

              ${hasVarieties ? `
                <div class="template-varieties-wrap">
                  <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:4px; gap:8px; flex-wrap:wrap;">
                    <div class="template-varieties-label">
                      <i class="fa-solid fa-palette"></i> النمط المختار: <b id="tmpl-selected-var-name-${escapeHtml(t.id)}" style="color:#2563eb;">${escapeHtml(initialVarName)}</b>
                      <span class="variety-status-pill ${isVarietyUrlCached(initialVarUrl, t.id) ? 'cached' : 'not-cached'}" id="tmpl-var-status-${escapeHtml(t.id)}">
                        ${isVarietyUrlCached(initialVarUrl, t.id) ? '<i class="fa-solid fa-circle-check"></i> جاهز' : '<i class="fa-solid fa-cloud"></i> غير محمل'}
                      </span>
                    </div>
                    <label class="template-shuffle-toggle" title="تفعيل التبديل العشوائي التلقائي لخلفيات هذه المجموعة عند كل ترنيمة جديدة دون تكرار">
                      <input type="checkbox" class="chk-template-shuffle" data-tmpl-id="${escapeHtml(t.id)}" ${isTemplateShuffleEnabled(t.id) ? 'checked' : ''}>
                      <span class="template-shuffle-text"><i class="fa-solid fa-shuffle"></i> تبديل عشوائي لكل ترنيمة</span>
                    </label>
                  </div>
                  <div class="template-varieties-bar">
                    ${t.varieties.map((v, vIdx) => {
                      const isVarCached = isVarietyUrlCached(v.url, t.id);
                      return `
                        <button type="button" class="template-variety-circle ${vIdx === 0 ? 'active' : ''} ${isVarCached ? 'is-cached' : ''}" data-tmpl-id="${escapeHtml(t.id)}" data-variety-idx="${vIdx}" data-url="${escapeHtml(v.url)}" data-thumb-url="${escapeHtml(v.thumbUrl || v.url)}" data-name="${escapeHtml(v.name)}" data-cached="${isVarCached ? '1' : '0'}" title="${escapeHtml(v.name)}${isVarCached ? ' (جاهز أوفلاين)' : ''}" style="background-image: url('${escapeHtml(v.thumbUrl || v.url)}');">
                          ${isVarCached ? '<span class="var-check-badge"><i class="fa-solid fa-check"></i></span>' : ''}
                        </button>
                      `;
                    }).join('')}
                  </div>
                </div>
              ` : ''}

              <div class="template-card-footer">
                <div class="template-actions-group">
                  ${(function() {
                    const sizeMB = getTemplateEstimatedSizeMB(t);
                    const sizeStr = sizeMB > 0 ? ` (${sizeMB} MB)` : '';
                    const isCached = t.isCustom || isTemplatePrerendered(t.id);
                    const isInitialVarCached = hasVarieties ? isVarietyUrlCached(initialVarUrl, t.id) : isCached;
                    const canApply = hasVarieties ? (isInitialVarCached || isCached) : isCached;
                    
                    if (hasUpdate) {
                      return `
                        <button type="button" class="btn-update-template-card btn btn-sm btn-warning" data-tmpl-id="${escapeHtml(t.id)}" title="يتوفر إصدار أحدث ومحسن من هذا القالب، اضغط للتحديث الفوري">
                          <i class="fa-solid fa-arrows-rotate"></i> <span>تحديث القالب</span> <span class="prerender-size-badge">${sizeStr}</span>
                        </button>
                        <button type="button" class="btn-apply-template-card btn btn-sm btn-primary" data-name="${escapeHtml(t.name)}" data-id="${escapeHtml(t.id || '')}" data-iscustom="${t.isCustom ? '1' : '0'}" ${hasVarieties ? `data-selected-variety-idx="0" data-selected-variety-url="${escapeHtml(initialVarUrl)}" data-selected-variety-name="${escapeHtml(initialVarName)}"` : ''} style="background:#2563eb; color:#fff; font-weight:700; padding:6px 14px; border-radius:8px; display:inline-flex; align-items:center; gap:6px; cursor:pointer;" title="تطبيق النسخة الحالية">
                          <i class="fa-solid fa-check"></i> تطبيق القالب
                        </button>
                      `;
                    }

                    if (hasVarieties) {
                      return `
                        <button type="button" class="btn-download-single-var btn btn-sm ${isInitialVarCached ? 'cached' : ''}" data-tmpl-id="${escapeHtml(t.id)}" data-variety-idx="0" data-url="${escapeHtml(initialVarUrl)}" data-name="${escapeHtml(initialVarName)}" title="${isInitialVarCached ? 'النمط المختار محمل مسبقاً' : 'تحميل النمط المختار حالياً فقط'}">
                          ${isInitialVarCached 
                            ? `<i class="fa-solid fa-circle-check" style="color:#10b981;"></i> <span>النمط جاهز</span>` 
                            : `<i class="fa-solid fa-download"></i> <span>تحميل هذا النمط</span>`
                          }
                        </button>
                        ${!isCached ? `
                          <button type="button" class="btn-prerender-template-card btn btn-sm" data-tmpl-id="${escapeHtml(t.id)}" title="تحميل وتجهيز جميع الأنماط (${t.varieties.length}) دفعة واحدة">
                            <i class="fa-solid fa-cloud-arrow-down"></i> <span>تحميل الكل (${t.varieties.length})</span> <span class="prerender-size-badge">${sizeStr}</span>
                          </button>
                        ` : ''}
                        <button type="button" class="btn-apply-template-card btn btn-sm btn-primary ${canApply ? '' : 'hidden'}" data-name="${escapeHtml(t.name)}" data-id="${escapeHtml(t.id || '')}" data-iscustom="${t.isCustom ? '1' : '0'}" data-selected-variety-idx="0" data-selected-variety-url="${escapeHtml(initialVarUrl)}" data-selected-variety-name="${escapeHtml(initialVarName)}" style="background:#2563eb; color:#fff; font-weight:700; padding:6px 14px; border-radius:8px; display:${canApply ? 'inline-flex' : 'none'}; align-items:center; gap:6px; cursor:pointer;" title="تطبيق هذا القالب">
                          <i class="fa-solid fa-check"></i> تطبيق القالب
                        </button>
                      `;
                    }

                    return `
                      ${!isCached ? `
                        <button type="button" class="btn-prerender-template-card btn btn-sm" data-tmpl-id="${escapeHtml(t.id)}" title="تحميل وتجهيز كافة وسائط وخلفيات القالب مسبقاً في الذاكرة لتجنب أي بطء أثناء العرض">
                          <i class="fa-solid fa-cloud-arrow-down"></i> <span>تحميل وتجهيز القالب</span> <span class="prerender-size-badge">${sizeStr}</span>
                        </button>
                      ` : ''}
                      <button type="button" class="btn-apply-template-card btn btn-sm btn-primary ${isCached ? '' : 'hidden'}" data-name="${escapeHtml(t.name)}" data-id="${escapeHtml(t.id || '')}" data-iscustom="${t.isCustom ? '1' : '0'}" style="background:#2563eb; color:#fff; font-weight:700; padding:6px 14px; border-radius:8px; display:${isCached ? 'inline-flex' : 'none'}; align-items:center; gap:6px; cursor:pointer;">
                        <i class="fa-solid fa-check"></i> تطبيق القالب
                      </button>
                    `;
                  })()}
                </div>
                ${t.isCustom ? `
                  <div style="display:flex; align-items:center; gap:4px;">
                    <button type="button" class="btn-export-template-zip btn btn-sm btn-secondary" data-id="${escapeHtml(t.id)}" style="background:#f1f5f9; color:#475569; font-size:0.75rem; padding:5px 8px; border-radius:6px;" title="تصدير كملف ZIP">
                      <i class="fa-solid fa-file-zipper"></i> ZIP
                    </button>
                    <button type="button" class="btn-delete-saved-template btn btn-sm btn-danger" data-id="${escapeHtml(t.id)}" style="background:#fee2e2; color:#ef4444; font-size:0.75rem; padding:5px 8px; border-radius:6px; border:none; cursor:pointer;" title="حذف القالب">
                      <i class="fa-solid fa-trash"></i>
                    </button>
                  </div>
                ` : ''}
              </div>
            </div>
          </div>
        `;
      }).join('');

      // Single Variety Download button listeners
      container.querySelectorAll('.btn-download-single-var').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const tmplId = btn.dataset.tmplId;
          const url = btn.dataset.url;
          const name = btn.dataset.name;
          const varietyIdx = parseInt(btn.dataset.varietyIdx, 10);
          const allTmpls = (typeof sanitizeAndGroupTemplates === 'function') 
            ? sanitizeAndGroupTemplates(state.availableTemplates || []) 
            : (state.availableTemplates || []);
          const tmpl = allTmpls.find(t => t.id === tmplId);
          if (!tmpl || !tmpl.varieties) return;
          const variety = (!isNaN(varietyIdx) && tmpl.varieties[varietyIdx])
            ? tmpl.varieties[varietyIdx]
            : (tmpl.varieties.find(v => v.url === url) || { url, name });
          const card = btn.closest('.template-preview-card');
          await downloadSingleVariety(tmpl, variety, btn, card);
        });
      });

      // Pre-render & Download button listeners
      container.querySelectorAll('.btn-prerender-template-card').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const tmplId = btn.dataset.tmplId;
          const allTmpls = (typeof sanitizeAndGroupTemplates === 'function') 
            ? sanitizeAndGroupTemplates(state.availableTemplates || []) 
            : (state.availableTemplates || []);
          const tmpl = allTmpls.find(t => t.id === tmplId);
          if (tmpl) {
            await prerenderTemplateAssets(tmpl, btn);
          }
        });
      });

      // Update Template button listeners
      container.querySelectorAll('.btn-update-template-card').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const tmplId = btn.dataset.tmplId;
          const allTmpls = (typeof sanitizeAndGroupTemplates === 'function') 
            ? sanitizeAndGroupTemplates(state.availableTemplates || []) 
            : (state.availableTemplates || []);
          const tmpl = allTmpls.find(t => t.id === tmplId);
          if (tmpl) {
            await prerenderTemplateAssets(tmpl, btn);
          }
        });
      });

      // Shuffle checkbox listeners
      container.querySelectorAll('.chk-template-shuffle').forEach(chk => {
        chk.addEventListener('change', (e) => {
          const tmplId = chk.dataset.tmplId;
          const isChecked = chk.checked;
          setTemplateShuffleEnabled(isChecked, tmplId);
          if (isChecked) {
            lastShuffledSongKey = null;
            if (state.activeSong) {
              triggerAutoShuffleGroupedTemplateIfNeeded(state.activeSong);
            }
            showToast('تم تفعيل التبديل العشوائي لكل ترنيمة بدون تكرار! 🔀');
          } else {
            showToast('تم إيقاف التبديل العشوائي.');
          }
        });
      });

      // Add variety circle click listeners
      container.querySelectorAll('.template-variety-circle').forEach(circle => {
        circle.addEventListener('click', (e) => {
          e.stopPropagation();
          const tmplId = circle.dataset.tmplId;
          const url = circle.dataset.url;
          const thumbUrl = circle.dataset.thumbUrl || url;
          const name = circle.dataset.name;
          const varietyIdx = circle.dataset.varietyIdx;

          const bar = circle.closest('.template-varieties-bar');
          if (bar) {
            bar.querySelectorAll('.template-variety-circle').forEach(c => c.classList.remove('active'));
          }
          circle.classList.add('active');

          const card = circle.closest('.template-preview-card');
          if (card) {
            const thumbImg = card.querySelector(`#tmpl-thumb-img-${tmplId}`);
            if (thumbImg) thumbImg.src = thumbUrl;

            const nameEl = card.querySelector(`#tmpl-selected-var-name-${tmplId}`);
            if (nameEl) nameEl.textContent = name;

            const badgeEl = card.querySelector(`#tmpl-selected-var-badge-${tmplId}`);
            if (badgeEl) badgeEl.innerHTML = `<i class="fa-solid fa-palette"></i> ${escapeHtml(name)}`;

            const isVarCached = isVarietyUrlCached(url, tmplId);

            // Update single download button state
            const singleBtn = card.querySelector('.btn-download-single-var');
            if (singleBtn) {
              singleBtn.dataset.url = url;
              singleBtn.dataset.name = name;
              singleBtn.dataset.varietyIdx = varietyIdx;
              if (isVarCached) {
                singleBtn.classList.add('cached');
                singleBtn.classList.remove('downloading');
                singleBtn.innerHTML = `<i class="fa-solid fa-circle-check" style="color:#10b981;"></i> <span>النمط جاهز</span>`;
                singleBtn.title = `النمط "${name}" محمل مسبقاً وجاهز للعرض`;
              } else {
                singleBtn.classList.remove('cached', 'downloading');
                singleBtn.innerHTML = `<i class="fa-solid fa-download"></i> <span>تحميل هذا النمط</span>`;
                singleBtn.title = `تحميل النمط "${name}" فقط`;
              }
            }

            // Update status pill
            const statusPill = card.querySelector(`#tmpl-var-status-${tmplId}`);
            if (statusPill) {
              if (isVarCached) {
                statusPill.className = 'variety-status-pill cached';
                statusPill.innerHTML = '<i class="fa-solid fa-circle-check"></i> جاهز';
              } else {
                statusPill.className = 'variety-status-pill not-cached';
                statusPill.innerHTML = '<i class="fa-solid fa-cloud"></i> غير محمل';
              }
            }

            // Update apply button
            const applyBtn = card.querySelector('.btn-apply-template-card');
            if (applyBtn) {
              applyBtn.dataset.selectedVarietyIdx = varietyIdx;
              applyBtn.dataset.selectedVarietyUrl = url;
              applyBtn.dataset.selectedVarietyName = name;
              const isTmplCached = isTemplatePrerendered(tmplId);
              if (isVarCached || isTmplCached) {
                applyBtn.style.display = 'inline-flex';
                applyBtn.classList.remove('hidden');
              } else {
                applyBtn.style.display = 'none';
                applyBtn.classList.add('hidden');
              }
            }
          }
        });
      });

      // Add click listeners to apply buttons
      container.querySelectorAll('.btn-apply-template-card').forEach(btn => {
        btn.addEventListener('click', () => {
          const isCustom = btn.dataset.iscustom === '1';
          const name = btn.dataset.name;
          const id = btn.dataset.id;

          if (isCustom) {
            const t = getSavedTemplates().find(item => item.id === id || item.name === name);
            if (t) applyFullTemplate(t);
          } else {
            const tmpl = (state.availableTemplates || []).find(t => t.id === id || t.name === name);
            if (tmpl) {
              const selectedVarUrl = btn.dataset.selectedVarietyUrl;
              const selectedVarName = btn.dataset.selectedVarietyName;
              const selectedVarIdx = parseInt(btn.dataset.selectedVarietyIdx, 10);

              let matchedVar = null;
              if (tmpl && Array.isArray(tmpl.varieties) && tmpl.varieties.length > 0) {
                if (!isNaN(selectedVarIdx) && tmpl.varieties[selectedVarIdx]) {
                  matchedVar = tmpl.varieties[selectedVarIdx];
                } else if (selectedVarName) {
                  matchedVar = tmpl.varieties.find(v => v.name === selectedVarName);
                }
                if (!matchedVar && selectedVarUrl) {
                  matchedVar = tmpl.varieties.find(v => v.url === selectedVarUrl);
                }
                if (!matchedVar) {
                  matchedVar = tmpl.varieties[0];
                }
              }

              state.selectedTemplateId = tmpl.id;
              localStorage.setItem('sunday_school_active_template_id', tmpl.id);

              if (selectedVarUrl) {
                state.standbyConfig.type = 'template';
                state.standbyConfig.templateId = tmpl.id;
                state.standbyConfig.url = selectedVarUrl;
                state.standbyConfig.showLogo = (tmpl && tmpl.showLogo !== undefined) ? Boolean(tmpl.showLogo) : (tmpl && tmpl.id !== 'tmpl-shabahak-akon-2026' && tmpl.id !== 'tmpl-broadcast-chroma-green');
                state.slidesBgConfig.type = 'template';
                state.slidesBgConfig.templateId = tmpl.id;
                state.slidesBgConfig.url = selectedVarUrl;
              } else {
                if (tmpl.standby) {
                  state.standbyConfig.type = 'template';
                  state.standbyConfig.templateId = tmpl.id;
                  state.standbyConfig.url = tmpl.standby;
                  state.standbyConfig.showLogo = (tmpl.showLogo !== undefined) ? Boolean(tmpl.showLogo) : (tmpl.id !== 'tmpl-shabahak-akon-2026' && tmpl.id !== 'tmpl-broadcast-chroma-green');
                }
                if (tmpl.slidesBg) {
                  state.slidesBgConfig.type = 'template';
                  state.slidesBgConfig.templateId = tmpl.id;
                  state.slidesBgConfig.url = tmpl.slidesBg;
                }
              }
              if (tmpl.transitionConfig) {
                state.transitionConfig = JSON.parse(JSON.stringify(tmpl.transitionConfig));
              } else if (tmpl.stringer) {
                state.transitionConfig.type = 'stinger';
                state.transitionConfig.stingerUrl = tmpl.stringer;
              }
              if (tmpl.styleOptions) {
                state.styleOptions = JSON.parse(JSON.stringify(tmpl.styleOptions));
              }
              if (tmpl.selectedFont) {
                state.selectedFont = tmpl.selectedFont;
                if (els.fontFamilySelect) els.fontFamilySelect.value = tmpl.selectedFont;
              }
              if (matchedVar && matchedVar.fontSize) {
                state.fontSize = matchedVar.fontSize;
              } else if (tmpl.fontSize) {
                state.fontSize = tmpl.fontSize;
              }
              if (matchedVar && matchedVar.textTransform) {
                state.textTransform = JSON.parse(JSON.stringify(matchedVar.textTransform));
              } else if (tmpl.textTransform) {
                state.textTransform = JSON.parse(JSON.stringify(tmpl.textTransform));
              }
              if (tmpl.hideControls !== undefined) {
                state.hideControls = Boolean(tmpl.hideControls);
                try { localStorage.setItem('sunday_school_taranim_hide_controls', state.hideControls); } catch(e) {}
                const chkHide = document.getElementById('btn-toggle-hide-controls');
                if (chkHide) chkHide.checked = state.hideControls;
                if (els.obsOverlay) els.obsOverlay.classList.toggle('controls-hidden', state.hideControls);
              }
              if (tmpl.presentationMode) {
                setSlideSplittingMode(tmpl.presentationMode);
              }
              if (typeof updateTextTransformUI === 'function') updateTextTransformUI();
              updateStandbyUI();
              updateSlidesBgUI();
              updateTransitionUI();
              if (typeof updateControlPanelFromState === 'function') updateControlPanelFromState();
              saveUserSettings();
              saveMediaConfig();
              if (state.activeSong && typeof loadSongIntoPresentation === 'function') {
                loadSongIntoPresentation(state.activeSong, false);
              }
              syncLiveState(false, false, { triggerTransition: true });
              showToast(`تم تطبيق قالب "${tmpl.name}" ${selectedVarName ? `(${selectedVarName})` : ''} بالكامل! 🎬`);
            }
          }
        });
      });

      // Export ZIP buttons
      container.querySelectorAll('.btn-export-template-zip').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          const t = getSavedTemplates().find(item => item.id === id);
          if (t) exportTemplateZip(t);
        });
      });

      // Delete buttons
      container.querySelectorAll('.btn-delete-saved-template').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          const list = getSavedTemplates().filter(item => item.id !== id);
          saveSavedTemplates(list);
          showToast('تم حذف القالب');
        });
      });
    };

    // Category filter button click events
    const catBar = document.getElementById('templates-categories-bar');
    if (catBar) {
      catBar.querySelectorAll('.tmpl-category-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          catBar.querySelectorAll('.tmpl-category-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          state.activeTemplateCategory = btn.dataset.cat || 'all';
          renderTemplatesCatalog();
        });
      });
    }

    const renderBuiltinTemplates = renderTemplatesCatalog;
    const renderSavedTemplates = renderTemplatesCatalog;

    const applyFullTemplate = (t) => {
      if (!t) return;
      const tmplId = t.id || t.name;
      state.selectedTemplateId = tmplId;
      localStorage.setItem('sunday_school_active_template_id', tmplId);

      if (t.styleOptions) state.styleOptions = JSON.parse(JSON.stringify(t.styleOptions));
      if (t.fontSize) state.fontSize = t.fontSize;
      if (t.selectedFont) state.selectedFont = t.selectedFont;
      if (t.customFontDataUrl) state.customFontDataUrl = t.customFontDataUrl;
      if (t.chromaKey) state.chromaKey = t.chromaKey;
      if (t.textAnimation) state.textAnimation = t.textAnimation;
      if (t.slidesBgConfig) {
        state.slidesBgConfig = JSON.parse(JSON.stringify(t.slidesBgConfig));
        state.slidesBgConfig.templateId = tmplId;
      }
      if (t.standbyConfig) {
        state.standbyConfig = JSON.parse(JSON.stringify(t.standbyConfig));
        state.standbyConfig.templateId = tmplId;
      }
      if (t.transitionConfig) state.transitionConfig = JSON.parse(JSON.stringify(t.transitionConfig));
      if (t.textTransform) state.textTransform = JSON.parse(JSON.stringify(t.textTransform));

      updateSlidesBgUI();
      updateTextTransformUI();
      updateStandbyUI();
      updateTransitionUI();
      saveUserSettings();
      saveMediaConfig();
      syncLiveState(false, false, { triggerTransition: true });
      showToast(`تم تطبيق قالب "${t.name}" بنجاح! `);
    };

    const exportTemplateZip = async (template) => {
      if (typeof JSZip === 'undefined') {
        showToast('جاري تحميل مكتبة ZIP...');
        return;
      }
      showToast('جاري تجهيز وتصدير ملف الـ ZIP...');
      try {
        const zip = new JSZip();
        const folderName = (template.name || 'Template').replace(/[\\/:*?"<>|]/g, '_');
        const root = zip.folder(folderName);
        const cleanT = JSON.parse(JSON.stringify(template));

        // 1. Package Standby Media
        if (template.standbyConfig && template.standbyConfig.url) {
          let blob = null;
          let ext = 'mp4';
          if (template.standbyConfig.url.startsWith('data:')) {
            blob = dataURLtoBlob(template.standbyConfig.url);
            if (blob && blob.type.includes('png')) ext = 'png';
            else if (blob && blob.type.includes('jpeg')) ext = 'jpg';
            else if (blob && blob.type.includes('webm')) ext = 'webm';
          } else {
            blob = await fetchFileAsBlob(template.standbyConfig.url);
            const m = template.standbyConfig.url.match(/\.([a-zA-Z0-9]+)$/);
            if (m) ext = m[1];
          }
          if (blob) {
            const fileName = `Standby_Media.${ext}`;
            root.folder('Standby').file(fileName, blob);
            cleanT.standbyConfig.url = `Templates/Standby/${folderName}/${fileName}`;
          }
        }

        // 2. Package SlidesBg Media
        if (template.slidesBgConfig && template.slidesBgConfig.url) {
          let blob = null;
          let ext = 'mp4';
          if (template.slidesBgConfig.url.startsWith('data:')) {
            blob = dataURLtoBlob(template.slidesBgConfig.url);
            if (blob && blob.type.includes('png')) ext = 'png';
            else if (blob && blob.type.includes('jpeg')) ext = 'jpg';
            else if (blob && blob.type.includes('webm')) ext = 'webm';
          } else {
            blob = await fetchFileAsBlob(template.slidesBgConfig.url);
            const m = template.slidesBgConfig.url.match(/\.([a-zA-Z0-9]+)$/);
            if (m) ext = m[1];
          }
          if (blob) {
            const fileName = `SlidesBg_Media.${ext}`;
            root.folder('SlidesBg').file(fileName, blob);
            cleanT.slidesBgConfig.url = `Templates/SlidesBg/${folderName}/${fileName}`;
          }
        }

        // 3. Package Stinger Media
        if (template.transitionConfig && template.transitionConfig.stingerUrl) {
          let blob = null;
          let ext = 'webm';
          if (template.transitionConfig.stingerUrl.startsWith('data:')) {
            blob = dataURLtoBlob(template.transitionConfig.stingerUrl);
            if (blob && blob.type.includes('mp4')) ext = 'mp4';
          } else {
            blob = await fetchFileAsBlob(template.transitionConfig.stingerUrl);
            const m = template.transitionConfig.stingerUrl.match(/\.([a-zA-Z0-9]+)$/);
            if (m) ext = m[1];
          }
          if (blob) {
            const fileName = `Stringer_Transition.${ext}`;
            root.folder('Stringer').file(fileName, blob);
            cleanT.transitionConfig.stingerUrl = `Templates/Stringer/${folderName}/${fileName}`;
          }
        }

        root.file('template.json', JSON.stringify(cleanT, null, 2));

        const content = await zip.generateAsync({ type: 'blob' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(content);
        a.download = `${folderName}.zip`;
        a.click();
        showToast(`تم تصدير قالب "${template.name}" كملف ZIP بنجاح! `);
      } catch(err) {
        showToast('تعذر تصدير ملف الـ ZIP');
      }
    };

    const handleImportTemplateFile = async (file) => {
      if (!file) return;
      if (file.name.endsWith('.zip')) {
        if (typeof JSZip === 'undefined') {
          showToast('مكتبة ZIP غير متوفرة');
          return;
        }
        showToast('جاري قراءة واستخراج حزمة القالب...');
        try {
          const zip = await JSZip.loadAsync(file);
          let templateJsonStr = null;
          const mediaDataUrls = {};

          for (const path in zip.files) {
            const entry = zip.files[path];
            if (entry.dir) continue;
            if (path.endsWith('template.json') || path.endsWith('.json')) {
              templateJsonStr = await entry.async('string');
            } else {
              const blob = await entry.async('blob');
              const dataUrl = await new Promise(res => {
                const r = new FileReader();
                r.onload = e => res(e.target.result);
                r.readAsDataURL(blob);
              });
              if (path.includes('Standby')) mediaDataUrls.standby = dataUrl;
              else if (path.includes('SlidesBg')) mediaDataUrls.slidesBg = dataUrl;
              else if (path.includes('Stringer')) mediaDataUrls.stringer = dataUrl;
            }
          }

          if (templateJsonStr) {
            const parsed = JSON.parse(templateJsonStr);
            if (mediaDataUrls.standby && parsed.standbyConfig) {
              parsed.standbyConfig.url = mediaDataUrls.standby;
              parsed.standbyConfig.type = mediaDataUrls.standby.startsWith('data:video') ? 'custom_video' : 'custom_image';
            }
            if (mediaDataUrls.slidesBg && parsed.slidesBgConfig) {
              parsed.slidesBgConfig.url = mediaDataUrls.slidesBg;
              parsed.slidesBgConfig.type = mediaDataUrls.slidesBg.startsWith('data:video') ? 'custom_video' : 'custom_image';
            }
            if (mediaDataUrls.stringer && parsed.transitionConfig) {
              parsed.transitionConfig.stingerUrl = mediaDataUrls.stringer;
            }

            parsed.id = 'template_' + Date.now();
            const list = getSavedTemplates();
            list.unshift(parsed);
            saveSavedTemplates(list);
            applyFullTemplate(parsed);
            showToast(`تم استيراد وتطبيق قالب "${parsed.name || file.name}" بنجاح! `);
          } else {
            showToast('لم يتم العثور على template.json في ملف الـ ZIP');
          }
        } catch(err) {
          showToast('حدث خطأ أثناء استيراد ملف الـ ZIP');
        }
      } else if (file.name.endsWith('.json')) {
        const reader = new FileReader();
        reader.onload = (e) => {
          try {
            const parsed = JSON.parse(e.target.result);
            const list = getSavedTemplates();
            if (Array.isArray(parsed)) {
              parsed.forEach(t => {
                t.id = 'template_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
                list.unshift(t);
              });
            } else {
              parsed.id = 'template_' + Date.now();
              list.unshift(parsed);
              applyFullTemplate(parsed);
            }
            saveSavedTemplates(list);
            showToast('تم استيراد القالب بنجاح!');
          } catch(err) {
            showToast('ملف JSON غير صالح', 'error');
          }
        };
        reader.readAsText(file);
      }
    };

    const importTemplateFileInput = document.getElementById('import-template-file-input');
    if (importTemplateFileInput) {
      importTemplateFileInput.addEventListener('change', (e) => {
        const file = e.target.files && e.target.files[0];
        if (file) handleImportTemplateFile(file);
      });
    }

    const btnExportAllTemplates = document.getElementById('btn-export-all-templates');
    if (btnExportAllTemplates) {
      btnExportAllTemplates.addEventListener('click', async () => {
        const list = getSavedTemplates();
        if (list.length === 0) {
          showToast('لا توجد قوالب محفوظة لتصديرها');
          return;
        }
        if (typeof JSZip === 'undefined') {
          showToast('جاري تحميل مكتبة ZIP...');
          return;
        }
        showToast('جاري حزم جميع القوالب في ملف ZIP...');
        try {
          const zip = new JSZip();
          for (const t of list) {
            const fName = (t.name || 'Template').replace(/[\\/:*?"<>|]/g, '_');
            const sub = zip.folder(fName);
            sub.file('template.json', JSON.stringify(t, null, 2));
          }
          const blob = await zip.generateAsync({ type: 'blob' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = `Taranim_All_Templates_${Date.now()}.zip`;
          a.click();
          showToast('تم تصدير جميع القوالب في ملف ZIP بنجاح! ');
        } catch(e) {
          showToast('تعذر تصدير الحزمة');
        }
      });
    }

