  function getFontDisplayName(fontVal) {
    if (!fontVal) return 'Alexandria (الإسكندرية)';
    if (fontVal === 'custom' || String(fontVal).startsWith('CustomFont_')) {
      const savedName = localStorage.getItem('sunday_school_custom_font_name');
      return savedName ? `خط مخصص: ${savedName}` : 'خط مخصص من الجهاز';
    }
    const found = AVAILABLE_FONTS.find(f => f.value === fontVal || fontVal.includes(f.name.split(' ')[0]));
    return found ? found.name : fontVal.replace(/['",]/g, '').trim();
  }

  function renderCustomFontDropdown(filterQuery = '') {
    const listEl = document.getElementById('font-dropdown-items-list');
    const nameEl = document.getElementById('font-dropdown-current-name');
    if (!listEl) return;

    if (nameEl) {
      nameEl.textContent = getFontDisplayName(state.selectedFont);
      if (state.selectedFont && state.selectedFont !== 'custom') {
        nameEl.style.fontFamily = state.selectedFont;
      } else {
        nameEl.style.fontFamily = 'inherit';
      }
    }

    const q = (filterQuery || '').trim().toLowerCase();
    const filtered = AVAILABLE_FONTS.filter(f => {
      if (!q) return true;
      return f.name.toLowerCase().includes(q) || f.value.toLowerCase().includes(q);
    });

    if (filtered.length === 0) {
      listEl.innerHTML = `<div style="text-align:center; padding:16px; color:#94a3b8; font-size:0.8rem;">لا توجد خطوط مطابقة للبحث</div>`;
      return;
    }

    listEl.innerHTML = filtered.map(f => {
      const isCurrent = (state.selectedFont === f.value) || 
        (!f.isCustomOption && state.selectedFont && f.value && (state.selectedFont.includes(f.name.split(' ')[0])));
      
      return `
        <div class="font-dropdown-item ${isCurrent ? 'active' : ''}" data-font-value="${escapeHtml(f.value)}" data-font-name="${escapeHtml(f.name)}" data-is-custom="${f.isCustomOption ? '1' : '0'}">
          <div class="font-item-top">
            <span class="font-item-name">${escapeHtml(f.name)}</span>
            ${isCurrent ? '<i class="fa-solid fa-check font-item-check"></i>' : ''}
          </div>
          ${!f.isCustomOption ? `
            <div class="font-item-preview" style="font-family:${escapeHtml(f.value)};">
              ترنيمة جديدة للرب • هللويا
            </div>
          ` : `
            <div class="font-item-preview" style="font-size:0.75rem; color:#64748b; font-family:inherit;">
              <i class="fa-solid fa-cloud-arrow-up"></i> رفع ملف خط TTF / WOFF / OTF من جهازك
            </div>
          `}
        </div>
      `;
    }).join('');

    listEl.querySelectorAll('.font-dropdown-item').forEach(item => {
      item.addEventListener('click', (e) => {
        e.stopPropagation();
        const fontVal = item.dataset.fontValue;
        const isCustom = item.dataset.isCustom === '1';

        // Close dropdown
        const menu = document.getElementById('font-custom-dropdown-menu');
        const toggleBtn = document.getElementById('btn-font-dropdown-toggle');
        if (menu) menu.classList.add('hidden');
        if (toggleBtn) toggleBtn.classList.remove('open');

        if (isCustom || fontVal === 'custom') {
          if (els.customFontWrapper) els.customFontWrapper.classList.remove('hidden');
          const savedCustomFontName = localStorage.getItem('sunday_school_custom_font_name');
          if (savedCustomFontName) {
            applyFont(`"${savedCustomFontName}", sans-serif`);
          } else if (els.customFontInput && els.customFontInput.value.trim()) {
            applyFont(els.customFontInput.value.trim());
          } else {
            applyFont('sans-serif');
          }
        } else {
          if (els.customFontWrapper) els.customFontWrapper.classList.add('hidden');
          applyFont(fontVal);
        }

        if (els.fontSelect) els.fontSelect.value = fontVal;
        renderCustomFontDropdown();
      });
    });
  }

  function applyFont(fontFamily) {
    state.selectedFont = fontFamily;
    document.documentElement.style.setProperty('--slide-font-family', fontFamily);
    if (els.obsLineText) els.obsLineText.style.fontFamily = fontFamily;
    const isJomhuriaFont = /jomhuria/i.test(fontFamily || '');
    if (state.scaleMode === 'auto') {
      state.styleOptions.lineHeight = isJomhuriaFont ? 0.92 : 1.18;
      if (els.obsLineHeightRange) els.obsLineHeightRange.value = state.styleOptions.lineHeight;
    }
    updateJustifyButtonState();
    saveUserSettings();
    syncLiveState();
  }

  async function loadInitialData() {
    const startupOverlay = document.getElementById('startup-loading-overlay') || document.getElementById('startup-overlay');
    if (startupOverlay) {
      startupOverlay.classList.add('fade-out');
      startupOverlay.style.display = 'none';
      try { startupOverlay.remove(); } catch(e) {}
    }
    document.body.classList.remove('startup-active');

    // Helper: index raw catalog items with fast search keys & deep slide lines
    const indexCatalogList = (list) => {
      if (!Array.isArray(list)) return [];
      return list.map(song => {
        const allLines = getSongAllLines(song);
        const tNorm = normalizeArabic(song.title || '');
        const nNorm = allLines.map(normalizeArabic).join(' ');
        const tSkeleton = typeof extractArabicConsonantSkeleton === 'function' ? extractArabicConsonantSkeleton(song.title || '') : '';
        const nSkeleton = typeof extractArabicConsonantSkeleton === 'function' ? extractArabicConsonantSkeleton(nNorm) : '';
        return {
          ...song,
          _allLines: allLines,
          _tNorm: tNorm,
          _nNorm: nNorm,
          _fullTextNorm: tNorm + ' ' + nNorm,
          _tSkeleton: tSkeleton,
          _nSkeleton: nSkeleton,
          _searchIndex: tNorm + ' ' + tSkeleton + ' ' + nNorm + ' ' + nSkeleton
        };
      });
    };

    // Helper: index Bible chapters data for instant local search
    const indexBibleChaptersData = (bibleData) => {
      if (!bibleData || typeof bibleData !== 'object') return [];
      const chaptersList = Object.values(bibleData);
      return chaptersList.map(chapter => {
        const allLines = getSongAllLines(chapter);
        const tNorm = normalizeArabic(chapter.title || '');
        const nNorm = allLines.map(normalizeArabic).join(' ');
        const tSkeleton = typeof extractArabicConsonantSkeleton === 'function' ? extractArabicConsonantSkeleton(chapter.title || '') : '';
        const nSkeleton = typeof extractArabicConsonantSkeleton === 'function' ? extractArabicConsonantSkeleton(nNorm) : '';
        return {
          ...chapter,
          is_bible: true,
          _allLines: allLines,
          _tNorm: tNorm,
          _nNorm: nNorm,
          _fullTextNorm: tNorm + ' ' + nNorm,
          _tSkeleton: tSkeleton,
          _nSkeleton: nSkeleton,
          _searchIndex: tNorm + ' ' + tSkeleton + ' ' + nNorm + ' ' + nSkeleton
        };
      });
    };

    if (els.totalSongsCount) {
      const formatted = Number(11611).toLocaleString('ar-EG');
      els.totalSongsCount.innerHTML = `<i class="fa-solid fa-music"></i> <span>${formatted} ترنيمة</span>`;
    }

    // 1. FAST 0MS OFFLINE RECOVERY FROM INDEXEDDB (INSTANT AVAILABILITY ON COLD START)
    try {
      if (typeof TaranimDB !== 'undefined') {
        const [savedCatalog, savedBible] = await Promise.all([
          TaranimDB.get('songs_catalog'),
          TaranimDB.get('bible_chapters_data')
        ]);
        if (savedCatalog && Array.isArray(savedCatalog) && savedCatalog.length > 0) {
          state.allSongs = indexCatalogList(savedCatalog);
          syncCustomSongsIntoCatalog();
          if (els.totalSongsCount) {
            const formatted = Number(state.allSongs.length).toLocaleString('ar-EG');
            els.totalSongsCount.innerHTML = `<i class="fa-solid fa-music"></i> <span>${formatted} ترنيمة</span>`;
          }
        }
        if (savedBible && typeof savedBible === 'object' && Object.keys(savedBible).length > 0) {
          state.bibleChaptersData = savedBible;
          state.allBibleChapters = indexBibleChaptersData(savedBible);
        }
      }
    } catch(e) {}

    // 2. PARALLEL NETWORK / CACHE SYNC & PERSISTENCE
    try {
      const pathDir = window.location.pathname.replace(/\/[^\/]*$/, '/');
      const fetchCatalog = (async () => {
        try {
          const r = await fetch('./songs_catalog.json');
          if (r && r.ok) return await r.json();
        } catch(e) {}
        // Fallback: Check caches explicitly
        if ('caches' in window) {
          try {
            const keys = await caches.keys();
            for (const k of keys) {
              const cache = await caches.open(k);
              const m = await cache.match('./songs_catalog.json', { ignoreSearch: true });
              if (m && m.ok) return await m.json();
            }
          } catch(e) {}
        }
        return null;
      })();

      const fetchBible = (async () => {
        try {
          const r = await fetch('./bible_chapters_data.json');
          if (r && r.ok) return await r.json();
        } catch(e) {}
        try {
          const r2 = await fetch(`${window.location.origin}${pathDir}bible_chapters_data.json`);
          if (r2 && r2.ok) return await r2.json();
        } catch(e) {}
        if ('caches' in window) {
          try {
            const keys = await caches.keys();
            for (const k of keys) {
              const cache = await caches.open(k);
              const m = await cache.match('./bible_chapters_data.json', { ignoreSearch: true });
              if (m && m.ok) return await m.json();
            }
          } catch(e) {}
        }
        return null;
      })();

      const fetchCustomCatalog = (async () => {
        try {
          const r = await fetch('./custom_catalog.json');
          if (r && r.ok) return await r.json();
        } catch(e) {}
        try {
          const r2 = await fetch(`${window.location.origin}${pathDir}custom_catalog.json`);
          if (r2 && r2.ok) return await r2.json();
        } catch(e) {}
        try {
          const r3 = await fetch(`${window.location.origin}${pathDir}api.php?action=custom_catalog`);
          if (r3 && r3.ok) return await r3.json();
        } catch(e) {}
        return null;
      })();

      const [data, bibleData, customData] = await Promise.all([fetchCatalog, fetchBible, fetchCustomCatalog]);

      if (data) {
        let rawList = Array.isArray(data) ? data : (data && data.songs ? data.songs : []);
        if (rawList.length > 0) {
          state.allSongs = indexCatalogList(rawList);
          if (typeof TaranimDB !== 'undefined') {
            TaranimDB.set('songs_catalog', rawList);
          }

          // Check if newly fetched catalog has more hymns than installed offline
          const installedCount = parseInt(localStorage.getItem('taranim_offline_installed_count') || '0', 10);
          const initialDone = localStorage.getItem('taranim_pwa_initial_download_done') === 'true';
          if (initialDone && installedCount > 0 && rawList.length > installedCount) {
            const diff = rawList.length - installedCount;
            if (els.btnMenuInstall) els.btnMenuInstall.style.display = 'inline-flex';
            setInstallButtonUpdateState(true, diff);
            const promptKey = `taranim_new_songs_prompt_${rawList.length}`;
            if (!sessionStorage.getItem(promptKey)) {
              sessionStorage.setItem(promptKey, 'true');
              setTimeout(() => {
                showOfflinePromptModal({
                  title: '🔔 ترانيم جديدة متاحة للتنزيل!',
                  message: `تم إضافة <strong>${Number(diff).toLocaleString('ar-EG')}</strong> ترنيمة جديدة! قم بالتنزيل الآن لتحديث مكتبتك والعمل بدون إنترنت.`,
                  btnText: 'تحديث وتنزيل الترانيم الآن',
                  isUpdate: true,
                  diffCount: diff
                });
              }, 1200);
            }
          }
        }
      }

      // Merge community accepted custom songs into state.allSongs
      if (customData && Array.isArray(customData) && customData.length > 0) {
        const customIndexed = customData.map(cs => {
          cs.is_custom = true;
          cs.is_community = true;
          return indexSingleSongItem(cs);
        });
        if (!state.allSongs) state.allSongs = [];
        state.allSongs = [...customIndexed, ...state.allSongs];
      }

      if (bibleData && typeof bibleData === 'object' && Object.keys(bibleData).length > 0) {
        state.bibleChaptersData = bibleData;
        state.allBibleChapters = indexBibleChaptersData(bibleData);
        if (typeof TaranimDB !== 'undefined') {
          TaranimDB.set('bible_chapters_data', bibleData);
        }
      }

      // Sync and prepend local custom hymns into catalog index
      syncCustomSongsIntoCatalog();

      if (els.totalSongsCount && state.allSongs.length > 0) {
        const formatted = Number(state.allSongs.length).toLocaleString('ar-EG');
        els.totalSongsCount.innerHTML = `<i class="fa-solid fa-music"></i> <span>${formatted} ترنيمة</span>`;
      }
    } catch(e) {}

    // Re-hydrate active song from canonical catalog if restored on load
    if (state.activeSong && !state.activeSong.is_bible && (state.activeSong.id !== undefined || state.activeSong.item_id !== undefined)) {
      const songId = state.activeSong.id !== undefined ? state.activeSong.id : state.activeSong.item_id;
      const canonical = state.allSongs.find(s => !s.is_bible && (String(s.id) === String(songId) || String(s.item_id) === String(songId)));
      if (canonical) {
        const restoredSong = { ...canonical, ...state.activeSong };
        if (state.activeSong.verses && Array.isArray(state.activeSong.verses) && state.activeSong.verses.length > 0) {
          restoredSong.verses = state.activeSong.verses;
        }
        loadSongIntoPresentation(restoredSong);
        syncLiveState();
      }
    }
  }

  // ==========================================================================
  // LOCAL CUSTOM HYMN / TARNIMA CREATOR & MANAGER MODULE
  // ==========================================================================
  const CUSTOM_SONGS_STORAGE_KEY = 'sunday_school_custom_songs';

  let customSongBuilderState = {
    id: null,
    item_id: null,
    title: '',
    scale_id: '',
    media_url: '',
    is_custom: true,
    isEditing: false,
    activeTab: 'tab-song-builder',
    verses: []
  };

  function getStoredCustomSongs() {
    try {
      const raw = localStorage.getItem(CUSTOM_SONGS_STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  function setStoredCustomSongs(songsList) {
    try {
      localStorage.setItem(CUSTOM_SONGS_STORAGE_KEY, JSON.stringify(songsList));
    } catch (e) {}
  }

  function indexSingleSongItem(song) {
    if (!song) return song;
    const allLines = getSongAllLines(song);
    const tNorm = normalizeArabic(song.title || '');
    const nNorm = allLines.map(normalizeArabic).join(' ');
    const tSkeleton = typeof extractArabicConsonantSkeleton === 'function' ? extractArabicConsonantSkeleton(song.title || '') : '';
    const nSkeleton = typeof extractArabicConsonantSkeleton === 'function' ? extractArabicConsonantSkeleton(nNorm) : '';
    return {
      ...song,
      _allLines: allLines,
      _tNorm: tNorm,
      _nNorm: nNorm,
      _fullTextNorm: tNorm + ' ' + nNorm,
      _tSkeleton: tSkeleton,
      _nSkeleton: nSkeleton,
      _searchIndex: tNorm + ' ' + tSkeleton + ' ' + nNorm + ' ' + nSkeleton
    };
  }

  function syncCustomSongsIntoCatalog() {
    const customList = getStoredCustomSongs();
    if (!state.allSongs) state.allSongs = [];
    
    // Remove previous custom songs from catalog in memory
    state.allSongs = state.allSongs.filter(s => !s.is_custom && !String(s.id).startsWith('custom_'));
    
    // Index and prepend custom songs so they appear at top priority in search
    const indexedCustom = customList.map(song => {
      song.is_custom = true;
      return indexSingleSongItem(song);
    });

    state.allSongs = [...indexedCustom, ...state.allSongs];

    if (els.totalSongsCount && state.allSongs.length > 0) {
      const formatted = Number(state.allSongs.length).toLocaleString('ar-EG');
      els.totalSongsCount.innerHTML = `<i class="fa-solid fa-music"></i> <span>${formatted} ترنيمة</span>`;
    }
  }

  function initDefaultCustomSongVerses() {
    return [];
  }

  function openCustomSongEditor(songToEdit = null, reviewOptions = null) {
    if (!els.modalCustomSongEditor) return;

    if (songToEdit && (songToEdit.verses || songToEdit.title || songToEdit.id)) {
      // Editing existing custom or pre-populated song
      const songData = JSON.parse(JSON.stringify(songToEdit));
      customSongBuilderState = {
        id: songData.id || ('custom_' + Date.now()),
        item_id: songData.item_id || songData.id || ('custom_' + Date.now()),
        title: songData.title || '',
        scale_id: (songData.scale_id !== undefined && songData.scale_id !== null) ? songData.scale_id : '',
        media_url: songData.media_url || '',
        is_custom: true,
        isEditing: Boolean(songData.id && (songData.is_custom || String(songData.id).startsWith('custom_'))),
        isReviewMode: Boolean(reviewOptions && reviewOptions.submissionId),
        submissionId: reviewOptions ? reviewOptions.submissionId : null,
        reviewToken: reviewOptions ? reviewOptions.reviewToken : null,
        activeTab: 'tab-song-builder',
        verses: (Array.isArray(songData.verses) && songData.verses.length > 0) ? songData.verses : []
      };
      if (els.songEditorModalTitle) {
        els.songEditorModalTitle.textContent = customSongBuilderState.isReviewMode
          ? `مراجعة واعتماد ترنيمة: ${songData.title || ''}`
          : (customSongBuilderState.isEditing ? `تعديل ترنيمة: ${songData.title || 'مخصصة'}` : 'إضافة ترنيمة جديدة');
      }
    } else {
      // New custom song (starts clean with no default prefilled slides)
      const initialTitle = (songToEdit && typeof songToEdit === 'object' && songToEdit.title) ? songToEdit.title : '';
      customSongBuilderState = {
        id: 'custom_' + Date.now(),
        item_id: 'custom_' + Date.now(),
        title: initialTitle,
        scale_id: '',
        media_url: '',
        is_custom: true,
        isEditing: false,
        isReviewMode: false,
        submissionId: null,
        reviewToken: null,
        activeTab: 'tab-song-builder',
        verses: []
      };
      if (els.songEditorModalTitle) {
        els.songEditorModalTitle.textContent = 'إضافة ترنيمة جديدة';
      }
    }

    if (els.songEditorReviewBanner) {
      if (customSongBuilderState.isReviewMode) {
        els.songEditorReviewBanner.classList.remove('hidden');
        if (reviewOptions && reviewOptions.submitterName && els.songEditorReviewBannerText) {
          els.songEditorReviewBannerText.textContent = `وضع مراجعة ترنيمة مرسلة من: ${reviewOptions.submitterName}${reviewOptions.churchName ? ` (${reviewOptions.churchName})` : ''}`;
        }
      } else {
        els.songEditorReviewBanner.classList.add('hidden');
      }
    }

    if (els.songInputTitle) els.songInputTitle.value = customSongBuilderState.title;
    if (els.songInputScale) els.songInputScale.value = customSongBuilderState.scale_id || '';
    if (els.songInputMedia) els.songInputMedia.value = customSongBuilderState.media_url || '';

    switchCustomSongEditorTab('tab-song-builder');
    renderCustomSongBuilderUI();
    updateCustomSongLivePreview();

    els.modalCustomSongEditor.classList.remove('hidden');
    if (els.songInputTitle) els.songInputTitle.focus();
  }

  function closeCustomSongEditor() {
    if (els.modalCustomSongEditor) {
      els.modalCustomSongEditor.classList.add('hidden');
    }
  }

  function switchCustomSongEditorTab(targetTabId) {
    customSongBuilderState.activeTab = targetTabId;
    if (!els.modalCustomSongEditor) return;

    // Update Tab Nav Buttons
    els.modalCustomSongEditor.querySelectorAll('.song-editor-tab-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.tab === targetTabId);
    });

    // Update Tab Contents
    els.modalCustomSongEditor.querySelectorAll('.song-editor-tab-content').forEach(tab => {
      tab.classList.toggle('hidden', tab.id !== targetTabId);
      tab.classList.toggle('active', tab.id === targetTabId);
    });

    if (targetTabId === 'tab-song-builder') {
      renderCustomSongBuilderUI();
      updateCustomSongLivePreview();
    } else if (targetTabId === 'tab-song-json') {
      const songJson = buildCompleteSongObject();
      if (els.songRawJsonTextarea) {
        els.songRawJsonTextarea.value = JSON.stringify(songJson, null, 2);
      }
    } else if (targetTabId === 'tab-song-smart-paste') {
      if (els.smartPasteRawTextarea && !els.smartPasteRawTextarea.value.trim()) {
        const fullNotes = generateNotesFromVerses(customSongBuilderState.verses);
        els.smartPasteRawTextarea.value = fullNotes;
      }
    }
  }

  function generateNotesFromVerses(verses) {
    if (!Array.isArray(verses) || verses.length === 0) return '';
    return verses.map(v => {
      const isChorus = (v.type === 1 || v.isChorus === true);
      const prefix = isChorus ? '(القرار)\n' : '';
      const lines = [];
      (v.slides || []).forEach(s => {
        if (Array.isArray(s.lines) && s.lines.length > 0) {
          lines.push(...s.lines);
        } else if (s.text) {
          lines.push(s.text);
        }
      });
      return prefix + lines.join('\n');
    }).join('\n\n');
  }

  function formatLineWithRepetition(pureText, repVal) {
    if (!pureText || !pureText.trim()) return pureText || '';
    const clean = pureText.trim();
    if (repVal === 'repeat_2') return `(${clean})2`;
    if (repVal === 'repeat_3') return `(${clean})3`;
    if (repVal === 'repeat_4') return `(${clean})4`;
    if (repVal === 'repeat_martain') return `(${clean}) (مرتين)`;
    if (repVal === 'prefix_2') return `2 (${clean})`;
    return clean;
  }

  function buildCompleteSongObject() {
    const titleVal = els.songInputTitle ? els.songInputTitle.value.trim() : (customSongBuilderState.title || '');
    const scaleVal = els.songInputScale ? parseInt(els.songInputScale.value) : customSongBuilderState.scale_id;
    const mediaVal = els.songInputMedia ? els.songInputMedia.value.trim() : (customSongBuilderState.media_url || '');

    let stanzaCounter = 0;
    const formattedVerses = (customSongBuilderState.verses || []).map((v, vIdx) => {
      const isChorus = (v.type === 1 || v.isChorus === true);
      if (!isChorus) stanzaCounter++;

      const slides = (v.slides || []).map((sl, slIdx) => {
        const cleanLines = (sl.lines || (sl.text ? sl.text.split('\n') : [])).map(l => String(l).trim()).filter(l => l.length > 0);
        return {
          id: slIdx + 1,
          heading: sl.heading || null,
          lines: cleanLines,
          text: cleanLines.join('\n')
        };
      }).filter(sl => sl.lines.length > 0);

      return {
        id: vIdx + 1,
        type: isChorus ? 1 : 0,
        isChorus: isChorus,
        ...(!isChorus ? { stanzaNum: stanzaCounter } : {}),
        slides: slides.length > 0 ? slides : [{ id: 1, heading: null, lines: ['...'], text: '...' }]
      };
    }).filter(v => v.slides.length > 0);

    const notesText = generateNotesFromVerses(formattedVerses);

    return {
      id: customSongBuilderState.id || ('custom_' + Date.now()),
      item_id: customSongBuilderState.item_id || ('custom_' + Date.now()),
      title: titleVal,
      scale_id: (!isNaN(scaleVal) && scaleVal > 0) ? scaleVal : null,
      notes: notesText,
      media_url: mediaVal || '',
      is_custom: true,
      created_at: customSongBuilderState.created_at || new Date().toISOString(),
      verses: formattedVerses
    };
  }

  function parseRawLyricsToVerses(rawText, options = {}) {
    if (!rawText || !rawText.trim()) return [];

    const detectChorus = options.detectChorus !== false;
    const detectRepeats = options.detectRepeats !== false;
    const splitRule = options.splitRule || 'full_stanza';

    const cleanRaw = rawText.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
    const blocks = cleanRaw.split(/\n\s*\n+/).map(b => b.trim()).filter(b => b.length > 0);

    const parsedVerses = [];
    let currentStanzaNum = 0;

    blocks.forEach((block, blockIdx) => {
      let rawLines = block.split('\n').map(l => l.trim()).filter(l => l.length > 0);
      if (rawLines.length === 0) return;

      let isChorus = false;
      let foundStanzaNum = null;
      const firstLine = rawLines[0];

      if (detectChorus) {
        const chorusPrefixRegex = /^\s*(?:[\(\[\{]\s*(القرار|قرار|ق|القرار\s*[\d٠-٩]+|قرار\s*[\d٠-٩]+)\s*[\)\]\}]\s*[:\-\/]?|(?:القرار|قرار)\s*[:\-\/]?|ق\s*[:\-\/\.]|(?:القرار|قرار)\s*[\d٠-٩]+\s*[:\-\/]?)\s*/i;
        const isIsolatedChorus = /^\s*[\(\[\{]?\s*(القرار|قرار|ق|القرار\s*[\d٠-٩]+|قرار\s*[\d٠-٩]+)\s*[\)\]\}]?\s*$/i;

        if (chorusPrefixRegex.test(firstLine) || isIsolatedChorus.test(firstLine)) {
          isChorus = true;
          rawLines[0] = firstLine.replace(chorusPrefixRegex, '').replace(isIsolatedChorus, '').trim();
          if (!rawLines[0]) rawLines.shift();
        } else {
          const matchNum = firstLine.match(/^\s*\(?\s*([\d٠-٩]+)\s*\)?\s*[:\s\-\.]\s*(.*)/);
          if (matchNum) {
            foundStanzaNum = matchNum[1];
            if (matchNum[2]) {
              rawLines[0] = matchNum[2].trim();
            } else {
              rawLines.shift();
            }
          }
        }

        if (blockIdx === 0 && !isChorus && !foundStanzaNum && blocks.length > 1) {
          const secondBlockFirstLine = blocks[1].split('\n')[0].trim();
          if (/^\s*\(?\s*[1١]\s*\)?\s*[:\s\-\.]/i.test(secondBlockFirstLine)) {
            isChorus = true;
          }
        }
      }

      let processedLines = rawLines.map(line => {
        if (!detectRepeats) return line;
        const mRep = line.match(/^(.*?)\s*[\(\[\{]\s*(مرتين|مرتان|2|٢|×2|x2|3|٣|×3|x3|4|٤|×4|x4)\s*[\)\]\}]$/i);
        if (mRep && mRep[1]) {
          const countStr = mRep[2].replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[×x]/i, '');
          const count = (countStr === 'مرتين' || countStr === 'مرتان') ? 2 : parseInt(countStr) || 2;
          return `(${mRep[1].trim()})${count}`;
        }
        return line;
      }).filter(l => l.length > 0);

      if (processedLines.length === 0) return;

      let slides = [];
      if (splitRule === '2_lines') {
        for (let i = 0; i < processedLines.length; i += 2) {
          const chunk = processedLines.slice(i, i + 2);
          slides.push({
            id: slides.length + 1,
            heading: null,
            lines: chunk,
            text: chunk.join('\n')
          });
        }
      } else if (splitRule === '4_lines') {
        for (let i = 0; i < processedLines.length; i += 4) {
          const chunk = processedLines.slice(i, i + 4);
          slides.push({
            id: slides.length + 1,
            heading: null,
            lines: chunk,
            text: chunk.join('\n')
          });
        }
      } else if (splitRule === '1_line') {
        processedLines.forEach((l, idx) => {
          slides.push({
            id: idx + 1,
            heading: null,
            lines: [l],
            text: l
          });
        });
      } else {
        // full_stanza
        slides.push({
          id: 1,
          heading: null,
          lines: processedLines,
          text: processedLines.join('\n')
        });
      }

      if (isChorus) {
        parsedVerses.push({
          id: parsedVerses.length + 1,
          type: 1,
          isChorus: true,
          slides: slides
        });
      } else {
        if (foundStanzaNum) {
          currentStanzaNum = parseInt(foundStanzaNum.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))) || (currentStanzaNum + 1);
        } else {
          currentStanzaNum++;
        }
        parsedVerses.push({
          id: parsedVerses.length + 1,
          type: 0,
          isChorus: false,
          stanzaNum: currentStanzaNum,
          slides: slides
        });
      }
    });

    return parsedVerses;
  }

  function renderCustomSongBuilderUI() {
    if (!els.songBuilderSegmentsList) return;

    if (!customSongBuilderState.verses || customSongBuilderState.verses.length === 0) {
      els.songBuilderSegmentsList.innerHTML = `
        <div class="empty-state" style="padding:24px; text-align:center; color:#94a3b8;">
          <i class="fa-solid fa-layer-group" style="font-size:2.2rem; margin-bottom:8px; color:#cbd5e1;"></i>
          <p style="font-size:0.88rem; margin:0; font-weight:700; color:#64748b;">لا توجد فقرات مضافة بعد</p>
          <p style="font-size:0.78rem; margin:4px 0 0 0;">اضغط على "+ إضافة قرار" أو "+ إضافة عدد" بالأعلى للبدء.</p>
        </div>
      `;
      return;
    }

    let stanzaCounter = 0;
    let chorusCounter = 0;
    const totalChoruses = customSongBuilderState.verses.filter(v => v.type === 1 || v.isChorus).length;

    els.songBuilderSegmentsList.innerHTML = customSongBuilderState.verses.map((verse, vIdx) => {
      const isChorus = (verse.type === 1 || verse.isChorus === true);
      if (isChorus) {
        chorusCounter++;
      } else {
        stanzaCounter++;
      }
      const sNum = stanzaCounter;
      const chLabel = (totalChoruses > 1) ? `القرار ${chorusCounter}` : `القرار`;

      const slidesHtml = (verse.slides || []).map((slide, sIdx) => {
        const lines = (Array.isArray(slide.lines) && slide.lines.length > 0) ? slide.lines : (slide.text ? slide.text.split('\n') : ['']);
        
        const linesRowsHtml = lines.map((lineText, lIdx) => {
          let repVal = 'none';
          let pureText = String(lineText || '');

          if (/^\(.*?\)(2|٢)$/.test(pureText)) {
            repVal = 'repeat_2';
            pureText = pureText.replace(/^\((.*?)\)(2|٢)$/, '$1');
          } else if (/^\(.*?\)(3|٣)$/.test(pureText)) {
            repVal = 'repeat_3';
            pureText = pureText.replace(/^\((.*?)\)(3|٣)$/, '$1');
          } else if (/^\(.*?\)(4|٤)$/.test(pureText)) {
            repVal = 'repeat_4';
            pureText = pureText.replace(/^\((.*?)\)(4|٤)$/, '$1');
          } else if (/^\(.*?\)\s*\(مرتين\)$/.test(pureText) || /^(.*?)\s*\(مرتين\)$/.test(pureText)) {
            repVal = 'repeat_martain';
            pureText = pureText.replace(/^\(?(.*?)\)?\s*\(مرتين\)$/, '$1');
          } else if (/^2\s*\(.*?\)$/.test(pureText)) {
            repVal = 'prefix_2';
            pureText = pureText.replace(/^2\s*\((.*?)\)$/, '$1');
          }

          return `
            <div class="slide-line-row" data-verse-idx="${vIdx}" data-slide-idx="${sIdx}" data-line-idx="${lIdx}">
              <span class="slide-line-num">${lIdx + 1}</span>
              <input type="text" class="slide-line-input" value="${escapeHtml(pureText)}" placeholder="اكتب نص السطر..." autocomplete="off">
              <select class="slide-line-repeat-select" title="تكرار السطر">
                <option value="none" ${repVal === 'none' ? 'selected' : ''}>بدون تكرار</option>
                <option value="repeat_2" ${repVal === 'repeat_2' ? 'selected' : ''}>(نص)2 مرتين</option>
                <option value="repeat_3" ${repVal === 'repeat_3' ? 'selected' : ''}>(نص)3 ٣ مرات</option>
                <option value="repeat_4" ${repVal === 'repeat_4' ? 'selected' : ''}>(نص)4 ٤ مرات</option>
                <option value="repeat_martain" ${repVal === 'repeat_martain' ? 'selected' : ''}>(مرتين)</option>
                <option value="prefix_2" ${repVal === 'prefix_2' ? 'selected' : ''}>2 (نص)</option>
              </select>
              <button type="button" class="btn-remove-line" title="حذف هذا السطر"><i class="fa-solid fa-xmark"></i></button>
            </div>
          `;
        }).join('');

        return `
          <div class="song-slide-box" data-verse-idx="${vIdx}" data-slide-idx="${sIdx}">
            <div class="slide-box-header">
              <span><i class="fa-solid fa-file-lines" style="color:#2563eb;"></i> الشريحة ${sIdx + 1}</span>
              ${(verse.slides.length > 1) ? `<button type="button" class="btn-remove-slide seg-btn seg-btn-danger" style="width:22px; height:22px; font-size:0.68rem;" title="حذف هذه الشريحة"><i class="fa-solid fa-trash-can"></i></button>` : ''}
            </div>
            <div class="slide-lines-list">
              ${linesRowsHtml}
            </div>
            <button type="button" class="btn-add-line-to-slide"><i class="fa-solid fa-plus"></i> إضافة سطر للشريحة</button>
          </div>
        `;
      }).join('');

      return `
        <div class="song-segment-card ${isChorus ? 'is-chorus' : 'is-verse'}" data-verse-idx="${vIdx}">
          <div class="segment-header">
            <div style="display:flex; align-items:center; gap:8px;">
              <select class="control-select seg-type-select" style="font-size:0.78rem; font-weight:800; padding:4px 8px; border-radius:8px;">
                <option value="1" ${isChorus ? 'selected' : ''}>🌟 ${chLabel} (Chorus)</option>
                <option value="0" ${!isChorus ? 'selected' : ''}>📖 عدد ${sNum} (Verse)</option>
              </select>
              <span class="segment-type-pill ${isChorus ? 'chorus' : 'verse'}">
                ${isChorus ? `<i class="fa-solid fa-star"></i> ${chLabel}` : `<i class="fa-solid fa-bookmark"></i> عدد ${sNum}`}
              </span>
            </div>
            <div class="segment-header-actions">
              <button type="button" class="seg-btn btn-move-seg-up" title="تحريك لأعلى" ${vIdx === 0 ? 'disabled style="opacity:0.4; cursor:not-allowed;"' : ''}><i class="fa-solid fa-arrow-up"></i></button>
              <button type="button" class="seg-btn btn-move-seg-down" title="تحريك لأسفل" ${vIdx === customSongBuilderState.verses.length - 1 ? 'disabled style="opacity:0.4; cursor:not-allowed;"' : ''}><i class="fa-solid fa-arrow-down"></i></button>
              <button type="button" class="seg-btn btn-dup-seg" title="تكرار / نسخ هذه الفقرة"><i class="fa-solid fa-clone"></i></button>
              <button type="button" class="seg-btn seg-btn-danger btn-del-seg" title="حذف هذه الفقرة بالكامل"><i class="fa-solid fa-trash-can"></i></button>
            </div>
          </div>

          <div class="segment-slides-container">
            ${slidesHtml}
            <button type="button" class="btn-add-slide-to-segment"><i class="fa-solid fa-plus"></i> إضافة شريحة أخرى لهذا ${isChorus ? 'القرار' : 'العدد'}</button>
          </div>
        </div>
      `;
    }).join('');

    bindCustomSongBuilderEvents();
  }

  function bindCustomSongBuilderEvents() {
    if (!els.songBuilderSegmentsList) return;

    // Segment Type Changes
    els.songBuilderSegmentsList.querySelectorAll('.seg-type-select').forEach(sel => {
      sel.addEventListener('change', (e) => {
        const segCard = sel.closest('.song-segment-card');
        if (!segCard) return;
        const vIdx = parseInt(segCard.dataset.verseIdx);
        if (customSongBuilderState.verses[vIdx]) {
          const isCh = (sel.value === '1');
          customSongBuilderState.verses[vIdx].type = isCh ? 1 : 0;
          customSongBuilderState.verses[vIdx].isChorus = isCh;
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Move Segment Up
    els.songBuilderSegmentsList.querySelectorAll('.btn-move-seg-up').forEach(btn => {
      btn.addEventListener('click', () => {
        const segCard = btn.closest('.song-segment-card');
        if (!segCard) return;
        const vIdx = parseInt(segCard.dataset.verseIdx);
        if (vIdx > 0) {
          const item = customSongBuilderState.verses.splice(vIdx, 1)[0];
          customSongBuilderState.verses.splice(vIdx - 1, 0, item);
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Move Segment Down
    els.songBuilderSegmentsList.querySelectorAll('.btn-move-seg-down').forEach(btn => {
      btn.addEventListener('click', () => {
        const segCard = btn.closest('.song-segment-card');
        if (!segCard) return;
        const vIdx = parseInt(segCard.dataset.verseIdx);
        if (vIdx < customSongBuilderState.verses.length - 1) {
          const item = customSongBuilderState.verses.splice(vIdx, 1)[0];
          customSongBuilderState.verses.splice(vIdx + 1, 0, item);
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Duplicate Segment
    els.songBuilderSegmentsList.querySelectorAll('.btn-dup-seg').forEach(btn => {
      btn.addEventListener('click', () => {
        const segCard = btn.closest('.song-segment-card');
        if (!segCard) return;
        const vIdx = parseInt(segCard.dataset.verseIdx);
        if (customSongBuilderState.verses[vIdx]) {
          const cloned = JSON.parse(JSON.stringify(customSongBuilderState.verses[vIdx]));
          customSongBuilderState.verses.splice(vIdx + 1, 0, cloned);
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Delete Segment
    els.songBuilderSegmentsList.querySelectorAll('.btn-del-seg').forEach(btn => {
      btn.addEventListener('click', () => {
        const segCard = btn.closest('.song-segment-card');
        if (!segCard) return;
        const vIdx = parseInt(segCard.dataset.verseIdx);
        if (customSongBuilderState.verses[vIdx]) {
          customSongBuilderState.verses.splice(vIdx, 1);
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Add Slide to Segment
    els.songBuilderSegmentsList.querySelectorAll('.btn-add-slide-to-segment').forEach(btn => {
      btn.addEventListener('click', () => {
        const segCard = btn.closest('.song-segment-card');
        if (!segCard) return;
        const vIdx = parseInt(segCard.dataset.verseIdx);
        if (customSongBuilderState.verses[vIdx]) {
          if (!customSongBuilderState.verses[vIdx].slides) customSongBuilderState.verses[vIdx].slides = [];
          customSongBuilderState.verses[vIdx].slides.push({
            id: customSongBuilderState.verses[vIdx].slides.length + 1,
            heading: null,
            lines: [''],
            text: ''
          });
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Delete Slide
    els.songBuilderSegmentsList.querySelectorAll('.btn-remove-slide').forEach(btn => {
      btn.addEventListener('click', () => {
        const slideBox = btn.closest('.song-slide-box');
        if (!slideBox) return;
        const vIdx = parseInt(slideBox.dataset.verseIdx);
        const sIdx = parseInt(slideBox.dataset.slideIdx);
        if (customSongBuilderState.verses[vIdx] && customSongBuilderState.verses[vIdx].slides) {
          customSongBuilderState.verses[vIdx].slides.splice(sIdx, 1);
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Add Line to Slide
    els.songBuilderSegmentsList.querySelectorAll('.btn-add-line-to-slide').forEach(btn => {
      btn.addEventListener('click', () => {
        const slideBox = btn.closest('.song-slide-box');
        if (!slideBox) return;
        const vIdx = parseInt(slideBox.dataset.verseIdx);
        const sIdx = parseInt(slideBox.dataset.slideIdx);
        if (customSongBuilderState.verses[vIdx] && customSongBuilderState.verses[vIdx].slides[sIdx]) {
          const slide = customSongBuilderState.verses[vIdx].slides[sIdx];
          if (!slide.lines) slide.lines = [];
          slide.lines.push('');
          renderCustomSongBuilderUI();
          updateCustomSongLivePreview();
        }
      });
    });

    // Delete Line
    els.songBuilderSegmentsList.querySelectorAll('.btn-remove-line').forEach(btn => {
      btn.addEventListener('click', () => {
        const lineRow = btn.closest('.slide-line-row');
        if (!lineRow) return;
        const vIdx = parseInt(lineRow.dataset.verseIdx);
        const sIdx = parseInt(lineRow.dataset.slideIdx);
        const lIdx = parseInt(lineRow.dataset.lineIdx);
        if (customSongBuilderState.verses[vIdx] && customSongBuilderState.verses[vIdx].slides[sIdx]) {
          const slide = customSongBuilderState.verses[vIdx].slides[sIdx];
          if (slide.lines) {
            slide.lines.splice(lIdx, 1);
            if (slide.lines.length === 0) slide.lines = [''];
            renderCustomSongBuilderUI();
            updateCustomSongLivePreview();
          }
        }
      });
    });

    // Line Input & Repetition Changes
    const updateLineFromRow = (lineRow) => {
      if (!lineRow) return;
      const vIdx = parseInt(lineRow.dataset.verseIdx);
      const sIdx = parseInt(lineRow.dataset.slideIdx);
      const lIdx = parseInt(lineRow.dataset.lineIdx);
      const inputEl = lineRow.querySelector('.slide-line-input');
      const repSel = lineRow.querySelector('.slide-line-repeat-select');
      if (!inputEl || !repSel) return;

      const rawTxt = inputEl.value;
      const repVal = repSel.value;
      const formatted = formatLineWithRepetition(rawTxt, repVal);

      if (customSongBuilderState.verses[vIdx] && customSongBuilderState.verses[vIdx].slides[sIdx]) {
        const slide = customSongBuilderState.verses[vIdx].slides[sIdx];
        if (!slide.lines) slide.lines = [];
        slide.lines[lIdx] = formatted;
        slide.text = slide.lines.join('\n');
        updateCustomSongLivePreview();
      }
    };

    els.songBuilderSegmentsList.querySelectorAll('.slide-line-input').forEach(input => {
      input.addEventListener('input', () => {
        const lineRow = input.closest('.slide-line-row');
        updateLineFromRow(lineRow);
      });
    });

    els.songBuilderSegmentsList.querySelectorAll('.slide-line-repeat-select').forEach(sel => {
      sel.addEventListener('change', () => {
        const lineRow = sel.closest('.slide-line-row');
        updateLineFromRow(lineRow);
      });
    });
  }

  function updateCustomSongLivePreview() {
    if (!els.songBuilderLiveSlidesPreview) return;

    let totalSlides = 0;
    let stanzaCounter = 0;
    const cardsHtml = (customSongBuilderState.verses || []).flatMap((v, vIdx) => {
      const isChorus = (v.type === 1 || v.isChorus === true);
      if (!isChorus) stanzaCounter++;
      const sNum = stanzaCounter;

      return (v.slides || []).map((slide, sIdx) => {
        totalSlides++;
        const rawLines = slide.lines || (slide.text ? slide.text.split('\n') : []);
        const cleanLines = rawLines.map(l => String(l).trim()).filter(l => l.length > 0);

        const linesHtml = (cleanLines.length > 0 ? cleanLines : ['(شريحة فارغة)']).map(l => {
          let text = escapeHtml(l);
          if (text.startsWith('(')) {
            text = '<span style="color:#60a5fa;">(</span>' + text.substring(1);
          }
          text = text.replace(/\)([\d٠-٩]*)$/, '<span style="color:#60a5fa;">)$1</span>');
          return `<div class="line-row-txt">${text}</div>`;
        }).join('');

        return `
          <div class="preview-slide-card">
            <div class="preview-slide-header">
              <span class="preview-slide-badge ${isChorus ? 'chorus' : 'verse'}">
                ${isChorus ? '<i class="fa-solid fa-star"></i> القرار' : `<i class="fa-solid fa-bookmark"></i> عدد ${sNum}`}
              </span>
              <span>شريحة ${totalSlides}</span>
            </div>
            <div class="preview-slide-lines">
              ${linesHtml}
            </div>
          </div>
        `;
      });
    }).join('');

    if (els.builderTotalSlidesCountBadge) {
      els.builderTotalSlidesCountBadge.textContent = `${totalSlides} ${totalSlides === 1 ? 'شريحة' : (totalSlides === 2 ? 'شريحتان' : (totalSlides <= 10 ? 'شرائح' : 'شريحة'))}`;
    }

    els.songBuilderLiveSlidesPreview.innerHTML = cardsHtml || `
      <div style="text-align:center; padding:20px; color:#94a3b8; font-size:0.82rem;">
        لا توجد شرائح للمعاينة
      </div>
    `;
  }

  function saveCustomSong(presentImmediately = false) {
    const songObj = buildCompleteSongObject();
    
    if (!songObj.title) {
      alert('يرجى إدخال عنوان الترنيمة لحفظها.');
      if (els.songInputTitle) els.songInputTitle.focus();
      return;
    }

    if (!songObj.verses || songObj.verses.length === 0) {
      alert('يرجى إضافة فقرات وكلمات للترنيمة.');
      return;
    }

    const currentSongs = getStoredCustomSongs();
    const existingIdx = currentSongs.findIndex(s => String(s.id) === String(songObj.id) || String(s.item_id) === String(songObj.id));

    if (existingIdx !== -1) {
      currentSongs[existingIdx] = songObj;
    } else {
      currentSongs.unshift(songObj);
    }

    setStoredCustomSongs(currentSongs);
    syncCustomSongsIntoCatalog();
    closeCustomSongEditor();

    // Update active presentation if editing current song
    if (state.activeSong && String(state.activeSong.id) === String(songObj.id)) {
      loadSongIntoPresentation(songObj);
      syncLiveState();
    }

    if (presentImmediately) {
      openAndPresentItem(songObj, false);
    }

    renderRecentSession();
  }

  function deleteCustomSong(songId) {
    if (!songId) return;
    if (!confirm('هل أنت متأكد من حذف هذه الترنيمة نهائياً من جهازك؟')) return;

    let currentSongs = getStoredCustomSongs();
    currentSongs = currentSongs.filter(s => String(s.id) !== String(songId) && String(s.item_id) !== String(songId));
    setStoredCustomSongs(currentSongs);
    syncCustomSongsIntoCatalog();

    // Remove from recents
    state.sessionRecents = state.sessionRecents.filter(r => String(r.id) !== String(songId));
    savePlaylists();
    renderRecentSession();

    // Clear presentation if active
    if (state.activeSong && String(state.activeSong.id) === String(songId)) {
      state.activeSong = null;
      state.presentationLines = [];
      state.currentLineIndex = -1;
      renderPresentationLinesList();
      syncLiveState();
    }
  }

  function exportCustomSongJson(songObj) {
    if (!songObj) songObj = buildCompleteSongObject();
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(songObj, null, 2));
    const dlAnchor = document.createElement('a');
    const safeTitle = (songObj.title || 'custom_song').replace(/[/\\?%*:|"<>]/g, '_');
    dlAnchor.setAttribute("href", dataStr);
    dlAnchor.setAttribute("download", `${safeTitle}.json`);
    document.body.appendChild(dlAnchor);
    dlAnchor.click();
    dlAnchor.remove();
  }

  function importCustomSongJson(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const parsed = JSON.parse(e.target.result);
        if (!parsed || typeof parsed !== 'object') throw new Error('Invalid JSON format');
        
        if (parsed.title) {
          openCustomSongEditor(parsed);
        } else if (Array.isArray(parsed) && parsed.length > 0 && parsed[0].title) {
          // Bulk import of songs
          const existing = getStoredCustomSongs();
          const merged = [...parsed.map(s => ({ ...s, is_custom: true })), ...existing];
          setStoredCustomSongs(merged);
          syncCustomSongsIntoCatalog();
          renderRecentSession();
          alert(`تم استيراد ${parsed.length} ترنيمة بنجاح!`);
        } else {
          alert('هيكل ملف JSON غير متطابق مع تنسيق الترانيم.');
        }
      } catch (err) {
        alert('حدث خطأ أثناء قراءة ملف JSON: ' + err.message);
      }
    };
    reader.readAsText(file);
  }

  function initCustomSongEditor() {
    // Open Modal Button in Header
    if (els.btnOpenAddSongModal) {
      els.btnOpenAddSongModal.addEventListener('click', (e) => {
        e.preventDefault();
        openCustomSongEditor();
      });
    }

    // Close & Cancel Buttons
    if (els.btnCloseSongEditorModal) {
      els.btnCloseSongEditorModal.addEventListener('click', closeCustomSongEditor);
    }
    if (els.btnCancelCustomSongModal) {
      els.btnCancelCustomSongModal.addEventListener('click', closeCustomSongEditor);
    }

    // Modal Tabs Navigation
    if (els.modalCustomSongEditor) {
      els.modalCustomSongEditor.querySelectorAll('.song-editor-tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          switchCustomSongEditorTab(btn.dataset.tab);
        });
      });
    }

    // Add Chorus / Verse Buttons in Builder
    if (els.btnAddChorusSegment) {
      els.btnAddChorusSegment.addEventListener('click', () => {
        customSongBuilderState.verses.push({
          id: customSongBuilderState.verses.length + 1,
          type: 1,
          isChorus: true,
          slides: [{ id: 1, heading: null, lines: [''], text: '' }]
        });
        renderCustomSongBuilderUI();
        updateCustomSongLivePreview();
      });
    }

    if (els.btnAddVerseSegment) {
      els.btnAddVerseSegment.addEventListener('click', () => {
        customSongBuilderState.verses.push({
          id: customSongBuilderState.verses.length + 1,
          type: 0,
          isChorus: false,
          slides: [{ id: 1, heading: null, lines: [''], text: '' }]
        });
        renderCustomSongBuilderUI();
        updateCustomSongLivePreview();
      });
    }

    // Smart Paste Parser Button
    if (els.btnExecuteSmartParse) {
      els.btnExecuteSmartParse.addEventListener('click', () => {
        const rawTxt = els.smartPasteRawTextarea ? els.smartPasteRawTextarea.value : '';
        if (!rawTxt.trim()) {
          alert('يرجى لصق نص الترنيمة أولاً.');
          return;
        }

        const detectChorus = els.chkSmartDetectChorus ? els.chkSmartDetectChorus.checked : true;
        const detectRepeats = els.chkSmartDetectRepeats ? els.chkSmartDetectRepeats.checked : true;
        const splitRule = els.selectSmartSplitRule ? els.selectSmartSplitRule.value : 'full_stanza';

        const parsedVerses = parseRawLyricsToVerses(rawTxt, { detectChorus, detectRepeats, splitRule });
        if (parsedVerses.length === 0) {
          alert('تعذر استخراج أبيات من النص المدخل.');
          return;
        }

        customSongBuilderState.verses = parsedVerses;
        switchCustomSongEditorTab('tab-song-builder');
      });
    }

    // Apply Changes from Raw JSON
    if (els.btnApplyRawJsonChanges) {
      els.btnApplyRawJsonChanges.addEventListener('click', () => {
        try {
          const jsonVal = els.songRawJsonTextarea ? els.songRawJsonTextarea.value : '';
          const parsed = JSON.parse(jsonVal);
          if (!parsed || typeof parsed !== 'object') throw new Error('Invalid JSON');

          if (parsed.title) {
            customSongBuilderState.title = parsed.title;
            if (els.songInputTitle) els.songInputTitle.value = parsed.title;
          }
          if (parsed.scale_id !== undefined) {
            customSongBuilderState.scale_id = parsed.scale_id;
            if (els.songInputScale) els.songInputScale.value = parsed.scale_id || '';
          }
          if (parsed.media_url !== undefined) {
            customSongBuilderState.media_url = parsed.media_url;
            if (els.songInputMedia) els.songInputMedia.value = parsed.media_url || '';
          }
          if (Array.isArray(parsed.verses)) {
            customSongBuilderState.verses = parsed.verses;
          }

          switchCustomSongEditorTab('tab-song-builder');
          alert('تم تطبيق التعديلات من JSON بنجاح!');
        } catch (err) {
          alert('خطأ في تنسيق JSON: ' + err.message);
        }
      });
    }

    // Copy JSON Code Button
    if (els.btnCopySongJsonCode) {
      els.btnCopySongJsonCode.addEventListener('click', () => {
        const jsonVal = els.songRawJsonTextarea ? els.songRawJsonTextarea.value : '';
        navigator.clipboard.writeText(jsonVal).then(() => {
          alert('تم نسخ كود JSON إلى الحافظة.');
        }).catch(() => {});
      });
    }

    // Save Buttons
    if (els.btnSaveCustomSongOnly) {
      els.btnSaveCustomSongOnly.addEventListener('click', () => {
        saveCustomSong(false);
      });
    }

    if (els.btnSaveAndPresentSong) {
      els.btnSaveAndPresentSong.addEventListener('click', () => {
        saveCustomSong(true);
      });
    }

    // Export Single Song JSON Button
    if (els.btnExportCurrentSongJson) {
      els.btnExportCurrentSongJson.addEventListener('click', () => {
        exportCustomSongJson();
      });
    }

    // Submit for Review & Community Acceptance
    if (els.btnSubmitSongForReview) {
      els.btnSubmitSongForReview.addEventListener('click', openSubmitSongDialog);
    }
    if (els.btnCloseSubmitSongModal) {
      els.btnCloseSubmitSongModal.addEventListener('click', closeSubmitSongDialog);
    }
    if (els.btnCancelSubmitSong) {
      els.btnCancelSubmitSong.addEventListener('click', closeSubmitSongDialog);
    }
    if (els.btnConfirmSendSubmission) {
      els.btnConfirmSendSubmission.addEventListener('click', handleSendSongSubmission);
    }
    if (els.btnApproveReviewedSongDirect) {
      els.btnApproveReviewedSongDirect.addEventListener('click', handleApproveReviewedSongDirect);
    }

    // Check URL parameters on load for ?review_sub=...&token=...
    try {
      const urlParams = new URLSearchParams(window.location.search);
      const reviewSubId = urlParams.get('review_sub');
      const reviewToken = urlParams.get('token');
      if (reviewSubId && reviewToken) {
        (async () => {
          try {
            const r = await fetch(`/taranim/api.php?action=get_submission&id=${encodeURIComponent(reviewSubId)}&token=${encodeURIComponent(reviewToken)}`);
            const d = await r.json();
            if (d.status === 'success' && d.song) {
              const subInfo = d.submission || {};
              openCustomSongEditor(d.song, {
                submissionId: reviewSubId,
                reviewToken: reviewToken,
                submitterName: subInfo.submitter_name,
                churchName: subInfo.church_name
              });
              showToast(`وضع مراجعة ترنيمة مرسلة من: ${subInfo.submitter_name || 'خادم'} 🔍`, 'info');
            }
          } catch(e) {}
        })();
      }
    } catch(e) {}

    // Import Song JSON File
    if (els.btnImportSongJsonFile && els.inputImportSongJsonFile) {
      els.btnImportSongJsonFile.addEventListener('click', () => {
        els.inputImportSongJsonFile.click();
      });
      els.inputImportSongJsonFile.addEventListener('change', (e) => {
        if (e.target.files && e.target.files[0]) {
          importCustomSongJson(e.target.files[0]);
          e.target.value = '';
        }
      });
    }

    // Edit & Delete Active Custom Song Buttons in Presentation Toolbar
    if (els.btnEditActiveCustomSong) {
      els.btnEditActiveCustomSong.addEventListener('click', () => {
        if (state.activeSong) {
          openCustomSongEditor(state.activeSong);
        }
      });
    }

    if (els.btnDeleteActiveCustomSong) {
      els.btnDeleteActiveCustomSong.addEventListener('click', () => {
        if (state.activeSong && state.activeSong.id) {
          deleteCustomSong(state.activeSong.id);
        }
      });
    }
  }

  function openSubmitSongDialog() {
    const songObj = buildCompleteSongObject();
    if (!songObj.title) {
      showToast('يرجى كتابة عنوان الترنيمة أولاً.', 'warning');
      if (els.songInputTitle) els.songInputTitle.focus();
      return;
    }
    if (!songObj.verses || songObj.verses.length === 0) {
      showToast('يرجى إضافة فقرات وكلمات للترنيمة قبل إرسالها.', 'warning');
      return;
    }

    try {
      const savedName = localStorage.getItem('sunday_school_submitter_name') || '';
      if (savedName && els.inputSubmitterName) els.inputSubmitterName.value = savedName;
    } catch(e) {}

    if (els.modalSubmitSongDialog) {
      els.modalSubmitSongDialog.classList.remove('hidden');
      if (els.inputSubmitterName && !els.inputSubmitterName.value) {
        els.inputSubmitterName.focus();
      }
    }
  }

  function closeSubmitSongDialog() {
    if (els.modalSubmitSongDialog) {
      els.modalSubmitSongDialog.classList.add('hidden');
    }
  }

  async function handleSendSongSubmission() {
    const name = els.inputSubmitterName ? els.inputSubmitterName.value.trim() : '';
    if (!name) {
      showToast('يرجى كتابة الاسم.', 'warning');
      if (els.inputSubmitterName) els.inputSubmitterName.focus();
      return;
    }

    const notes = els.inputSubmitterNotes ? els.inputSubmitterNotes.value.trim() : '';

    try {
      localStorage.setItem('sunday_school_submitter_name', name);
    } catch(e) {}

    const songObj = buildCompleteSongObject();
    const payload = {
      ...songObj,
      submitter_name: name,
      notes: notes
    };

    const btn = els.btnConfirmSendSubmission;
    const origHtml = btn ? btn.innerHTML : '';
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الإرسال...';
    }

    try {
      const resp = await fetch('/taranim/api.php?action=submit_custom_song', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const result = await resp.json();
      if (result.status === 'success') {
        // Direct browser dispatch to Google Apps Script as dual guarantee
        try {
          const directAppsScriptUrl = 'https://script.google.com/macros/s/AKfycbwuidcfDZtPxuFTGV5-GxNY395DhD6MeP4tl10LVLMr0ptNvNMI0sOS9OBeZzD9RUg/exec';
          const versesSummary = (payload.verses || []).map((v, i) => {
            const isChorus = v.type == 1 || v.isChorus;
            const vTitle = isChorus ? '🌟 القرار' : `📖 العدد ${i + 1}`;
            const vText = (v.slides || []).map(s => (s.lines || []).join('\n')).join('\n');
            return `<div style="margin-bottom:10px; background:#f8fafc; padding:10px; border-right:4px solid #3b82f6; border-radius:6px;"><strong>${vTitle}</strong><pre style="font-family:inherit; white-space:pre-wrap; margin:6px 0 0 0; color:#1e293b;">${vText}</pre></div>`;
          }).join('');
          
          const emailHtml = `
            <div dir="rtl" style="font-family:Tahoma, Arial, sans-serif; padding:16px; background:#f1f5f9;">
              <div style="max-width:600px; margin:0 auto; background:#ffffff; border-radius:10px; padding:20px; border:1px solid #e2e8f0;">
                <h3 style="color:#2563eb; margin-top:0;">🎵 طلب اعتماد ترنيمة جديدة</h3>
                <p><strong>العنوان:</strong> ${payload.title || ''}</p>
                <p><strong>المُرسل:</strong> ${name || 'خادم'}</p>
                ${notes ? `<p><strong>ملاحظات:</strong> ${notes}</p>` : ''}
                <hr style="border:none; border-top:1px solid #e2e8f0; margin:15px 0;">
                <h4>الكلمات والفقرات:</h4>
                ${versesSummary}
              </div>
            </div>
          `;
          const formBody = new URLSearchParams();
          formBody.append('action', 'sendEmail');
          formBody.append('to', 'peterfayez107@gmail.com');
          formBody.append('subject', `🎵 طلب اعتماد ترنيمة جديدة: ${payload.title || ''} — ${name}`);
          formBody.append('htmlBody', emailHtml);

          fetch(directAppsScriptUrl, {
            method: 'POST',
            mode: 'no-cors',
            body: formBody
          }).catch(() => {});
        } catch(e) {}

        closeSubmitSongDialog();
        showToast('🚀 تم إرسال الترنيمة للمراجعة والاعتماد بنجاح!', 'success');
      } else {
        showToast(result.message || 'حدث خطأ أثناء الإرسال', 'error');
      }
    } catch (err) {
      showToast('فشل إرسال الطلب، تأكد من اتصال الإنترنت.', 'error');
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = origHtml;
      }
    }
  }

  async function handleApproveReviewedSongDirect() {
    if (!customSongBuilderState.isReviewMode || !customSongBuilderState.submissionId || !customSongBuilderState.reviewToken) return;
    const songObj = buildCompleteSongObject();
    const btn = els.btnApproveReviewedSongDirect;
    const origHtml = btn ? btn.innerHTML : '';
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ...';
    }

    try {
      const resp = await fetch('/taranim/api.php?action=save_reviewed_custom_song', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          submission_id: customSongBuilderState.submissionId,
          token: customSongBuilderState.reviewToken,
          song: songObj
        })
      });
      const result = await resp.json();
      if (result.status === 'success') {
        showToast('✅ تم اعتماد ونشر الترنيمة بنجاح في قاعدة البيانات الحية للموقع!', 'success');
        closeCustomSongEditor();
        if (typeof initCatalog === 'function') initCatalog();
      } else {
        showToast(result.message || 'حدث خطأ أثناء الحفظ', 'error');
      }
    } catch (err) {
      showToast('حدث خطأ في الاتصال بالخادم', 'error');
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = origHtml;
      }
    }
  }

  function performIntelligentSearch(query) {
    if (!query || !query.trim()) {
      if (searchDebounceTimeout) clearTimeout(searchDebounceTimeout);
      if (searchAbortController) searchAbortController.abort();
      els.searchDropdown.classList.add('hidden');
      return;
    }

    const trimmedQuery = query.trim();
    const bibleInfo = parseBibleSearchShortcut(trimmedQuery);
    const searchTarget = bibleInfo ? bibleInfo.searchQuery : trimmedQuery;

    // 1. INSTANT 0ms LOCAL SEARCH VIA PRE-INDEXED CATALOG & BIBLE DATA (< 2ms total runtime)
    const isFrancoInput = Boolean(state.francoAutoTranslate) && /[a-z]/i.test(searchTarget) && !/[\u0600-\u06FF]/.test(searchTarget);
    const qFrancoVariants = isFrancoInput 
      ? (typeof francoToArabicVariants === 'function' ? francoToArabicVariants(searchTarget) : [francoToArabic(searchTarget)].filter(Boolean))
      : [];
    
    const effectiveArabicTarget = isFrancoInput && qFrancoVariants.length > 0 ? qFrancoVariants[0] : searchTarget;
    const qNorm = normalizeArabic(effectiveArabicTarget);
    if (!qNorm) {
      if (!state.francoAutoTranslate && /[a-z]/i.test(trimmedQuery)) {
        renderSearchDropdown([], trimmedQuery, 15, false);
      }
      return;
    }

    const spellingVariants = (typeof generateArabicSpellingVariants === 'function')
      ? generateArabicSpellingVariants(effectiveArabicTarget).map(normalizeArabic)
      : [];

    const searchTargets = Array.from(new Set([qNorm, ...qFrancoVariants.map(normalizeArabic), ...spellingVariants].filter(Boolean)));
    const qWords = qNorm.split(/\s+/).filter(w => w.length >= 2 || (qNorm.length < 3 && w.length >= 1));
    const qWordCount = qWords.length;

    const candidateMap = new Map();
    const allSongs = state.allSongs || [];
    const totalSongs = allSongs.length;

    // Fast pass 1: Scan all songs
    for (let i = 0; i < totalSongs; i++) {
      const song = allSongs[i];
      const tNorm = song._tNorm || '';
      const fullNorm = song._fullTextNorm || '';

      let maxScore = 0;

      for (let k = 0; k < searchTargets.length; k++) {
        const target = searchTargets[k];
        let score = 0;

        // 1. Exact / StartsWith / Substring Title
        if (tNorm === target) {
          score = 100000;
        } else if (tNorm.startsWith(target)) {
          score = 85000;
        } else if (tNorm.includes(target)) {
          score = 70000;
        } 
        // 2. Multi-word phrase or words
        else if (qWordCount >= 2) {
          if (fullNorm.includes(target)) {
            // Exact consecutive adjacent phrase in lyrics!
            score = 55000 + (qWordCount * 2500) + Math.min(target.length * 20, 2000);
          } else {
            let allFound = true;
            for (let j = 0; j < qWordCount; j++) {
              if (!fullNorm.includes(qWords[j])) {
                allFound = false;
                break;
              }
            }
            if (allFound) {
              score = 28000 + (qWordCount * 1000);
            }
          }
        } 
        // 3. Single-word queries
        else if (qWordCount === 1) {
          const w0 = qWords[0] || target;
          if (tNorm.includes(w0)) {
            score = 35000;
          } else if (fullNorm.includes(w0)) {
            score = 8000;
          }
        }

        if (score > maxScore) maxScore = score;
      }

      if (maxScore > 0) {
        candidateMap.set('song_' + (song.id || song.item_id), { ...song, _score: maxScore });
      }
    }

    // Fast pass 2: Bible chapters
    const bibleChapters = state.allBibleChapters || (state.bibleChaptersData ? Object.values(state.bibleChaptersData) : []);
    if (bibleChapters.length > 0) {
      const bLen = bibleChapters.length;
      for (let i = 0; i < bLen; i++) {
        const chapter = bibleChapters[i];
        const cBookId = parseInt(chapter.book_id || (chapter.book !== undefined ? chapter.book : 0));
        const cChNum = parseInt(chapter.chapter_number || (chapter.chapter !== undefined ? chapter.chapter : 0));
        const tNorm = chapter._tNorm || normalizeArabic(chapter.title || '');
        const fullNorm = chapter._fullTextNorm || '';

        let score = 0;
        if (bibleInfo && bibleInfo.bookId) {
          if (cBookId === bibleInfo.bookId) {
            if (bibleInfo.chapter && cChNum === bibleInfo.chapter) {
              score = 2000000;
            } else if (!bibleInfo.chapter) {
              score = 1000000 - cChNum;
            } else {
              score = 800000 - Math.abs(cChNum - bibleInfo.chapter);
            }
          }
        } else if (tNorm.includes(qNorm)) {
          score = 70000;
        } else if (qWordCount >= 2 && fullNorm.includes(qNorm)) {
          score = 55000 + (qWordCount * 2500);
        } else if (qWordCount >= 3) {
          let allFound = true;
          for (let j = 0; j < qWordCount; j++) {
            if (!fullNorm.includes(qWords[j])) {
              allFound = false;
              break;
            }
          }
          if (allFound) score = 25000;
        }

        if (score > 0) {
          candidateMap.set('bible_' + (chapter.id || `${cBookId}_${cChNum}`), {
            ...chapter,
            is_bible: true,
            book_id: cBookId,
            chapter_number: cChNum,
            _score: score
          });
        }
      }
    }

    const localMatches = Array.from(candidateMap.values()).sort((a, b) => b._score - a._score);
    let songsList = localMatches;

    // GUARANTEE BIBLE CHAPTER RESULT IF SHORTCUT/BIBLE QUERY WAS TYPED
    if (bibleInfo && bibleInfo.bookId) {
      const bookId = bibleInfo.bookId;
      const chNum = bibleInfo.chapter || 1;
      const bookTitle = bibleInfo.bookTitle || bibleInfo.bookName;
      const fallbackTitle = `سفر ${bookTitle} - الأصحاح ${chNum}`;

      const existingInList = songsList.find(s => {
        const isItemBible = Boolean(s.is_bible);
        const sBookId = parseInt(s.book_id || (s.book !== undefined ? s.book : 0));
        const sChNum = parseInt(s.chapter_number || (s.chapter !== undefined ? s.chapter : 0));
        return isItemBible && sBookId === bookId && sChNum === chNum;
      });

      if (!existingInList) {
        songsList = [{
          id: `bible_${bookId}_${chNum}`,
          item_id: `bible_${bookId}_${chNum}`,
          title: fallbackTitle,
          is_bible: true,
          book_id: bookId,
          chapter_number: chNum,
          _score: 2000000,
          notes: ""
        }, ...songsList];
      }
    }

    // RENDER LOCAL RESULTS INSTANTLY (0ms DELAY!)
    renderProcessedResults(songsList, trimmedQuery, bibleInfo, false);

    // 2. NON-BLOCKING ASYNC SERVER FETCH (30MS FAST DEBOUNCE & IMMEDIATE ABORT)
    if (searchDebounceTimeout) clearTimeout(searchDebounceTimeout);
    if (searchAbortController) searchAbortController.abort();

    searchDebounceTimeout = setTimeout(async () => {
      searchAbortController = new AbortController();
      const signal = searchAbortController.signal;

      try {
        let apiResults = [];
        const apiUrl = getApiUrl();
        let res = await fetch(`${apiUrl}?q=${encodeURIComponent(trimmedQuery)}&limit=60`, { signal }).catch(() => null);
        if (!res || !res.ok) res = await fetch(`/api.php?q=${encodeURIComponent(trimmedQuery)}&limit=60`, { signal }).catch(() => null);
        if (res && res.ok) {
          let data = await res.json();
          if (data && data.songs && data.songs.length > 0) {
            apiResults = apiResults.concat(data.songs);
          }
        }

        if (apiResults.length > 0) {
          const mergedList = [...apiResults, ...songsList];
          renderProcessedResults(mergedList, trimmedQuery, bibleInfo, false);
        }
      } catch (err) {
      }
    }, 30);
  }

  function renderProcessedResults(rawSongsList, query, bibleInfo, isApiPending = false) {
    const uniqueMap = new Map();
    rawSongsList.forEach(song => {
      if (song && (song.id !== undefined && song.id !== null)) {
        const isBible = Boolean((song.is_bible === true || song.is_bible === '1' || song.is_bible === 1) || (song.chapter_number !== undefined && song.chapter_number !== null && song.chapter_number !== ''));
        const key = (isBible ? 'bible_' : 'song_') + song.id;
        uniqueMap.set(key, song);
      }
    });

    const uniqueSongs = Array.from(uniqueMap.values());

    const scored = uniqueSongs.map(song => {
      let score = song._score !== undefined ? song._score : getMatchScore(song, query);
      return {
        ...song,
        _score: score
      };
    }).sort((a, b) => b._score - a._score);

    if (bibleInfo && bibleInfo.bookName) {
      const targetBookNorm = normalizeArabic(bibleInfo.bookName);
      const targetCh = bibleInfo.chapter ? String(bibleInfo.chapter) : '';

      const exactBibleMatches = scored.filter(s => {
        const isItemBible = Boolean((s.is_bible === true || s.is_bible === '1' || s.is_bible === 1) || (s.chapter_number !== undefined && s.chapter_number !== null && s.chapter_number !== ''));
        if (!isItemBible) return false;
        const sTitleNorm = normalizeArabic(s.title || '');
        if (!sTitleNorm.includes(targetBookNorm)) return false;
        if (targetCh && s.chapter_number !== undefined && s.chapter_number !== null && s.chapter_number !== '') {
          return String(s.chapter_number) === targetCh;
        }
        return true;
      });

      if (exactBibleMatches.length > 0) {
        const dedupBibleMap = new Map();
        exactBibleMatches.forEach(b => {
          const normTitle = normalizeArabic(b.title || '');
          if (!dedupBibleMap.has(normTitle)) {
            dedupBibleMap.set(normTitle, b);
          }
        });
        const cleanBibleOnly = Array.from(dedupBibleMap.values());
        renderSearchDropdown(cleanBibleOnly, query, 15, isApiPending);
        return;
      }
    }

    renderSearchDropdown(scored, query, 15, isApiPending);
  }

  let activeSearchLimit = 15;

  function renderSearchDropdown(songs, query, displayLimit = 15, isApiPending = false) {
    activeSearchLimit = displayLimit;
    
    // Resolve Franco query to translated Arabic for accurate lyric matching & highlighting
    const isFrancoInput = Boolean(state.francoAutoTranslate) && /[a-z]/i.test(query) && !/[\u0600-\u06FF]/.test(query);
    const qFrancoVariants = isFrancoInput 
      ? (typeof francoToArabicVariants === 'function' ? francoToArabicVariants(query) : [francoToArabic(query)].filter(Boolean))
      : [];
    const effectiveArabicQuery = isFrancoInput && qFrancoVariants.length > 0 ? qFrancoVariants[0] : query;
    const qNorm = normalizeArabic(effectiveArabicQuery);
    const qWords = qNorm.split(/\s+/).filter(w => w.length >= 2 || (qNorm.length < 3 && w.length >= 1));

    // Also include any secondary Franco variant words for highlighting
    const allQueryVariants = [qNorm, ...qFrancoVariants.map(normalizeArabic)].filter(Boolean);
    const allHighlightWords = Array.from(new Set(allQueryVariants.flatMap(v => v.split(/\s+/)).filter(w => w && (w.length >= 2 || (qNorm.length < 3 && w.length >= 1)))));

    let francoHeaderHtml = '';
    if (state.francoAutoTranslate && isFrancoInput) {
      const rawTranslated = qFrancoVariants[0] || francoToArabic(query);
      if (rawTranslated) {
        francoHeaderHtml = `<div class="franco-translation-header"><i class="icon-star-sparkle" style="display:inline-block; vertical-align:-1px; margin-left:6px; color:#2563eb;"></i> <strong>${escapeHtml(rawTranslated)}</strong></div>`;
      }
    }

    let suggestionBannerHtml = '';
    const spellingVariants = (typeof generateArabicSpellingVariants === 'function')
      ? generateArabicSpellingVariants(effectiveArabicQuery)
      : [];

    if (spellingVariants.length > 0) {
      const topVar = spellingVariants[0];
      suggestionBannerHtml = `
        <div class="search-did-you-mean-banner" data-val="${escapeHtml(topVar)}">
          <div class="suggestion-text">
            <i class="icon-star-sparkle" style="color:#2563eb; margin-left:6px;"></i>
            <span>هل تقصد: <strong class="clickable-suggestion-word" data-val="${escapeHtml(topVar)}" title="اضغط للاستبدال والبحث">${escapeHtml(topVar)}</strong>؟</span>
          </div>
        </div>
      `;
    }

    const dropdownPrefixHtml = suggestionBannerHtml + francoHeaderHtml;

    if (!songs || songs.length === 0) {
      if (isApiPending) {
        els.searchDropdown.innerHTML = dropdownPrefixHtml + `<div class="search-item no-results-item"><i class="fa-solid fa-spinner fa-spin" style="color:#2563eb; margin-left:8px;"></i><span class="item-title">جاري البحث...</span></div>`;
      } else {
        const emptyContentHtml = `
          <div class="search-item no-results-item" style="flex-direction:column; align-items:center; gap:8px; padding:16px 12px; text-align:center;">
            <div style="display:flex; align-items:center; gap:6px; color:#64748b; font-size:0.9rem;">
              <i class="fa-solid fa-circle-exclamation"></i>
              <span>لم يتم العثور على ترنيمة أو شاهد كتابي</span>
            </div>
            <button type="button" id="btn-quick-add-from-search" class="btn btn-sm btn-primary search-quick-add-btn" style="margin-top:4px; font-size:0.84rem; padding:8px 16px; font-weight:700; background:#2563eb; color:#fff; border-radius:10px; border:none; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:0 2px 8px rgba(37,99,235,0.25);">
              <i class="fa-solid fa-circle-plus"></i> إضافة ترنيمة جديدة باسم "${escapeHtml(query)}"
            </button>
          </div>
        `;

        els.searchDropdown.innerHTML = dropdownPrefixHtml + emptyContentHtml;

        const btnQuickAdd = els.searchDropdown.querySelector('#btn-quick-add-from-search');
        if (btnQuickAdd) {
          btnQuickAdd.addEventListener('click', (e) => {
            e.stopPropagation();
            els.searchDropdown.classList.add('hidden');
            openCustomSongEditor({ title: query.trim() });
          });
        }
      }
    } else {
      const visibleSongs = songs.slice(0, activeSearchLimit);
      state.lastSearchResultSongs = visibleSongs;
      const remainingCount = songs.length - visibleSongs.length;

      const itemsHtml = visibleSongs.map(s => {
        const allLines = getSongAllLines(s);
        const isBibleItem = Boolean((s.is_bible === true || s.is_bible === '1' || s.is_bible === 1) || (s.chapter_number !== undefined && s.chapter_number !== null && s.chapter_number !== '') || s.type === 'bible');
        const isCustomItem = Boolean(s.is_custom || (s.id && String(s.id).startsWith('custom_')));

        // Highlighted title
        const titleHighlighted = highlightMatches(s.title || '', qNorm, allHighlightWords);

        // Check whether match was in title or lyrics/slides
        const titleNorm = normalizeArabic(s.title || '');
        const matchIsInTitle = qNorm && (titleNorm.includes(qNorm) || (allHighlightWords.length > 1 && allHighlightWords.every(w => titleNorm.includes(w))));
        const matchIsInLyrics = allLines.length > 0;

        // Build lyric preview snippet
        let snippetHtml = '';
        let matchedLineIdx = -1;
        let isConsecutiveMatch = false;
        let matchedLineText = '';

        if (allLines.length > 0) {
          try {
            const bestMatch = findBestLyricMatch(allLines, qNorm, allHighlightWords);
            if (bestMatch) {
              matchedLineIdx = bestMatch.idx;
              matchedLineText = bestMatch.matchedLine || '';
              isConsecutiveMatch = Boolean(bestMatch.isConsecutive);
              const startIdx = Math.max(0, bestMatch.idx - 1);
              const previewSlice = allLines.slice(startIdx, startIdx + 3);

              snippetHtml = previewSlice.map((line, idx) => {
                const lineNum = startIdx + idx + 1;
                const isMatchedLine = (startIdx + idx) === bestMatch.idx;
                const formattedLine = isMatchedLine
                  ? highlightMatches(line, qNorm, allHighlightWords)
                  : escapeHtml(line);
                
                // Show verse or line badge
                const numBadge = isMatchedLine
                  ? `<span class="line-num-mini matched-line-badge">${isBibleItem ? 'آية' : lineNum}</span>`
                  : `<span class="line-num-mini">${lineNum}</span>`;
                return `${numBadge} ${formattedLine}`;
              }).join('<span class="preview-sep">•</span>');
            } else {
              snippetHtml = allLines.slice(0, 2).map((l, i) => `<span class="line-num-mini">${i + 1}</span> ${escapeHtml(l)}`).join('<span class="preview-sep">•</span>');
            }
          } catch (err) {
            snippetHtml = escapeHtml(allLines.slice(0, 2).join(' • '));
          }
        }

        // Badges:
        const typeBadge = isBibleItem
          ? `<span class="item-badge bible-badge"><i class="fa-solid fa-book-open"></i> شاهد كتابي</span>`
          : (isCustomItem
              ? `<span class="item-badge custom-song-badge"><i class="fa-solid fa-user-pen"></i> مضافة محلياً</span>`
              : `<span class="item-badge"><i class="fa-solid fa-music"></i> ترنيمة</span>`);

        let matchBadge = '';
        if (isConsecutiveMatch) {
          matchBadge = `<span class="item-badge lyrics-match-badge" style="background:#dbeafe; color:#1d4ed8; border-color:#93c5fd;"><i class="icon-star-sparkle"></i> تطابق متتالي</span>`;
        } else if (!matchIsInTitle && matchedLineIdx >= 0) {
          matchBadge = `<span class="item-badge lyrics-match-badge"><i class="fa-solid fa-align-left"></i> في الكلمات</span>`;
        }

        return `
          <div class="search-item" data-id="${s.id || s.item_id}" data-is-bible="${isBibleItem ? '1' : '0'}" data-matched-line="${escapeHtml(matchedLineText)}" data-matched-idx="${matchedLineIdx}">
            <div class="item-top">
              <span class="item-title">${titleHighlighted}</span>
              <div class="item-badges-group">
                ${matchBadge}
                ${typeBadge}
              </div>
            </div>
            ${snippetHtml ? `<div class="item-preview-box preview-expandable">${snippetHtml}</div>` : ''}
          </div>
        `;
      }).join('');

      let loadMoreBtnHtml = '';
      if (remainingCount > 0) {
        const nextChunk = Math.min(15, remainingCount);
        loadMoreBtnHtml = `
          <button type="button" id="btn-search-load-more" class="search-load-more-btn">
            <i class="fa-solid fa-circle-chevron-down"></i>
            عرض المزيد من النتائج (+${nextChunk} من ${remainingCount} متبقية)
          </button>
        `;
      }

      const footerAddHtml = `
        <div class="search-dropdown-footer-add">
          <span class="search-footer-add-hint">لم تجد ترنيمتك في النتائج؟</span>
          <button type="button" id="btn-search-footer-add" class="btn-search-footer-add">
            <i class="fa-solid fa-circle-plus"></i> إضافة ترنيمة جديدة باسم "${escapeHtml(query)}"
          </button>
        </div>
      `;

      els.searchDropdown.innerHTML = dropdownPrefixHtml + itemsHtml + loadMoreBtnHtml + footerAddHtml;
    }

    els.searchDropdown.classList.remove('hidden');

    const btnFooterAdd = els.searchDropdown.querySelector('#btn-search-footer-add');
    if (btnFooterAdd) {
      btnFooterAdd.addEventListener('click', (e) => {
        e.stopPropagation();
        els.searchDropdown.classList.add('hidden');
        openCustomSongEditor({ title: query.trim() });
      });
    }

    els.searchDropdown.querySelectorAll('.search-did-you-mean-banner, .clickable-suggestion-word').forEach(el => {
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        const wordEl = el.classList.contains('clickable-suggestion-word') ? el : el.querySelector('.clickable-suggestion-word');
        const newVal = wordEl ? wordEl.dataset.val : el.dataset.val;
        if (!newVal) return;
        els.intelligentSearch.value = newVal;
        els.intelligentSearch.focus();
        renderSearchWordSuggestions(newVal);
        performIntelligentSearch(newVal);
      });
    });



    els.searchDropdown.querySelectorAll('.btn-toggle-item-preview').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const searchItem = btn.closest('.search-item');
        if (!searchItem) return;
        const previewBox = searchItem.querySelector('.item-preview-box');
        if (previewBox) {
          const isHidden = previewBox.classList.contains('hidden');
          if (isHidden) {
            previewBox.classList.remove('hidden');
            btn.classList.add('active');
            btn.innerHTML = `<i class="fa-solid fa-chevron-up"></i> طي`;
          } else {
            previewBox.classList.add('hidden');
            btn.classList.remove('active');
            btn.innerHTML = `<i class="fa-solid fa-chevron-down"></i> معاينة`;
          }
        }
      });
    });

    els.searchDropdown.querySelectorAll('.search-item').forEach((item, idx) => {
      item.addEventListener('click', () => {
        const id = item.dataset.id;
        const isBible = item.dataset.isBible === '1';
        if (!id) return;
        const currentQuery = (els.intelligentSearch.value || query || '').trim();
        const matchedText = item.dataset.matchedLine || '';
        const matchedIdx = parseInt(item.dataset.matchedIdx);

        els.searchDropdown.classList.add('hidden');
        els.intelligentSearch.value = '';
        els.clearSearchBtn.classList.add('hidden');
        const matchedSong = state.lastSearchResultSongs ? state.lastSearchResultSongs[idx] : null;

        const searchTarget = {
          query: currentQuery,
          matchedLine: matchedText,
          matchedIdx: !isNaN(matchedIdx) ? matchedIdx : -1,
          isBible: isBible
        };

        if (matchedSong) {
          openAndPresentItem(matchedSong, isBible, searchTarget);
        } else {
          openAndPresentItem(id, isBible, searchTarget);
        }
      });
    });

    const btnLoadMore = els.searchDropdown.querySelector('#btn-search-load-more');
    if (btnLoadMore) {
      btnLoadMore.addEventListener('click', (e) => {
        e.stopPropagation();
        renderSearchDropdown(songs, query, activeSearchLimit + 15);
      });
    }
  }




  function hasCompleteContent(obj) {
    if (!obj || typeof obj !== 'object') return false;
    const isBible = Boolean((obj.is_bible === true || obj.is_bible === '1' || obj.is_bible === 1) || (obj.chapter_number !== undefined && obj.chapter_number !== null && obj.chapter_number !== '') || obj.type === 'bible');
    
    if (obj.verses && Array.isArray(obj.verses) && obj.verses.length > 0) return true;
    if (obj.slides && Array.isArray(obj.slides) && obj.slides.length > 0) return true;
    
    if (isBible) {
      const txt = String(obj.notes || obj.text || obj.content || '').trim();
      const titleTxt = String(obj.title || '').trim();
      if (!txt || txt === titleTxt) return false;
      const lines = txt.split('\n').filter(l => l.trim().length > 0);
      if (lines.length < 2 && txt.length < 100) return false;
      return true;
    }

    if (obj.notes && String(obj.notes).trim().length > 0) return true;
    if (obj.text && String(obj.text).trim().length > 0) return true;
    return false;
  }


  async function ensureBibleChaptersLoaded() {
    if (state.bibleChaptersData && Object.keys(state.bibleChaptersData).length > 0) {
      return state.bibleChaptersData;
    }
    if (bibleChaptersLoadingPromise) {
      return await bibleChaptersLoadingPromise;
    }

    bibleChaptersLoadingPromise = (async () => {
      try {
        // 1. Check IndexedDB first (0ms offline!)
        if (typeof TaranimDB !== 'undefined') {
          const dbData = await TaranimDB.get('bible_chapters_data');
          if (dbData && typeof dbData === 'object' && Object.keys(dbData).length > 0) {
            state.bibleChaptersData = dbData;
            return dbData;
          }
        }

        // 2. Check Cache API
        if ('caches' in window) {
          const keys = await caches.keys().catch(() => []);
          for (const key of keys) {
            const cache = await caches.open(key).catch(() => null);
            if (cache) {
              const res = await cache.match('bible_chapters_data.json', { ignoreSearch: true }).catch(() => null) ||
                          await cache.match('./bible_chapters_data.json', { ignoreSearch: true }).catch(() => null);
              if (res && res.ok) {
                const data = await res.json().catch(() => null);
                if (data && Object.keys(data).length > 0) {
                  state.bibleChaptersData = data;
                  if (typeof TaranimDB !== 'undefined') TaranimDB.set('bible_chapters_data', data);
                  return data;
                }
              }
            }
          }
        }

        const pathDir = window.location.pathname.replace(/\/[^\/]*$/, '/');
        let res = await fetch('./bible_chapters_data.json').catch(() => null);
        if (!res || !res.ok) res = await fetch('bible_chapters_data.json').catch(() => null);
        if (!res || !res.ok) res = await fetch(`${window.location.origin}${pathDir}bible_chapters_data.json`).catch(() => null);

        if (res && res.ok) {
          const data = await res.json().catch(() => null);
          if (data && Object.keys(data).length > 0) {
            state.bibleChaptersData = data;
            if (typeof TaranimDB !== 'undefined') TaranimDB.set('bible_chapters_data', data);
            return data;
          }
        }
      } catch (err) {}
      return null;
    })();

    return await bibleChaptersLoadingPromise;
  }

  async function openAndPresentItem(songOrId, isBible = false, searchTarget = null) {
    if (!songOrId && songOrId !== 0) return;

    let inputObject = (typeof songOrId === 'object' && songOrId !== null) ? songOrId : null;
    let rawSongId = inputObject ? (inputObject.id !== undefined ? inputObject.id : inputObject.item_id) : songOrId;
    let isItemBible = Boolean(isBible || (inputObject && ((inputObject.is_bible === true || inputObject.is_bible === '1' || inputObject.is_bible === 1) || (inputObject.chapter_number !== undefined && inputObject.chapter_number !== null && inputObject.chapter_number !== ''))));
    
    if (!searchTarget && inputObject && inputObject._searchTarget) {
      searchTarget = inputObject._searchTarget;
    }

    // Auto-apply assigned default template for Taranim or Bible
    applyAssignedDefaultTemplate(isItemBible);

    const cleanId = String(rawSongId || '').replace(/^(song_|bible_)/, '').trim();

    let targetSong = inputObject ? JSON.parse(JSON.stringify(inputObject)) : null;
    let originSource = inputObject ? 'direct_object_parameter' : 'unknown';

    // 0. BIBLE LOCAL MEMORY LOOKUP (INSTANT 0ms FOR ALL 1,189 BIBLE CHAPTERS)
    if (isItemBible) {
      let bId = (inputObject && inputObject.book_id !== undefined && inputObject.book_id !== null && inputObject.book_id !== '') ? inputObject.book_id : (inputObject && inputObject.book ? inputObject.book : '');
      let cNum = (inputObject && inputObject.chapter_number !== undefined && inputObject.chapter_number !== null && inputObject.chapter_number !== '') ? inputObject.chapter_number : (inputObject && inputObject.chapter !== undefined ? inputObject.chapter : '');
      
      if (!bId || !cNum) {
        const m = String(rawSongId || '').match(/^(?:bible_)?(\d+)_(\d+)$/);
        if (m) {
          bId = m[1];
          cNum = m[2];
        }
      }

      if (bId && cNum) {
        await ensureBibleChaptersLoaded();

        const cacheKey = `${bId}_${cNum}`;
        let localChapter = null;

        if (state.bibleChaptersData && state.bibleChaptersData[cacheKey]) {
          localChapter = JSON.parse(JSON.stringify(state.bibleChaptersData[cacheKey]));
        }

        if (localChapter && hasCompleteContent(localChapter)) {
          localChapter.is_bible = true;
          localChapter.book_id = parseInt(bId);
          localChapter.chapter_number = parseInt(cNum);
          state.activeSong = localChapter;
          addToSessionRecents(localChapter);
          loadSongIntoPresentation(localChapter, true, false, searchTarget);
          return;
        }
      }
    }

    // 1. MATCH IN SESSION RECENTS BY ID IF NOT COMPLETE
    if ((!targetSong || !hasCompleteContent(targetSong)) && cleanId) {
      let foundInRecents = state.sessionRecents.find(r => {
        const rId = String(r.id !== undefined ? r.id : r.item_id).replace(/^(song_|bible_)/, '').trim();
        return Boolean(r.is_bible) === Boolean(isItemBible) && rId === cleanId && hasCompleteContent(r);
      });
      if (foundInRecents) {
        targetSong = JSON.parse(JSON.stringify(foundInRecents));
        originSource = 'session_recents_lookup';
      }
    }

    // 2. MATCH OR ENRICH BY ID IN CANONICAL CATALOG FAST INDEX
    if (!isItemBible && (!targetSong || !hasCompleteContent(targetSong)) && cleanId && state.allSongs && state.allSongs.length > 0) {
      let canonicalSong = state.allSongs.find(s => {
        if (s.is_bible) return false;
        const sId = String(s.id !== undefined ? s.id : s.item_id).replace(/^(song_|bible_)/, '').trim();
        return sId === cleanId;
      });
      if (canonicalSong) {
        if (!targetSong) {
          targetSong = JSON.parse(JSON.stringify(canonicalSong));
          originSource = 'canonical_catalog_lookup';
        } else {
          if (!targetSong.notes && canonicalSong.notes) targetSong.notes = canonicalSong.notes;
          if (!targetSong.title && canonicalSong.title) targetSong.title = canonicalSong.title;
          if ((!targetSong.verses || !Array.isArray(targetSong.verses) || targetSong.verses.length === 0)
              && canonicalSong.verses && Array.isArray(canonicalSong.verses) && canonicalSong.verses.length > 0) {
            targetSong.verses = JSON.parse(JSON.stringify(canonicalSong.verses));
            originSource += '_enriched_verses_from_catalog';
          }
        }
      }
    }

    // 2.1 OFFLINE INDEXEDDB LOOKUP FALLBACK
    if (!isItemBible && (!targetSong || !hasCompleteContent(targetSong)) && cleanId && typeof TaranimDB !== 'undefined') {
      try {
        const storedCatalog = await TaranimDB.get('songs_catalog');
        if (Array.isArray(storedCatalog)) {
          const found = storedCatalog.find(s => String(s.id) === cleanId || String(s.item_id) === cleanId);
          if (found) {
            targetSong = JSON.parse(JSON.stringify(found));
            originSource = 'indexeddb_catalog_lookup';
          }
        }
      } catch(e) {}
    }

    // 3. INSTANT 0ms UI PRESENTATION (IF TARGET SONG IS COMPLETE)
    if (targetSong && hasCompleteContent(targetSong)) {
      const readySong = ensureSongVerses(targetSong);
      state.activeSong = readySong;
      addToSessionRecents(readySong);
      loadSongIntoPresentation(readySong, true, false, searchTarget);
    }

    // 4. PARALLEL API FETCH (Enrichment / Full Verses Loading)
    if (!targetSong || !hasCompleteContent(targetSong)) {
      try {
        const apiUrl = getApiUrl();
        let endpoints = [];
        if (isItemBible) {
          let bId = (inputObject && inputObject.book_id !== undefined) ? inputObject.book_id : (inputObject && inputObject.book ? inputObject.book : '');
          let cNum = (inputObject && inputObject.chapter_number !== undefined) ? inputObject.chapter_number : (inputObject && inputObject.chapter !== undefined ? inputObject.chapter : '');
          
          if (!bId || !cNum) {
            const m = String(rawSongId || '').match(/^bible_(\d+)_(\d+)$/);
            if (m) {
              bId = m[1];
              cNum = m[2];
            }
          }

          if (bId && cNum) {
            const pathDir = window.location.pathname.replace(/\/[^\/]*$/, '/');
            endpoints.push(`api.php?action=bible_chapter&book_id=${bId}&chapter=${cNum}`);
            endpoints.push(`./api.php?action=bible_chapter&book_id=${bId}&chapter=${cNum}`);
            endpoints.push(`${window.location.origin}${pathDir}api.php?action=bible_chapter&book_id=${bId}&chapter=${cNum}`);
            endpoints.push(`${apiUrl}?action=bible_chapter&book_id=${bId}&chapter=${cNum}`);
            endpoints.push(`/api.php?action=bible_chapter&book_id=${bId}&chapter=${cNum}`);
          } else if (cleanId && !isNaN(parseInt(cleanId))) {
            endpoints.push(`api.php?action=song&id=${cleanId}&type=bible&is_bible=1`);
            endpoints.push(`./api.php?action=song&id=${cleanId}&type=bible&is_bible=1`);
            endpoints.push(`${apiUrl}?action=song&id=${cleanId}&type=bible&is_bible=1`);
            endpoints.push(`/api.php?action=song&id=${cleanId}&type=bible&is_bible=1`);
          }
        } else if (cleanId && !isNaN(parseInt(cleanId))) {
          endpoints.push(`api.php?action=song&id=${cleanId}`);
          endpoints.push(`./api.php?action=song&id=${cleanId}`);
          endpoints.push(`${apiUrl}?action=song&id=${cleanId}`);
          endpoints.push(`/api.php?action=song&id=${cleanId}`);
        }

        if (endpoints.length > 0) {
          const fetchPromises = endpoints.map(url => 
            fetch(url)
              .then(r => r.ok ? r.json() : null)
              .catch(() => null)
          );

          const results = await Promise.all(fetchPromises);
          let fullSong = results.find(data => data && (
            (data.verses && Array.isArray(data.verses) && data.verses.length > 0) ||
            (data.notes && String(data.notes).trim().length > 0) ||
            (data.text && String(data.text).trim().length > 0) ||
            (data.slides && Array.isArray(data.slides) && data.slides.length > 0)
          ));

          // OFFLINE BIBLE CHAPTER FALLBACK IF ENDPOINTS RETURN NO VERSES
          if (!fullSong && isItemBible) {
            let bId = (inputObject && inputObject.book_id !== undefined) ? inputObject.book_id : '';
            let cNum = (inputObject && inputObject.chapter_number !== undefined) ? inputObject.chapter_number : '';
            if (!bId || !cNum) {
              const m = String(rawSongId || '').match(/^bible_(\d+)_(\d+)$/);
              if (m) { bId = m[1]; cNum = m[2]; }
            }
            if (bId && cNum) {
              if (!state.bibleChaptersData) {
                try {
                  const pathDir = window.location.pathname.replace(/\/[^\/]*$/, '/');
                  let bRes = await fetch('./bible_chapters_data.json').catch(() => null);
                  if (!bRes || !bRes.ok) bRes = await fetch(`${window.location.origin}${pathDir}bible_chapters_data.json`).catch(() => null);
                  if (!bRes || !bRes.ok) bRes = await fetch('bible_chapters_data.json').catch(() => null);
                  if (bRes && bRes.ok) state.bibleChaptersData = await bRes.json();
                } catch(e) {}
              }
              const cacheKey = `${bId}_${cNum}`;
              if (state.bibleChaptersData && state.bibleChaptersData[cacheKey]) {
                fullSong = JSON.parse(JSON.stringify(state.bibleChaptersData[cacheKey]));
              }
            }
          }

          if (fullSong) {
            targetSong = fullSong;
            if (isItemBible) targetSong.is_bible = true;
            const finalSong = ensureSongVerses(targetSong);
            state.activeSong = finalSong;
            addToSessionRecents(finalSong);
            loadSongIntoPresentation(finalSong, true, false, searchTarget);
            return;
          }
        }
      } catch (err) {}
    }

    // 5. SAFE FALLBACK (IF API IS OFFLINE / UNREACHABLE & NO SONG PRESENTED YET)
    if (!state.activeSong && (inputObject || cleanId)) {
      targetSong = inputObject || {
        id: cleanId,
        title: isItemBible ? `سفر - أصحاح ${cleanId}` : `ترنيمة ${cleanId}`,
        is_bible: isItemBible
      };
      const fallbackSong = ensureSongVerses(targetSong);
      state.activeSong = fallbackSong;
      addToSessionRecents(fallbackSong);
      loadSongIntoPresentation(fallbackSong, true, false, searchTarget);
    }

    console.log('Resolved targetSong origin:', originSource, targetSong);

    if (targetSong) {
      targetSong = ensureSongVerses(targetSong);
      state.activeSong = targetSong;
      addToSessionRecents(targetSong);
      loadSongIntoPresentation(targetSong, true, false, searchTarget);
    } else {
      showToast('تعذر تحميل بيانات العنصر.');
    }
  }

